XX. CONTRATACIÓN ADMINISTRATIVA DE SERVICIOS (CAS)
La contratación administrativa de servicios, conocida como CAS, es un régimen laboral del
Sector Público en el Perú que se pretende eliminar progresivamente.
1. Antecedentes
1. Con fecha 28 de junio de 2008, se publica en el Diario Oficial El Peruano el Decreto Legisla
tivo 1057- Decreto Legislativo que regula el régimen especial de contratación administrativa
de servicios - cuya finalidad es regular el régimen especial de contratación adm inistrativa
