2 . ¿Qué es la contratación administrativa de servicios?
El régimen especial de contratación administrativa de servicios (CAS) es aplicable a toda en
tidad pública sujeta al Decreto Legislativo 276, Ley de Bases de la Carrera Administrativa y de
Remuneraciones del Sector Público, y a otras normas que regulan carreras administrativas es
peciales; asimismo, a las entidades públicas sujetas al régimen laboral de la actividad privada,
con excepción de las empresas del Estado, el Seguro Social de Salud (ESSALUD), y los guar-
daparques del Servicio Nacional de Áreas Naturales Protegidas porel Estado (SERNANP)16.
De esta manera, el Contrato Administrativo de Servicios constituye una modalidad especial
de contratación laboral privativa del Estado, no se encuentra sujeto a la Ley de Bases de la
Carrera Administrativa, el régimen laboral de la actividad privada ni a otras normas que regu
lan carreras administrativas especiales; el Régimen Laboral Especial del Decreto Legislativo
1057 tiene carácter transitorio17. El contrato administrativo de servicios es de tiempo indeter
minado, salvo que se utilice para labores de necesidad transitoria o de suplencia18, tampoco
será indeterminado cuando se refiera a trabajadores de confianza.
Asimismo, al trabajador sujeto a contrato administrativo de servicios le son aplicables, en lo
que resulte pertinente, la Ley 28175, Ley Marco del Empleo Público; la Ley 27815, Ley del Código
de Etica de la Función Públicay las demás normas de carácter general que regulen el Servicio
Civil, los topes de ingresos mensuales, la responsabilidad administrativa funcional y/o que
establezcan los principios, deberes, obligaciones, incompatibilidades, prohibiciones, infrac-
cionesy sanciones aplicables al servicio, función o cargo para el que fue contratado; quedando
sujeto a las estipulaciones del contratoy a las normas internas de la entidad empleadora19.
