3. Requisitos para la celebración del contrato CAS
Son requisitos para la celebración del contrato administrativo de servicios21-.
1. Requerimiento realizado por la dependencia usuaria.
2. Existencia de disponibilidad presupuestaria, determinada por la oficina de presupuesto
de la entidad o quien haga sus veces.
3. No contar con sentencia condenatoria consentiday/o ejecutoriada por alguno de los deli
tos previstos en los artículos 296, 296-A pri mer, segundo y cuarto párrafo; 296-B, 297,382,
383, 3 8 4 , 387,388,389, 393, 393''A, 3 9 4 , 395, 3 9 6 , 397, 397''A, 398, 3 9 9 , 400 y 401 del Código
Penal, así como el artículo 4-A del Decreto Ley 25475y los delitos previstos en los artículos
1, 2 y 3 del Decreto Legislativo 1106, o sanción administrativa que acarree inhabilitación,
inscritas en el Registro Nacional de Sanciones contra Servidores Civiles.
4. Concurso público
El acceso al régimen de Contratación Administrativa de Servicios se realiza obligatoriamente
mediante concurso público22 El funcionario público, empleado de confianza y directivo su
perior contratado porel Régimen Laboral Especial del Decreto Legislativo 1057, está excluido
de la realización de concurso público; este personal solo puede ser contratado para ocupar
una plaza orgánica contenida en el Cuadro de Asignación de Personal - CAP de la entidad23.
De conformidad con la Única Disposición Complementaria Transitoria de la Ley 31039, publi
cada el 26 agosto 2020, de manera transitoria a los procesos de incorporación bajo el Decreto
Legislativo 276 y el Decreto Legislativo 728 según corresponda en las diversas entidades pú
blicas del sector salud, se dispone la contratación directa e inmediata, mediante el régimen
especial de contratación administrativa de servicios (CAS), al personal profesional de la salud:
médico, no médico y personal técnico y auxiliar asistencial de la salud del Ministerio de Salud,
Seguro Social de Salud (EsSalud), y Sanidad de las Fuerzas Armadas y Fuerzas Policiales que
se encuentran contratados por la modalidad de servicios de terceros (locación de servicios),
ante el riesgo de contagio de enfermedades altamente infecciosas como el C0 V ID -i9 y otros,
de esta manera, se exonera al Ministerio de Salud, Seguro Social de Salud (EsSalud),y Sanidad
de las Fuerzas Armadasy Fuerzas Policiales, del concurso público, para la contratación directa
e inmediata de los contratados por servicios de terceros.
