5. Procedimiento de contratación
Para suscribir un contrato administrativo de servicios las entidades públicas deben observar
un procedimiento que incluye las siguientes etapas24:
1. Preparatoria. Comprende el requerimiento del órgano o unidad orgánica usuaria, que
incluye la descripción del servicio a realizary los requisitos mínimos y las competencias
que debe reunir el postulante, así como la descripción de las etapas del procedimiento, la
justificación de la necesidad de contratación y la disponibilidad presupuestaria determ i
nada por la oficina de presupuesto o la que haga sus veces de la entidad.
2. Convocatoria Comprende la publicación de la convocatoria en el portal institucional, en
un lugar visible de acceso público del local o de la sede central de la entidad convocante
sin perjuicio de utilizarse, a criterio de la entidad convocante, otros medios de informa
ción adicionales para difundir la convocatoria. La publicación de la convocatoria debe ha-
cersey mantenerse desde, cuando menos, cinco (5) días hábiles previos al inicio de la eta
pa de selección. Debe incluir el cronogramay etapas del procedimiento de contratación,
los mecanismos de evaluación, los requisitos mínimos a cumplir por el postulante y las
condiciones esenciales del contrato, entre ellas, el lugar en el que se prestará el servicio, el
plazo de duración del contrato y el monto de la retribución a pagar.
3. Selección. Comprende la evaluación objetiva del postulante. Dada la especialidad del
régimen, se realiza, necesariamente, mediante evaluación curriculary entrevista, siendo
opcional para las entidades aplicar otros mecanismos, como la evaluación psicológica, la
evaluación técnica o la evaluación de competencias específicas, que se adecúen a las ca
racterísticas del servicio materia de la convocatoria. La evaluación se realiza tomando en
consideración los requisitos relacionados con las necesidades del servicio y garantizando
los principios de mérito, capacidad e igualdad de oportunidades. El resultado de la eva
luación, en cada una de sus etapas, se publica a través de los mismos medios utilizados
para publicar la convocatoria, en forma de lista por orden de mérito, que debe contener
los nombres de los postulantesy los puntajes obtenidos porcada uno de ellos.
4. Suscripción y registro del contrato. Comprende la suscripción del contrato dentro de un
plazo no mayor de cinco días hábiles, contados a partir del día siguiente de la publicación
de los resultados. Si vencido el plazo el seleccionado no suscribe el contrato por causas
objetivas imputables a él, se debe declarar seleccionada a la persona que ocupa el orden
de mérito inmediatamente siguiente, para que proceda a la suscripción del respectivo
contrato dentro del mismo plazo, contado a partir de la respectiva notificación. De no
suscribirse el contrato por las mismas consideraciones anteriores, la entidad convocante
puede declarar seleccionada a la persona que ocupa el orden de mérito inmediatamen
te siguiente o declarar desierto el proceso. Una vez suscrito el contrato, la entidad tiene
cinco días hábiles para ingresarlo al registro de contratos administrativos de servicios de
cadaentidady a la planilla electrónica.
