6. Derechos de los trabajadores CAS
El Contrato Administrativo de Servicios otorga al trabajador los siguientes derechos25:
a) Percibir una remuneración no menor a la remuneración mínima legalmente establecida.
b) Jornada máxima de ocho (8) horas diarias o cuarenta y ocho (48) horas semanales.
c) Descanso semanal obligatorio de veinticuatro (24) horas consecutivas como mínimo.
d) Un tiempo de refrigerio, que no forma parte de la jornada de trabajo.
e) Aguinaldo por Fiestas Patriasy Navidad, conforme a los montos establecidos en las leyes
anuales de presupuesto del sector público.
f) Vacaciones remuneradas de treinta (30) días naturales.
g) Ucencias con goce de haber por maternidad, paternidad, y otras licencias a las que tienen
derecho los trabajadores de los regímenes laborales generales.
h) Gozar de los derechos a que hace referencia la Ley 29783, Ley de Seguridad y Salud en el
Trabajo.
i) A la libertad sindical.
j) A afiliarse a un régimen de pensiones, pudiendo elegir entre el Sistema Nacional de Pen
siones o el Sistema Privado de Pensiones,y cuando corresponda, afiliarse al Seguro Com
plementario de Trabajo de Riesgo.
I<) Afiliación al régimen contributivo que administra EsSalud.
I) Recibir al término del contrato un certificado de trabajo.
7. Obligaciones y responsabilidades administrativas
Son aplicables al trabajador sujeto al Régimen Laboral Especial del Decreto Legislativo 1057,
en lo que resulte pertinente, la Ley 28175, Ley Marco del Empleo Público; la Ley 27815, Ley del
Código de Ética de la Fundón Pública y las demás normas de carácter general que regulen el
servicio civil, los topes de ingresos mensuales, la responsabilidad administrativa funcional y/o
las disposiciones que establezcan los principios, deberes, obligaciones, incompatibilidades,
prohibiciones, infracciones y sanciones aplicables al servicio, fundón o cargo para el que fue
contratado; quedando sujeto a las estipulaciones del contrato y a las normas internas de la
entidad empleadora26. El procedimiento disciplinario aplicable a los trabajadores del presente
régimen es el previstoen la Ley 3 0 0 5 7 -Ley del Servido Civil27.
