8. Acciones de desplazamiento
Los trabajadores bajo contrato administrativo de servicios pueden, sin que implique la varia-
ción de la retribución o del plazo establecido en el contrato, ejercer la suplencia al interior de
la entidad contratante o quedarsujetos, únicamente, a las siguientes acciones administrativas
de desplazamiento de personal28:
a) La designación temporal, como representante de la entidad contratante ante comisio
nes y grupos de trabajo, como miembro de órganos colegiados y/o como directivo supe
rior o empleado de confianza.
b) La rotación temporal, al interior de la entidad contratante para prestar servicios en un
órgano distinto al que solicitó la contratación, hasta por un plazo máximo de noventa
(90) días calendario durante la vigencia del contrato.
c) La comisión de servicios, para temporal mente realizar funciones fuera de la entidad con
tratante, la que por necesidades del servicio puede requerir el desplazamiento del traba
jador fuera de su provincia de residencia o del país, hasta por un plazo máximo de treinta
(30) días calendario, en cada oportunidad.
9 . Suspensión de las obligaciones del trabajador
Se suspende la obligación de prestación de servicios del trabajador sujeto al régimen del De
creto Legislativo 1057 en los siguientes casos29:
1. Suspensión con contraprestación:
a) Los supuestos regulados en el régimen contributivo de ESSALUD.
b) Por ejercicio del derecho al descanso pre y post natal de noventa (90) días.
c) Por causa fortuita o de fuerza mayor, debidamente comprobada.
d) Por licencia con goce de haber.
e) Por hacer uso del descanso físico semanal, anual y del compensatorio por horas labora
das en sobretiempo.
f) Por fallecimiento de cónyuge, concubina, padres, hijos o hermanos hasta por tres (3) días
pudiendo extenderse hasta (3) tres días más cuando el deceso se produce en provincia
diferente a donde labora el trabajador.
2. Suspensión sin contraprestación. Por hacer uso de permisos personales en forma excep
cional, por causas debidamente justificadas.
10. Extinción del contrato administrativo de servicios
El Contrato Administrativo de Servicios se extingue por30:
a) Fallecimiento.
