11. Desnaturalización de los contratos
Existe invalidez de los contratos administrativos de servicios, de manera enunciativa, en los
siguientes supuestos31:
1. Cuando la relación contractual preexistente tiene su origen en un mandato judicial de re
posición al amparo de la Ley 24041, o por aplicación directa de la norma al caso concreto.
2. Cuando se verifica que previo a la suscripción del contrato CAS, el trabajadortenía una re
lación laboral de tiempo indeterminado por desnaturalización de la contratación modal
empleada.
3. Cuando se verifica que previa a la suscripción del contrato CAS, el locador de servicios
tenía, en los hechos, una relación laboral de tiempo indeterminado encubierta.
4. Si el trabajador inicia sus servicios suscribiendo contrato administrativo deservicios pero
continúa prestando los mismos sin suscribir nuevo contrato CAS, no existe invalidez de
los contratos administrativos de servicios suscritos; sin embargo, esta circunstancia no
origina la prórroga automática del contrato CAS suscrito y se entiende que la relación
laboral posterior fue o es, según sea el caso, una de naturaleza indeterminada.
XXI. RÉGIMEN DEL SERVICIO CIVIL
El régimen laboral del servicio civil tiene por objeto unificar los distintos regímenes laborales
estatales en el Perú, como son el Decreto Legislativo 728, el Decreto Legislativo 276y el Decreto
Legislativo 1057 (CAS).
