Tema 5: Temas de la especialidad laboral
1. Antecedentes
1. Con fecha 04 de julio de 2013 se publica en el Diario Oficial El Peruano la Ley 30057- Ley
del Servicio Civil - que tiene por objeto establecer un régimen únrco y exclusivo para
las personas que prestan servicios en las entidades públicas del Estado, así como para
aquellas personas que están encargadas de su gestión, del ejercicio de sus potestades y
de la prestación de servicios a cargo de estas32.
2. Con fecha 13 de junio de 2014 se publica el Decreto Supremo 040-2014-PCM- Reglamen
to General de la Ley 30057, Ley del Servicio C ivil-q u e tiene por objeto la aplicación gene-
ral de lo dispuesto en la Ley 30057, Ley del Servicio Civil33.
3. Con fe ch a n de junio de 2 0 i 4 se publica el Decreto Supremo 041-2014-PCM-Reglamento
del Régimen Especial para Gobiernos Locales-que tiene por objeto desarrollar las regu
laciones específicas aplicables a la gestión del Servicio Civil para Municipalidades que
cuentan hasta con veinte (20) personas34
4. Con fecha 13 de junio de 2014 se publica el Decreto Supremo 138-2014-EF-Regí amento de
Compensaciones de la Ley 30057, Ley del Servicio C iv il-q u e tiene por objeto establecer
las disposiciones reglamentarias para la valorización y regulación de las compensa
ciones económicas y la determinación de las compensaciones no económicas, estable
cidas en la Ley 30057- Ley del Servicio Civil35.
5. Con fecha 04 de mayo de 2016 se publica la Sentencia del Tribunal Constitucional
del Pleno Jurisdiccional recaído en el Expedientes 0025-2013-PI-TC; 0003-2014-PI-TC;
0008-2014-PI-TC; 0017-2014-PI-TCquese pronuncia sobre laconstitucionalidade incons-
titucionalidad de la Ley 30057.
6 . Este régimen laboral sólo es aplicable a las entidades públicas cuya transición ha sido
aprobada por la Autoridad Nacional del Servicio Civil, verbi gratia, la Oficina de Norm ali
zación Previsional.
El régimen del Servicio Civil se aplica a las entidades públicas de36: a) Poder Ejecutivo, inclu
yendo Ministeriosy Organismos Públicos; b) Poder Legislativo; c) Poder Judicial; d) Gobiernos
Regionales; e) Gobiernos Locales; f) Organismos a los que la Constitución Política del Perúy las
leyes confieren autonomía; y, g) las demás entidadesy organismos, proyectos y programas del
Estado, cuyas actividades se realizan en virtud de potestades administrativas y, por tanto, se
consideran sujetas a las normas comunes de derecho público.
El régimen laboral del servicio civil es un régimen unificado y flexible que sustituirá a los
regímenes laborales del Decreto Legislativo 728, Decreto Legislativo 276 y Decreto Legislativo
1057, incorporando a los trabajadores del Estado al Servicio Civil.
