UBILEX
El sistema administrativo de gestión de recursos humanos establece, desarrol la y ejecuta la
política de Estado respecto del Servicio Civil, a través del conjunto de normas, principios, re
cursos, métodos, procedimientos y técnicas utilizadas por las entidades públicas en la gestión
de los recursos humanos; el sistema está integrado por37: a) Autoridad Nacional del Servicio
Civil (SERVIR); b) oficinas de recursos humanos de las entidades o las que hagan sus veces; c)
Tribunal del Servicio Civil; y, d) Dirección General de Gestión Fiscal de los Recursos Humanos
del Ministerio de Economíay Finanzas.
2. Principios de la ley del servicio civil
Son principios de la Ley del Servicio Civil38:
a) Interés general El régimen del Servicio Civil se fundamenta en la necesidad de recursos
humanos para una adecuada prestación de servicios públicos.
b) Eficacia y eficiencia. El Servicio Civil y su régimen buscan el logro de los objetivos del
Estado y la realización de prestaciones de servicios públicos requeridos por el Estado y la
optimización de los recursos destinados a este fm.
c) Igualdad de oportunidades. Las reglas del Servicio Civil son generales, impersonales,
objetivas, públicas y previamente determinadas, sin discriminación alguna por razones
de origen, raza, sexo, idioma, religión, opinión, condición económica o de cualquier otra
índole.
d) Mérito. El régimen del Servido Civil, incluyendo el acceso, la permanencia, progresión,
mejora en las compensaciones y movilidad, se basa en la aptitud, actitud, desempeño,
capacidady evaluación permanente para el puesto de los postulantes y servidores civiles.
e) Provisión presupuestaria. Todo acto relativo al sistema del Servicio Civil está supeditado
a la disponibilidad presupuestal, el cumplim iento de las reglas fiscales, la sostenibilidad
de las finanzas del Estado, así como a estar previamente autorizado y presupuestado.
f) Legalidady especialidad normativa. El régimen del Servicio Civil se rige únicamente por
lo establecido en la Constitución Política, la Ley 30057y sus normas reglamentarias.
g) Transparencia. La información relativa a la gestión del régimen del Servicio Civil es con
fiable, accesibley oportuna.
h) Rendición de cuentas de la gestión. Los servidores públicos encargados de la gestión de
las entidades públicas rinden cuentas de la gestión que ejecutan.
i) Probidad y ética pública. El Servicio Civil promueve una actuación transparente, ética y
objetiva de los servidores civiles.
j) Flexibilidad. El Servicio Civil procura adaptarse a las necesidades del Estado y de los ad
ministrados.
k) Protección contra el término arbitrario del Servicio Civil. Se otorga al servidor civil ade
cuada protección contra el térm ino arbitrario del Servicio Civil.
