3. Clasificación de los servidores civiles
Los servidores civiles de las entidades públicas se clasifican en los siguientes grupos39-
1. Funcionario público. Es un representante político o cargo público representativo, que
ejerce funciones de gobierno en la organización del Estado. Dirige o interviene en la con
ducción de la entidad, así como aprueba políticas y normas40. Los funcionarios públicos
se clasifican en41:
a) Funcionarlo público de elección popular, directa y universal Es el elegido median
te elección popular, directa y universal, como consecuencia de un proceso electoral
conducido por la autoridad competente parata! fin. El ingreso, permanenciaytérm i-
no de su función están regulados por la Constitución Política del Perúy las leyes de la
materia, verbi gratla, Presidente de la República, Congresistas de la República y del
Parlamento Andino, Alcaldes, Teniente Alcaldes y Regidores.
b) Funcionario público de designación o remoción regulada Es aquel cuyos requisi
tos, proceso de acceso, período de vigencia o causales de remoción están regulados
en norma especial con rango de ley, verbi gratla, Magistrados del Tribunal Constitu
cional, Defensordel Pueblo.
c) Funcionario público de libre designación y remoción. Es aquel cuyo acceso al Ser
vicio Civil se realiza por libre decisión del funcionario público que lo designa, basada
en la confianza para realizar funciones de naturaleza política, normativa o adminis
trativa, verbi gratia, Ministros de Estado, Gerente Municipal.
2. Directivo público. Es el servidor civil que desarrolla funciones relativas a la organización,
dirección o toma de decisiones de un órgano, unidad orgánica, programa o proyecto es
pecial42.
3. Servidor Civil de Carrera. Es el servidor civil que realiza funciones directamente vincu
ladas al cumplim iento de las funciones sustantivas y de administración Interna de una
entidad43.
4 - Servidor de actividades complementarias. Es el servidor civil que realiza funciones indi
rectamente vinculadas al cumplimiento de las funciones sustantivas y de administración
interna de una entidad44.
5. Servidores de confianza. En cualquiera de estos grupos pueden existí r servidores de con
fianza. Es un servidor civil que forma parte del entorno directo e inmediato de los funcio
narios públicos o directivos públicos y cuya permanencia en el Servicio Civil está determi
nada y supeditada a la confianza por parte de la persona que lo designó. Puede form ar
parte del grupo de directivos públicos, servidor civil de carrera, o servidor de actividades
