4. Procesos de personal en el régimen del servicio civil
Los procesos de personal en el régimen del servicio civil son los siguientes:
1. Proceso de selección para incorporación al servicio civil. El proceso de selección es el me
canismo de incorporación al grupo de directivos públicos, servidores civiles de carrera y ser
vidores de actividades complementarias; tiene por finalidad seleccionar a las personas más
idóneas para el puesto sobre la base del mérito, competenciay transparencia, garantizando la
igualdad en el acceso a la función públ ica; en el caso de los servidores de confianza, el proceso
de selección se lim ita al cumplimiento del perfil establecido para el puesto y no requieren
aprobar un concurso público de méritos46. Para participar en un proceso de incorporación al
Servicio Civil se requiere47:
a) Estar en ejercicio pleno de sus derechos civiles.
b) Cumplir con los requisitos mínimos exigidos para el puesto.
c) No tener condena por delito doloso.
d) No estar inhabilitado administrativa o judicialmente para el ejercicio de la profesión,
para contratar con el Estado o para desempeñar función pública.
e) Tener la nacionalidad peruana, en los casos en que la naturaleza del puesto lo exija, con
forme a la Constitución Política del Perú y a las leyes específicas.
f) Los demás requisitos previstos en la Constitución Política del Perúy las leyes.
2. Proceso de capacitación. La finalidad del proceso de capacitación es buscar la mejora
del desempeño de los servidores civiles para brindar servicios de calidad a los ciudada
nos. Asimismo, busca fortalecer y mejorar las capacidades de los servidores civiles para el
buen desempeño y es una estrategia fundamental para alcanzar el logro de los objetivos
institucionales48. Los tipos de capacitación son49:
a) Formación Laboral. Tiene por objeto capacitar a los servidores civiles en cursos, ta
lleres, seminarios, diplomados u otros que no conduzcan a grado académico o tí
tulo profesional y que permitan, en el corto plazo, mejorar la calidad de su trabajo
y de los servicios que prestan a la ciudadanía. Se aplica para el cierre de brechas de
conocimientos o competencias, así como para la mejora continua del servidor civil,
respecto de sus funciones concretas y de las necesidades institucionales.
