Tema 5: Temas de la especialidad laboral
b) Formación Profesional Conlleva a la obtención, principalmente, del grado acadé-
mico de maestrías en áreas requeridas por las entidades. Está destinada a preparar
a los servidores públicos en universidades, institutos y otros centros de formación
profesional y técnica, de primer nivel; atendiendo a la naturaleza de las funciones
que desempeñan y a su formación profesional.
3. Proceso de evaluación de desempeño en la gestión de rendimiento La gestión del rendi
miento comprende el proceso de evaluación de desempeño y tiene por finalidad estimular el
buen rendim ientoy el compromiso del servidor civil. Identificay reconoce el aporte de los ser
vidores con las metas institucionalesy evidencia las necesidades requeridas por los servidores
para mejorar el desempeño en sus puestos y de la entidad50. Están sujetos a evaluación de
desempeño los directivos públicos, los servidores civiles de carreray los servidores de activida
des complementarias51. La evaluación de desempeño es el proceso obligatorio, integral, siste
mático y continuo de apreciación objetivay demostrable del rendimiento del servidor público
en cumplim iento de los objetivos y funciones de su puesto. Es llevada a cabo obligatoriamente
por las entidades públicas en la oportunidad, form ay condiciones que señale el ente rector52.
La evaluación es la base para la progresión en el grupo de servidores civiles de carrera, las com
pensaciones y la determinación de la permanencia en el Servicio Civil. Por la evaluación, se
califica a los servidores como53: a) Personal de rendimiento distinguido; b) Personal de buen
rendimiento; c) Personal de rendimiento sujeto a observación; y, d) Personal desaprobado.
Por otro lado, el desplazamiento de personal es el acto de administración mediante el cual
un servidor civil, por disposición fundamentada de la entidad pública, pasa a desempeñar
temporalmente diferentes funciones dentro o fuera de su entidad, teniendo en consideración
las necesidades del Servicio Civil y el nivel ostentado. Los desplazamientos son54: a) Designa
ción como directivo público o como servidor de confianza; b) Rotación; c) Destaque; d) Encar
go de funciones; y, e) Comisión de servicios.
5. Compensaciones
La compensación es el conjunto de ingresosy beneficios que la entidad destina al servidor civil
para retribuir la prestación de sus servicios a la entidad de acuerdo al puesto que ocupa55. La
compensación se estructura de la siguiente manera56:
a) La compensación económica del puesto es la contraprestación en dinero, correspondien
te a las actividades realizadas en un determinado puesto. La compensación económica
que se otorga a los servidores civiles de las entidades públicas es anual y está compuesta
