de la valorización que solo comprende57: a) Principal, componente económico directo de
la familia de puestos; b) Ajustada, otorgada al puesto en razón de la entidady en función
a criterios de jerarquía, responsabilidad, presupuesto a cargo, personal directamente a su
cargo, alcance de sus decisiones o monto que involucran las decisiones sobre recursos del
Estado; c) Vacaciones, entrega económica por el derecho vacacional; y, d) Aguinaldos,
entregas económicas por Fiestas Patrias y Navidad. Adicionalmentey de acuerdo a situa
ciones atípicas para el desempeño de un puesto, debido a condiciones de accesibilidad
geográfica, por altitud, riesgo de vida, riesgo legal o servicios efectivos en el extranjero, se
puede incorporar la Valorización Priorizada.
b) La compensación no económica está constituida por los beneficios otorgados para mo
tivar y elevar la competitividad de los servidores civiles. Estos beneficios no son de libre
disposición del servidor.
Un derecho a considerarse es la Compensación por Tiempo de Servicios (CTS), el cálculo
de esta compensación equivale al 100% del promedio mensual del monto resultante de
las valorizaciones Principal y Ajustada que les fueron pagadas al servidor civil en cada
mes durante los últimos treinta y seis (36) meses de trabajo efectivamente prestado, por
cada año de servicios efectivamente prestados; en caso de que la antigüedad de trabajo
efectivamente prestado sea menor a treintay seis (36) meses, se hace el cálculo de mane
ra proporcional. El pago de la CTS es cancelatorioy solo se efectiviza a la culminación del
vínculo del servidor con cada entidad58.
6. Suspensión del servicio civil
La suspensión del Servicio Civil es perfecta cuando cesa temporalmente la obligación del tra
bajador de prestar el servicio y la del empleador de otorgar la compensación respectiva, sin
que desaparezca el vínculo laboral. Es imperfecta cuando el empleador debe otorgar la com
pensación sin contraprestación efectiva de labores59.
El Servicio Civil se suspende de manera perfecta en los siguientes casos60:
a) La maternidad durante el descanso prey postnatal.
b) El ejercicio de cargos políticos de elección popular o haber sido designado como funcio
nario público de libre designación y remoción que requieran desempeñarse a tiempo
completo.
c) El permiso o licencia concedidos por la entidad.
d) El ejercicio del derecho de huelga.
e) La sanción por la comisión de faltas de carácter disciplinario que conlleve la suspensión
temporal del servidor civil, así como la pena privativa de libertad efectiva por delito cul
poso por un período no mayor a tres (3) meses.
