Tema 5: Temas de la especialidad laboral
f) La inhabilitación para el ejercicio profesional o el ejercicio de la función pública, en ambos
casos por un período no mayor a tres (3) meses.
g) La detención del servidor por la autoridad competente.
h) La sentencia de primera instancia por delitos de terrorismo, narcotráfico, corrupción o
violación de la libertad sexual.
i) El caso fortuito o fuerza mayor, debidamente sustentado.
La relación de Servicio Civil se suspende de manera imperfecta en los siguientes casos61:
a) Laenfermedady el accidente comprobados, de acuerdo al plazo establecido en lanorm a-
tividad sobre seguridad social en salud.
b) La invalidez temporal, de acuerdo al plazo establecido en la normatividad sobre seguri
dad social en salud.
c) El descanso vacacional.
d) El permiso y la licencia para el desempeño de cargos sindicales.
e) El permiso o licencia concedidos por la entidad, por cuenta o interés de la entidad.
f) Licencias por paternidad, conforme a la ley de la materia.
g) Por citación expresa judicial, militar, policial u otras citaciones derivadas de actos de ad
ministración interna de las entidades públicas.
7. Término del servicio civil
La relación laboral en el Servicio Civil termina con la conclusión del vínculo que une a la enti
dad con el servidor civil. Son causales de término del Servicio Civil las siguientes:
a) Fallecimiento.
b) Renuncia.
c) Jubilación.
d) Mutuo acuerdo.
e) Alcanzar el límite de edad de setenta (70) años, exceptuando a aquellos funcionarios pú
blicos de órganos colegiados cuya función es de asistencia temporal y perciben dieta.
f) Pérdida o renuncia a la nacionalidad peruana, en los casos en que la naturaleza del pues
to la exija como requisito para acceder al Servicio Civil.
g) La sanción de destitución por la comisión de faltas de carácter disciplinario y la condena
penal por delito doloso; así como la pena privativa de libertad efectiva por delito culposo
por un plazo mayor a tres (3) meses.
h) La inhabilitación para el ejercicio profesional o el ejercicio de la función pública, en ambos
casos por un período mayor a tres (3) meses.
i) Cese por causa relativa a la capacidad del servidor en los casos de desaprobación.
