8. Régimen disciplinario
Las disposiciones sobre Régimen Disciplinario y Procedimiento Sancionador de la Ley 30057
así como en su Reglamento General se encuentran vigentes desde el 14 de setiembre de 2014;
por lo que a partir de dicha fecha son de aplicación los siguientes supuestos: a) Los procedi
mientos disciplinarios que se instauren hasta el 13 de setiembre de 2014, con resolución y otro
acto expreso, se rigen por las normas sustantivas y procedimentales vigentes al momento de
la instauración del procedimiento hasta la resolución de los recursos de apelación que, de ser
el caso, se interpongan contra los actos que ponen fin al PAD. b) Los procedimientos discipli
narios que se instauren desde e li4 de setiembre de 2014, por hechos cometidos a partir de di
cha fechase regirán por las reglas procedimentales y sustantivas sobre régimen disciplinarios
previstas en el régimen de la Ley 30057y su Reglamento, c) Los procedimientos disciplinarios
que se instauren a partir del 14 de setiembre de 2014 sobre faltas cometidas en fechas anterio
res (hasta el 13 de setiembre de 2014), se rigen por las reglas procedimentales previstas en el
régimen de la Ley 30057 y su Reglamento y por las reglas sustantivas aplicables al momento
en que se cometieron los hechos62.
1. Faltas de carácter disciplinario. Son faltas de carácter disciplinario que, según su gravedad,
pueden ser sancionadas con suspensión temporal o con destitución, previo proceso adminis
trativo63:
a) El incumplimiento de las normas establecidas en la Ley 30057y su reglamento.
b) La reiterada resistencia al cumplim iento de las órdenes de sus superiores relacionadas
con sus labores.
c) El incurrir en acto de violencia, grave indisciplina o faltam iento de palabra en agravio de
su superior del personal jerárquicoy de los compañeros de labor.
d) La negligencia en el desempeño de las funciones.
