e) El impedír el funcionamiento del servicio público.
f) La utilización o disposición de los bienes de la entidad pública en beneficio propio o de
terceros.
g) La concurrencia al trabajo en estado de embriaguez o bajo la influencia de drogas o sus
tancias estupefacientes.
h) El abuso de autoridad o el uso de la función con fines de lucro.
i) El causar deliberadamente daños materiales en los locales, instalaciones, obras, maqui
narias, instrumentos, documentación y demás bienes de propiedad de la entidad o en
posesión de ésta.
j) Las ausencias injustificadas por más de tres (3) días consecutivos o por más de cinco (5)
días no consecutivos en un período de treinta (30) días calendario, o más de quince (15)
días no consecutivos en un período de ciento ochenta días (180) calendario.
k) El hostigamiento sexual cometido por quien ejerza autoridad sobre el servidor civil, así
como el cometido por un servidor civil, cualquiera sea la ubicación de la víctima del hosti
gamiento en la estructura jerárquica de la entidad pública, o cuando la víctima sea un be
neficiario de modalidad formativa, preste servicios independientes a la entidad pública,
sea un usuario de esta o, en general, cuando el hostigamiento se haya dado en el marco o
a raíz de la función que desempeña el servidor, independientemente de la categoría de la
víctima.
l) Realizar actividades de proselitismo político durante la jornada de trabajo, o a través del
uso de sus funciones o de recursos de la entidad pública.
m) Discriminación por razón de origen, raza, sexo, idioma, religión, opinión o condición eco
nómica.
n) El incumplimiento injustificado del horarioy la jornada de trabajo.
ñ) La afectación del principio de mérito en el accesoy la progresión en el servicio civil.
o) Actuar o influir en otros servidores para obtener un beneficio propio o beneficio para ter
ceros.
p) La doble percepción de compensaciones económicas, salvo los casos de dietas y función
docente.
q) Las demás que señale la ley.
2. Sanciones aplicables. Las sanciones por faltas disciplinarias pueden ser64:
a) Amonestación verbal o escrita. La amonestación verbal la efectúa el jefe inmediato en
forma personal y reservada. Para el caso de amonestación escrita la sanción se aplica pre
vio proceso administrativo disciplinario. Es impuesta por el jefe inmediato. La sanción se
oficializa por resolución del jefe de recursos humanos o quien haga sus veces. La apela
ción es resuelta por el jefe de recursos humanos o quien haga sus veces65.
64 Cfr. Artículo 88 Ley 30057, Perú.
65 Cfr. Artículo 89 Ley 30057, Perú.
