b) S u sp en sió n sin goce d e re m u n e ra c io n e s d e s d e u n d ía h a s ta p o r d o c e (12) m eses. La
suspensión sin goce de remuneraciones se aplica hasta por un máximo de trescientos se
senta y cinco (365) días calendario previo procedimiento administrativo disciplinario. El
número de días de suspensión es propuesto por el jefe inmediato y aprobado por el jefe
de recursos humanos o quien haga sus veces, el cual puede modificar la sanción propues
ta. La sanción se oficializa por resolución del jefe de recursos humanos o quien haga su
veces. La apelación es resuelta por el Tribunal del Servicio Civil66.
c) Destitución. La destitución se aplica previo proceso administrativo disciplinario por el
jefe de recursos humanos o quien haga sus veces. Es propuesta por el jefe de recursos
humanos o quien haga sus veces y aprobada por el titu lar de la entidad pública, el cual
puede modificar la sanción propuesta. Se oficializa por resolución del titu lar de la entidad
pública. La apelación es resuelta por el Tribunal del Servicio Civil67.
3. Autoridades del procedimiento administrativo disciplinario. Son autoridades del proce
dimiento administrativo disciplinario68:
a) El jefe inmediato del presunto infractor.
b) El jefe de recursos humanos o quien haga sus veces.
c) El titu lar de la entidad.
d) El Tribunal del Servicio Civil.
Las autoridades del procedimiento cuentan con el apoyo de un secretario técnico, que es de
preferencia abogado y designado mediante resolución del titu lar de la entidad69.
4. Trámite del procedimiento administrativo disciplinario. Son etapas del procedimiento
administrativo disciplinario70:
1. La autoridad del procedimiento administrativo disciplinario de primera instancia inicia el
procedimiento de oficio o a pedido de una denuncia, debiendo comunicar al servidor por
escrito las presuntas faltas y otorgarle un plazo de cinco (5) días hábiles para presentar el
descargo y las pruebas que crea conveniente para su defensa. Para tal efecto, el servidor
civil tiene derecho a conocer los documentos y antecedentes que dan lugar al procedi
miento. Vencido el plazo sin la presentación de los descargos, el proceso queda listo para
ser resuelto.
2. Previo al pronunciamiento de las autoridades del proceso administrativo disciplinario de
primera instancia y luego de presentado los descargos, el servidor civil procesado puede
ejercer su derecho de defensa a través de un informe oral, efectuado personalmente o por
medio de un abogado, para lo cual se señala fechay hora única.
