3. La autoridad del procedimiento administrativo disciplinario de primera instancia realiza
las investigaciones del caso, solicita los informes respectivos, examina las pruebas que se
presenten e impone las sanciones que sean de aplicación.
XXII. EL PROCESO LABORAL
Con fecha 15 de enero de 2010 se publicó en el Diario Oficial El Peruano la Nueva Ley Procesal
del Trabajo - Ley 2 9 4 9 7 - En lo no previsto por la Ley 29497 son de aplicación supletoria las
normas del Código Procesal Civil71. Asimismo, en los procesos laborales el Estado puede ser
condenado al pago de costos72.
1. Principios del proceso laboral
El proceso laboral se inspira, esencialmente, en los siguientes principios73:
1. Inmediación, se garantiza la relación directa del Juez con las partes, verbi gratia, las pregun
tas directas que puede realizar en audiencia el juez al trabajador.
2.0ralidad, se hace prevalecer laoralidad, esto es lo verbal, sobre lo escrito, verbi gratia, la ex
posición verbal de los hechos que fundamentan la demanda en la audiencia de juzgamiento.
3. Concentración, las etapas del proceso laboral tienden a su concentración en menos etapas,
verbi gratia, la utilización del juzgamiento anticipado luego de darse por fracasada la conci
liación.
71 Cfr. Primera disposición complementaria Ley 2 9 4 9 7 , Perú.
72 Cfr. Sétima disposición complementaria Ley 2 9 4 9 7 , Perú.
73 Cfr. Artículo I Ley 29497, Perú.
