4 Celeridad, el Juez garantiza el cumplim iento de plazos procesales, verbi gratia, señalamien
to de fecha para audiencia en el más breve plazo posible teniendo en cuenta la complejidad
del proceso.
5. Economía procesal, el Juez garantiza la gratuidad de los procesos laborales, verbigratia, el
trabajador está exonerado del pago de aranceles judiciales hasta las 70 URR
6 . Veracidad, el Juez busca la verdad material sobre la verdad procesal que podrían inducir las
partes, verbi gratia, uso de los medios de prueba de oficio.
2. Ám bito de la ju sticia laboral
Corresponde a la justicia laboral resolverlosconflictosjurídicosqueseoriginan con ocasión de
las prestaciones de servicios de carácter personal, de naturaleza laboral, formativa, cooperati
vista o administrativa; están excluidas las prestaciones de servicios de carácter civil, salvo que
la demanda se sustente en el encubrimiento de relaciones de trabajo. Tales conflictos jurídicos
pueden ser individuales, plurales o colectivos, y estar referidos a aspectos sustanciales o cone
xos, incluso previos o posteriores a la prestación efectiva de los servicios74.
3. Competencia
La competencia es la facultad de administrar justicia en un caso concreto:
1. Competencia por materia de los juzgados de paz letrados laborales. Los juzgados de paz
letrados laborales conocen de los siguientes procesos75:
1. En proceso abreviado laboral, las pretensiones referidas al cumplim iento de obligaciones
de dar no superiores a 70 URP originadas con ocasión de la prestación personal de servi
cios de naturaleza laboral, formativa o cooperativista, referidas a aspectos sustanciales o
conexos, incluso previos o posteriores a la prestación efectiva de los servicios,
z. En proceso con título ejecutivo, cuando la cuantía no supere las 70 URP; salvo tratándose
de la cobranza de aportes previsionales del Sistema Privado de Pensiones retenidos por el
empleador, en cuyo caso son competentes con prescindencia de la cuantía.
3. Los asuntos no contenciosos, sin importar la cuantía.
4. En proceso abreviado laboral, las pretensiones no cuantificables relativas a la protección
de derechos individuales, originadas con ocasión de la prestación personal de servicios
de naturaleza laboral, con excepción de las pretensiones vinculadas a la libertad sindical,
siempre que estas no sean de competencia de los juzgados especializados de trabajo.
5. Las pretensiones no cuantificables acumuladas con una pretensión cuantificable hasta 70
URP vinculadas entre sí.
6 . En proceso abreviado laboral, las pretensiones de impugnación de sanciones disciplina
rias distintas al despido, dentro de una relación laboral en el régimen laboral de la acti
vidad privada o regímenes especiales, tales como amonestación verbal, amonestación
