Tema 5: Temas de la especialidad laboral
escrita, días de suspensión sin goce de remuneraciones y cualquier otra que no implique
la finalización del vínculo laboral, con excepción de los derechos vinculados a la protec
ción de la libertad sindical.
7. En proceso abreviado laboral, los casos de actos de hostilidad del empleador, entendidos
como actos de acoso moral y hostigamiento sexual, conforme a la ley de la materia..
8 . En proceso abreviado laboral, los casos relacionados con el pago de indemnizaciones por
daños y perjuicios, cualquiera sea la causa que los origine, cuando su monto no sea su
perior a 70 URR La Resolución Administrativa N° 000424-2024-CE-PJ» publicada el 06
de diciembre de 2024, en su artículo primero precisa que los juzgados de Paz Letrados
Laborales son los órganos competentes para conocerlos procesos de responsabilidad civil
por enfermedades profesionales y accidentes de trabajo, cuando el monto indemnizato-
rio sea igual o menor de 70 URR
9. En proceso abreviado laboral, el reconocimiento de los derechos laborales de los trabaja
dores en regímenes especiales sean públicos o privados, como trabajadores de la micro y
pequeña empresa, trabajadores agrarios, trabajadores de la construcción civil, trabajado
res del hogar, régimen laboral de estibadores terrestres, régimen laboral de exportación
no tradicional, régimen laboral de guardianes y porteros y régimen laboral de trabajado
res adolescentes, cualquiera fuera su cuantía.
10. El pago de indemnizaciones por daños y perjuicios, cualquiera sea la causa, cuando su
monto no sea superior a 70 URR
n . Los asuntos referidos a los descuentos de los haberes de los trabajadores por casos de
“Pago Indebido” realizado por la entidad.
2. Competencia por materia de los juzgados especializados de trabajo. Los juzgados espe
cializados de trabajo conocen de los siguientes procesos76:
a. En proceso ordinario laboral, las pretensiones relativas a la protección de derechos indi
viduales, plurales o colectivos, originadas con ocasión de la prestación personal de servicios
de naturaleza laboral, formativa o cooperativista, referidas a aspectos sustanciales o conexos,
incluso previos o posteriores a la prestación efectiva de los servicios.
Se consideran incluidas en dicha competencia, sin ser exclusivas, las pretensiones relaciona
das a los siguientes:
i) El nacimiento, desarrolloy extinción de la prestación personal de servicios; así como a los
correspondientes actos jurídicos.
ii) La responsabilidad por daño patrimonial o extrapatrimonial, incurrida porcualquiera de
las partes involucradas en la prestación personal de servicios, o terceros en cuyo favor se
presta o prestó el servicio.
iii) Los actos de discriminación en el acceso, ejecución y extinción de la relación laboral.
iv) La responsabilidad civil por las enfermedades profesionales y los accidentes de trabajo
cuando el monto indemnizatorio sea mayor de 70 URR
76 Cfr. Artículo 2 Ley 2 9 4 9 7 , Perú.
