vi) Los conflictos vinculados a una organización sindical y entre organizaciones sindicales,
incluida su disolución.
vii) El cumplimiento de obligaciones generadas o contraídas con ocasión de la prestación
personal de servicios exigióles a institutos, fondos, cajas u otros.
viii) El cumplimiento de las prestaciones de saludy pensiones de invalidez, a favor de los ase
gurados o los beneficiarios, exigióles al empleador, a las entidades prestadoras de salud o
a las aseguradoras.
ix) El Sistema Privado de Pensiones.
x) La nulidad de cosa juzgada fraudulenta laboral; y
xi) aquellas materias que, a criterio del juez, en función de su especial naturaleza, deban ser
ventiladas en el proceso ordinario laboral.
Conoce las pretensiones referidas al cumplimiento de obligaciones de darsuperiores a70 URR
a. En proceso abreviado laboral, de la reposición cuando ésta se plantea como pretensión
principal única.
b. En proceso abreviado laboral, las pretensiones relativas a la vulneración de la libertad sin
dical.
c. En proceso contencioso administrativo conforme a la ley de la materia, los casos siguien
tes:
Pretensiones originadas de las prestaciones de servicios de carácter personal, sujetas
al derecho laboral públicoy las carreras especiales al servicio del Estado, así como las
pretensiones propias del derecho de la seguridad social.
La impugnación judicial de resoluciones expedidas por tribunales administrativos
que resuelven en materia de derecho laboral público y derecho de la seguridad so
cial, cuando las prestaciones sean otorgadas por un organismo público.
La impugnación contra actuaciones de la autoridad administrativa de trabajo.
d. Los procesos con título ejecutivo cuando la cuantía supere las 70 URR
3. Competencia por materia de las salas laborales superiores. Las salas laborales de las cor
tes superiores tienen competencia, en primera instancia, en las materias siguientes77:
a. Proceso de acción popular en materia laboral.
b. Anulación de laudo arbitral que resuelve un conflicto jurídico de naturaleza laboral.
c. Impugnación de laudos arbitrales derivados de una negociación colectiva.
d. Contienda de competencia promovida entre juzgados de trabajo y entre éstos y otros juz
gados de distinta especialidad del mismo distrito judicial.
e. Conflictos de autoridad entre los juzgados de trabajoy autoridades administrativas en los
casos previstos por la ley.
77 Cfr. Artículo 3 Ley 2 9 4 9 7 , Perú.
6 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

