Tema 5: Temas de la especialidad laboral
f. Las demás que señale la ley.
4. Competencia por función. La Sala de Derecho Constitucional y Social de la Corte Suprema
de Justicia de la República es competente para conocer de los siguientes recursos78:
a) Del recurso de casación;
b) del recurso de apelación de las resoluciones pronunciadas por las salas laborales en pri
mera instancia; y
c) del recurso de queja por denegatoria del recurso de apelación o por haber sido concedido
en efecto distinto al establecido en la ley.
Las salas laborales de las cortes superiores son competentes para conocer de los siguientes
recursos79:
a) Del recurso de apelación contra las resoluciones expedidas por los juzgados laborales; y
b) del recurso de queja por denegatoria del recurso de apelación o por haber sido concedido
en efecto distinto al establecido en la ley.
Los juzgados especializados de trabajo son competentes para conocer de los siguientes recursos80:
a) Del recurso de apelación contra las resoluciones expedidas por los juzgados de paz letra
dos en materia laboral; y
b) del recurso de queja por denegatoria del recurso de apelación o por haber sido concedido
en efecto distinto al establecido en la ley.
5. Competencia por territorio. A elección del demandante es competente el juez del lugar
del domicilio principal del demandado o el del últim o lugar donde se prestaron los servicios.
Si la demanda está dirigida contra quien prestó los servicios, sólo es competente el juez del
domicilio de éste81.
4. Demanda laboral
La demanda laboral es el acto procesal de la parte demandante (trabajador o empleador) que
da inicio al proceso laboral.
La demanda se presenta por escrito y debe contener los requisitos y anexos establecidos en la
norma procesal civil, con las siguientes precisiones82:
a) Debe incluirse, cuando corresponda, la indicación del monto total del petitorio, así como
el monto de cada uno de los extremos que integren la demanda. El demandante puede
incluir de modo expreso su pretensión de reconocimiento de los honorarios que se pagan
con ocasión del proceso.
78 Cfr. Artículo 4 Ley 2 9 4 9 7 , Perú.
79 Cfr. Artículo 4 Ley 29497, Perú.
