b) No debe incluirse ningún pliego dirigido a la contraparte, los testigos o los peritos; sin
embargo, debe indicarse la finalidad de cada medio de prueba.
El juez verifica el cumplimiento de los requisitos de la demanda dentro de los cinco (5) días
hábiles siguientes de recibida. Si observa el incumplimiento de alguno de los requisitos, con
cede al demandante cinco (5) días hábiles para que subsane la omisión o defecto, bajo aperci
bimiento de declararse la conclusión del procesoy el archivo del expediente83.
5. Contestación de la demanda laboral
La contestación de la demanda laboral es el acto procesal de la parte demandada (empleador
o trabajador) que haciendo uso del derecho de contradicción da respuesta a la demanda in
coada en su contra.
La contestación de lademandase presenta porescritoy debe contenerlos requisitosy anexos
establecidos en la norma procesal civil, sin incluir ningún pliego dirigido a la contraparte, los
testigos o los peritos; sin embargo, debe indicarse la finalidad de cada medio de prueba84.
La contestación contiene todas las defensas procesales y de fondo que el demandado estime
convenientes. Si el demandado no niega expresamente los hechos expuestos en la demanda,
estos son considerados admitidos. La reconvención es improcedente85.
6. Actividad probatoria
1. O portunidad Los medios probatorios deben ser ofrecidos por las partes únicamente
en la demanda y en la contestación. Extraordinariamente, pueden ser ofrecidos hasta el
momento previo a la actuación probatoria, siempre y cuando estén referidos a hechos
nuevos o hubiesen sido conocidos u obtenidos con posterioridad. Las partes concurren a
la audiencia en la que se actúan las pruebas con todos sus testigos, peritos y documentos
que, en dicho momento, corresponda ofrecer, exhibir o se pretenda hacer valer con rela
ción a las cuestiones probatorias86.
2. Prueba de oficio. Excepcionalmente, el juez puede ordenar la práctica de alguna prueba
adicional, en cuyo caso dispone lo conveniente para su realización, procediendo a sus
pender la audiencia en la que se actúan las pruebas por un lapso adecuado no mayor a
treinta (30) días hábiles,y a citar, en el mismo acto, fechay hora para su continuación. Esta
decisión es inimpugnable87.
3. Carga de la prueba. La carga de la prueba corresponde a quien afirma hechos que con
figuran su pretensión, o a quien los contradice alegando nuevos hechos, sujetos a las si-
