Tema 5: Temas de la especialidad laboral
guientes reglas especiales de distribución de la carga probatoria, sin perjuicio de que por
ley se dispongan otras adicionales88.
Acreditada la prestación personal de servicios, se presume la existencia de vínculo laboral
a plazo indeterminado, salvo prueba en contrario. Cuando corresponda, si el demandante
invoca la calidad de trabajador o ex trabajador, tiene la carga de la prueba de89:
a) La existencia de la fuente normativa de los derechos alegados de origen distinto al
constitucional o legal.
b) El motivo de nulidad invocadoy el acto de hostilidad padecido.
c) La existencia del daño alegado.
De modo paralelo, cuando corresponda, incumbe al demandado que sea señalado como
empleador la carga de la prueba de90:
a) El pago, el cumplimiento de las normas legales, el cumplim iento de sus obligaciones
contractuales, su extinción o inexigibilidad.
b) La existencia de un motivo razonable distinto al hecho lesivo alegado.
c) El estado del vínculo laboral y la causa del despido.
4. Interrogatorios El interrogatorio a las partes, testigos, peritos y otros es realizado por el
juez de manera libre, concreta y clara, sin seguir ningún ritualismo o fórm ula preconsti-
tuida. Para su actuación no se requiere de la presentación de pliegos de preguntas91.
5. Declaración de parte. La parte debe declarar personalmente. Las personas jurídicas pres
tan su declaración a través de cualquiera de sus representantes, quienes tienen el deber
de acudir informados sobre los hechos que motivan el proceso92.
6. Declaración de testigos. Los testigos no presencian el desarrollo de la audiencia y solo
ingresan a ella en el momento que les corresponda93.
7. Exhibición de planillas. La exhibición de las planillas manuales se tiene por cumplida
con la presentación de las copias legalizadas correspondientes a los períodos necesitados
de prueba. La exhibición de las planillas electrónicas es ordenada por el juez al funciona
rio del Ministerio de Trabajo y Promoción del Empleo responsable de brindar tal infor
mación. Las partes pueden presentar copias certificadas expedidas por el Ministerio de
Trabajoy Promoción del Empleo de la información contenida en las planillas electrónicas,
en lugar de la exhibición electrónica94.
8. Pericia. Los peritos no presencian el desarrollo de la audienciay solo ingresan a ella en el
momento que corresponda efectuar su exposición. Los informes contables practicados
