7. Formas especiales de conclusión del proceso
Fo rm as e sp e ciale s d e co n clu sió n del proceso. El proceso laboral puede concluir, de forma
especial, por conciliación, allanamiento, reconocimiento de la demanda, transacción, desis
tim iento o abandono. También concluye cuando ambas partes inasisten por segunda vez a
cualquiera de las audiencias programadas en primera instancia96.
1 . C o n cilia ció n y tran sacció n . La conciliacióny latransacción pueden ocurrir dentro del proce
so, cualquiera sea el estado en que se encuentre, hasta antes de la notificación de la sentencia
con calidad de cosa juzgada. El juez puede en cualquier momento invitara las partes a llegara
un acuerdo conciliatorio, sin que su participación implique prejuzgamientoy sin que lo mani
festado por las partes se considere declaración. Si ambas partes concurren al juzgado llevando
un acuerdo para poner fin al proceso, el juez le da trám ite preferente en el día97. Para que un
acuerdo conciliatorio o transaccional ponga fin al proceso debe superar el test de disponibili
dad de derechos, para lo cual se toman los siguientes criterios98:
a) El acuerdo debe versar sobre derechos nacidos de una norma dispositiva, debiendo el
juez verificar que no afecte derechos indisponibles;
b) debe ser adoptado por el titu lar del derecho; y
c) debe haber participado el abogado del prestador de servicios demandante.
2. A b a n d o n o . El abandono del proceso se produce transcurridos cuatro (4) meses sin que se
realice acto que lo impulse. El juez declara el abandono a pedido de parte o de tercero legiti
mado, en la segunda oportunidad que se solicite, salvo que en la primera vez el demandante
no se haya opuesto al abandono o no haya absuelto el traslado conferido99.
8. Sentencia
El juez recoge los fundamentos de hecho y de derecho esenciales para motivar su decisión. La
existencia de hechos admitidos no enerva la necesidad de fundamentar la sentencia en dere
cho. La sentencia se pronuncia sobre todas las articulaciones o medios de defensa propuestos
por las partes y sobre la demanda, en caso deque la declare fundada total o parcialmente, in
dicando los derechos reconocidos, así como las prestaciones que debe cum plir el demandado.
Si la prestación ordenada es de dar una suma de dinero, la misma debe estar indicada en mon
to líquido. El juez puede disponer el pago de sumas mayores a las demandadas si apareciere
