dados. Su cuantía o modo de liquidación es de expreso pronunciamiento en la sentencia100.
9. Medios im púgnatenos
1. A p e la ció n de la se n te n c ia en los procesos o rd in ario , a b re v ia d o y d e im p u g n a ció n d e la u
d o s a rb itra le s económ icos. El plazo de apelación de la sentencia es de cinco (5) días hábiles
y empieza a correr desde el día hábil siguiente de la audiencia o de citadas las partes para su
notificación101.
2. T rám ite en se g u n d a in sta n cia y a u d ie n c ia d e v ista de la ca u sa en los procesos o rd in ario ,
a b re v ia d o y d e im p u g n a c ió n de lau d o s a rb itra le s eco nó m ico s Interpuesta la apelación, el
juez remite el expediente a segunda instancia dentro de los cinco (5) días hábiles siguientes. El
órgano jurisdiccional de segunda instancia realiza las siguientes actividades102:
a) Dentro de los cinco (5) días hábiles de recibido el expediente fija día y hora para la cele
bración de la audiencia de vista de la causa. La audiencia de vista de la causa debe fijarse
entre los veinte (20) y treinta (30) días hábiles siguientes de recibido el expediente.
b) El día de la audiencia de vista, concede el uso de la palabra al abogado de la parte apelan
te a fin de que exponga sintéticamente los extremos apelados y los fundamentos en que
se sustentan; a continuación, cede el uso de la palabra al abogado de la parte contraria.
Puede form ular preguntas a las partes y sus abogados a lo largo de las exposiciones ora
les.
c) Concluida la exposición oral, dicta sentencia inmediatamente o luego de sesenta (60)
minutos, expresando el fallo y las razones que lo sustentan, de modo lacónico. Excepcio
nalmente, puede diferir su sentencia dentro de los cinco (5) días hábiles siguientes. En
ambos casos, al finalizar la audiencia señala día y hora para que las partes comparezcan
ante el despacho para la notificación de la sentencia, bajo responsabilidad. La citación
debe realizarse dentro de los cinco (5) días hábiles siguientes de celebrada la audiencia
de vista.
d) Si las partes no concurren a la audiencia de vista, la sala, sin necesidad de citación, notifi
ca la sentencia al quinto día hábil siguiente, en su despacho.
3. C a u s a le s del recurso d e casació n. Con fecha en de marzo de 2023, se publica en el Diario
