-- 822 of 1506 --

1. Si la sentencia o auto ha sido expedido con inobservancia de alguna de las garantías cons
titucionales de carácter procesal o material, o con una indebida o errónea aplicación de
dichas garantías.
2. Si la sentencia o auto incurre o deriva de una inobservancia de las normas legales de ca
rácter procesal sancionadas con la nulidad.
3. Si la sentencia o auto contiene una indebida aplicación, una errónea interpretación o una
falta de aplicación de la ley, tratados o acuerdos internacionales ratificados por el Perú
en materia laboral y de seguridad social, o de otras normas jurídicas necesarias para su
aplicación.
4. Si la sentencia o auto ha sido expedido con falta de motivación o manifiesta ilogicidad de
la motivación o cuando el vicio resulte de su propio tenor.
5. Si la sentencia o auto se aparta de las decisiones vinculantes del Tribunal Constitucional o
de la Corte Suprema de Justicia de la República.
El recurso de casación se interpone104:
Contra las sentencias o autos que ponen fin al proceso, expedidos por las salas superiores
como órganos de segundo grado. En caso de sentencias que obliguen a dar suma de dine
ro, el monto total reconocido en ella debe superar las 500 URR
Son requisitos de procedencia del recurso de casación105: El recurso de casación debe:
a) Indicar separadamente cada causal invocada.
b) Citar concretamente los preceptos legales que considere erróneamente aplicados o inob
servados, expresando específicamente cuál es la aplicación que pretende.
c) Precisar el fundamento o los fundamentos doctrinales o legales que sustenten su preten
sión, expresando específicamente cuál es la aplicación que pretende.
Excepcionalmente, es procedente el recurso de casación en los supuestos no previstos en el ar
tículo 34, cuando la Sala Constitucional y Social de la Corte Suprema de Justicia de la Repúbli
ca, discrecionalmente, lo considere necesario para el desarrollo de la doctrina jurisprudencial.
Se declara la improcedencia del recurso de casación cuando no se cumplen los requisitos y
causales previstos en el artículo 34y el numeral 1 del artículo 36 de la Ley. Asimismo, cuando:
a) Se refiere a resoluciones no impugnables mediante el recurso de casación.
b) El recurrente hubiera consentido la resolución adversa en primera instancia, si esta fuere
confirmada por la resolución objeto del recurso.
c) El recurrente invoca violaciones de la ley que no hubieran sido deducidas en los funda
mentos de su recurso de apelación, salvo que estén referidas a fundamentos contenidos
en la resolución de segunda instancia que no hubieran sido previstos en la de primera.
d) Carezca manifiestamente de fundamento jurídico.
10 4 Cfr. Artículo 35.1 Ley 29497, Perú.
105 Cfr. Artículo 36.1 Ley 29497, Perú.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 823 of 1506 --

Tema 5: Temas de la especialidad laboral
e) Se hubieren desestimado en el fondo otros recursos sustancialmente iguales y el recu
rrente no presenta argumentos suficientes para que se modifique el criterio o doctrina
jurisprudencial ya establecida.
f) La sentencia de segunda instancia confirma la de primera instancia. No obstante, proce
derá el recurso si presenta interés casacional que se produce cuando la resolución recurri
da se oponga a la doctrina jurisprudencial de la Corte Suprema de Justicia de la República,
o cuando resuelva puntos y cuestiones sobre los que exista jurisprudencia contradictoria
de las salas laborales superiores.
g) Cuando el pronunciamiento de segunda instancia sea anulatorio.
La improcedencia del recurso puede afectar a todas las causales invocadas o referirse sola
mente a alguna de estas.
Tramite:
El recurso se interpone ante la sala superior que emitió la resolución impugnada, dentro
del plazo d e io días, de notificada la resolución que se impugna más el térm ino de la dis
tancia cuando corresponda, adjuntando el arancel judicial.
En caso no se cumpla con lo previsto en el numeral i o los literales a) o b) del numeral 2
del artículo 35, la sala superior declara inadmisible el recurso e impondrá una m ulta no
menor de 10 ni mayor de 50 URP en caso de que considere que su interposición tuvo como
causa una conducta maliciosa o temeraria.
En caso no se cumpla con lo previsto en el literal c) del numeral 2 del artículo 35, la sala
superior concede al impugnante un plazo de 03 días para su subsanación, en caso no se
presente la subsanación, la sala superior declara inadmisible el recurso. Sin perjuicio de
la inadmisibilidad, se sanciona con una multa no menor de 10 ni mayor de 20 URP si se
advierte una conducta maliciosa o temeraria.
Una vez adm itido el recurso de casación, la sala superior eleva copia de los principales ac
tuados del expediente a la Corte Suprema de Justicia de la República, en un plazo máximo
de 05 días hábiles. Dentro del mismo plazo, también notifica a las partes en sus respecti
vas casillas electrónicas con el auto de admisión del recursoy el recurso correspondiente.
La resolución que se pronuncia sobre la procedencia o improcedencia del recurso de ca
sación se expide dentro del plazo de 30 días hábiles contados desde la recepción de las
copias del expediente, con el voto conforme de tres jueces supremos,y fija díay hora para
la audiencia de casación, de ser el caso.
Programada la audiencia de casación, la misma se instala con la concurrencia de las par
tes que asistan, quienes pueden informarsin necesidad deque hubiesen pedido el uso de
la palabra. En todo caso, la falta de comparecencia injustificada del abogado de la parte
recurrente da lugar a que se declare improcedente el recurso de casación.
La sentencia casatoria se expide dentro del plazo de diez días hábiles luego de finalizada
la audiencia.
El recurso de casación se resuelve con el voto conforme de cuatro jueces supremos.
