10. Proceso ordinario laboral
1. Traslado y citación a audiencia de conciliación. Verificados los requisitos de la demanda, el
juez emite resolución disponiendo106:
a) La admisión de la demanda;
b) la citación a las partes a audiencia de conciliación, la cual debe ser fijada en día y hora
entre los veinte (20) y treinta (30) días hábiles siguientes a la fecha de calificación de la
demanda; y
c) el emplazamiento al demandado para que concurra a la audiencia de conciliación con el
escrito de contestación y sus anexos.
2. A u d ie n c ia d e co n cilia ció n . La audiencia de conciliación se lleva a cabo del siguiente modo107:
a. La audiencia, inicia con la acreditación de las partes o apoderados y sus abogados. Si el
demandante no asiste, el demandado puede contestar la demanda, continuando la au
diencia. Si el demandado no asiste incurre automáticamente en rebeldía, sin necesidad
de declaración expresa, aun cuando la pretensión se sustente en un derecho indisponible.
También incurre en rebeldía automática si, asistiendo a la audiencia, no contesta la de
manda o el representante o apoderado no tiene poderes suficientes para conciliar.
b. El juez invita a las partes a conciliar sus posiciones y participa activamente a fin de que
solucionen sus diferencias total o parcialmente. Por decisión de las partes la conciliación
puede prolongarse lo necesario hasta que se dé por agotada, pudiendo incluso continuar
los días hábiles siguientes, cuantas veces sea necesario, en un lapso no mayor de un (1)
mes. Si las partes acuerdan la solución parcial o total de su conflicto el juez, en el acto,
aprueba lo acordado con efecto de cosa juzgada; asimismo, ordena el cumplim iento de
las prestaciones acordadas en el plazo establecido por las partes o, en su defecto, en el
plazo de cinco (5) días hábiles siguientes. Del mismo modo, si algún extremo no es con
trovertido, el juez emite resolución con calidad de cosa juzgada ordenando su pago en
igual plazo.
c. En caso de haberse solucionado parcialmente el conflicto, o no haberse solucionado, el
juez precisa las pretensiones que son materia de juicio; requiere al demandado para que
presente, en el acto, el escrito de contestación y sus anexos; entrega una copia al deman
dante; y fija díay hora para la audiencia de juzgamiento, la cual debe programarse dentro
de los treinta (30) días hábiles siguientes, quedando las partes notificadas en el acto. Si el
juez advierte, haya habido o no contestación, que la cuestión debatida es solo de derecho,
o que siendo también de hecho no hay necesidad de actuar medio probatorio alguno, so
licita a los abogados presentes exponer sus alegatos, a cuyo término, o en un lapso no ma
yor de sesenta (60) minutos, dicta el fallo de su sentencia. La notificación de la sentencia
se realiza de igual modo a lo regulado para el caso de la sentencia dictada en la audiencia
de juzgamiento.
106 Cfr. Artículo 42 Ley 29497, Perú.
10 7 Cfr. Artículo 43 Ley 29497, Perú.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 825 of 1506 --

Tema 5: Temas de la especialidad laboral
3. A u d ie n c ia de juzgamiento. La audiencia de juzgamiento se realiza en acto único y con
centra las etapas de confrontación de posiciones, actuación probatoria, alegatos y sentencia.
La audiencia de juzgamiento se inicia con la acreditación de las partes o apoderados y sus
abogados. Si ambas partes inasisten, el juez declara la conclusión del proceso si, dentro de
los treinta (30) días naturales siguientes, ninguna de las partes hubiese solicitado fecha para
nueva audiencia108.
3.1. E tap a d e co n fro n tació n de posiciones. La etapa de confrontación de posiciones se inicia
con una breve exposición oral de las pretensiones demandadas y de los fundamentos de he
cho que las sustentan. Luego, el demandado hace una breve exposición oral de los hechos que,
por razones procesales o de fondo, contradicen la demanda109.
3.2. E ta p a d e a ctu ació n p ro b ato ria La etapa de actuación probatoria se lleva a cabo del si
guiente modo110:
a. El juez enuncia los hechos que no necesitan de actuación probatoria por tratarse de he
chos admitidos, presumidos por ley, recogidos en resolución judicial con calidad de cosa
juzgada o notorios; así como los medios probatorios dejados de lado por estar dirigidos a
la acreditación de hechos impertinentes o irrelevantes para la causa.
b. El juez enuncia las pruebas admitidas respecto de los hechos necesitados de actuación
probatoria.
c. Inmediatamente después, las partes pueden proponer cuestiones probatorias solo res
pecto de las pruebas admitidas. El juez dispone la admisión de las cuestiones probatorias
únicamente si las pruebas que las sustentan pueden ser actuadas en esta etapa.
d. El juez toma juramento conjunto a todos los que vayan a participaren esta etapa.
e. Se actúan todos los medios probatorios admitidos, incluidos los vinculados a las cuestio
nes probatorias, empezando por los ofrecidos por el demandante, en el orden siguiente:
declaración de parte, testigos, pericia, reconocimiento y exhibición de documentos. Si
agotada la actuación de estos medios probatorios fuese imprescindible la inspección ju
dicial, el juez suspende la audienciay señala día, horay lugar para su realización citando,
en el momento, a las partes, testigos o peritos que corresponda. La inspección judicial
puede ser grabada en audio y vídeo o recogida en acta con anotación de las observacio
nes constatadas; al concluirse, señala día y hora, dentro de los cinco (5) días hábiles si
guientes para los alegatos y sentencia.
f. La actuación probatoria debe concluir en el día programado; sin embargo, si la actuación
no se hubiese agotado, la audiencia continúa dentro de los cinco (5) días hábiles siguien
tes.
3.3- A le g ato s y sen ten cia . Finalizada la actuación probatoria, los abogados presentan oral
mente sus alegatos. Concluidos los alegatos, el juez, en forma inmediata o en un lapso no ma
yor de sesenta (60) minutos, hace conocer a las partes el fallo de su sentencia. A su vez, señala
