díay hora, dentro de los cinco (5) días hábiles siguientes, para la notificación de la sentencia.
Excepcionalmente, por la complejidad del caso, puede diferir el fallo de su sentencia dentro
de los cinco (5) días hábiles posteriores, lo cual informa en el acto citando a las partes para que
comparezcan al juzgado para la notificación de la sentencia. La notificación de la sentencia
debe producirse en el díay hora indicados, bajo responsabilidad111.
11. Proceso abreviado laboral
1. Traslad o y citació n a a u d ie n c ia ú n ica Verificados los requisitos de la demanda, el juez emi
te resolución disponiendo112:
a) La admisión de la demanda;
b) el emplazamiento al demandado para que conteste la demanda en el plazo de diez (10)
días hábiles;y
c) la citación a las partes a audiencia única, la cual debe ser fijada entre los veinte (20) y
treinta (30) días hábiles siguientes a la fecha de calificación de la demanda.
2. A u d ie n c ia ú n ica La audiencia única se estructura a partir de las audiencias de conciliacióny
juzgamiento del proceso ordinario laboral. Comprendey concentra las etapas de conciliación,
confrontación de posiciones, actuación probatoria, alegatosy sentencia, las cuales se realizan,
en dicho orden, una seguida de la otra, con las siguientes precisiones113:
a. La etapa de conciliación se desarrolla de igual forma que la audiencia de conciliación del
proceso ordinario laboral, con la diferencia de que la contestación de la demanda no se
realiza en este acto, sino dentro del plazo concedido, correspondiendo al juez hacer en
trega al demandante de la copia de la contestación y sus anexos, otorgándole un tiempo
prudencial para la revisión de los medios probatorios ofrecidos.
b. Ante la proposición de cuestiones probatorias del demandante el juez puede, excepcio
nalmente, fijar fecha para la continuación de la audiencia dentro de los treinta (30) días
hábiles siguientes si, para la actuación de aquella se requiriese de la evacuación de un
informe pericial, siendo carga del demandante la gestión correspondiente.
12. Proceso impugnativo de laudos arbitrales económicos
1. A d m isió n de la d e m a n d a . Además de los requisitos de la demanda, la sala laboral verifica
si esta se ha interpuesto dentro de los diez (10) días hábiles siguientes de haberse notificado
el laudo arbitral que haciendo las veces de convenio colectivo resuelve el conflicto económico
o de creación de derechos, o su aclaración; en caso contrario, declara la improcedencia de la
demanda y la conclusión del proceso. Los únicos medios probatorios admisibles en este pro
ceso son los documentos, los cuales deben ser acompañados necesariamente con los escritos
de demanday contestación114.
