2. Traslad o y co n testació n Verificados los requisitos de la demanda, la sala laboral emite re-
solución disponiendo115:
a) La admisión de la demanda;
b) el emplazamiento al demandado para que conteste la demanda en el plazo de diez (10)
días hábiles;y
c) la notificación a los árbitros para que, de estimarlo convenientey dentro del mismo plazo,
expongan sobre lo que consideren conveniente.
3. T rá m ite y se n te n cia d e prim era in sta n c ia La sala laboral, dentro de los diez (10) días há-
biles siguientes de contestada la demanda, dicta sentencia por el solo mérito de los escritos
de demanda, contestación y los documentos acompañados. Para tal efecto señala díay hora,
dentro del plazo indicado, citando a las partes para alegatos y sentencia, lo cual se lleva a cabo
de igual modo a lo regulado en el proceso ordinario laboral116.
4. Im p ro ce d e n cia d el recurso d e casació n Contra lasentencia de la Corte Suprema de ] usticia
de la República no procede el recurso de casación117.
13. Proceso cautelar
A pedido de parte, todo juez puede dictar medida cautelar, antes de iniciado un proceso o
dentro de este, destinada a garantizar la eficacia de la pretensión principal. Las medidas cau
telares se dictan sin conocimiento de la contraparte118.
1. M e d id a e sp ecial d e reposición p ro visio nal. El juez puede dictar, entre otras medidas caute
lares, fuera o dentro del proceso, una medida de reposición provisional, cumplidos los requi
sitos ordinarios119.
2. A sig n a ció n p ro visio nal. De modo especial, en los procesos en los que se pretende la repo
sición, el juez puede disponer la entrega de una asignación provisional mensual cuyo monto
es fijado por el juezy el cual no puede exceder de la últim a remuneración ordinaria mensual
percibida por el trabajador, con cargo a la Compensación por Tiempo de Servicios (CTS)120.
14. Proceso de ejecución
Se tramitan en proceso de ejecución los siguientes títulos ejecutivos121:
a) Las resoluciones judiciales firmes;
b) las actas de conciliación judicial;
