15. Procesos no contenciosos
1. C o n sig n a ció n . La consignación de unaobligación exigióle no requiere que el deudor efectúe
previamente su ofrecimiento de pago, ni que solicite autorización del juez para hacerlo122. El
acreedor puede contradecir el efecto cancelatorio de la consignación en el plazo de cinco (5)
días hábiles de notificado. Conferido el traslado y absuelto el mismo, el juez resuelve lo que
corresponda o manda reservar el pronunciamiento para que se decida sobre su efecto can ce-
lato rio en el proceso respectivo123.
2. A u to riza ció n ju d ic ia l p ara in greso a centro lab o ra l. En los casos en que las normas de ins
pección del trabajo exigen autorización judicial previa para ingresar a un centro de trabajo,
esta es tramitada porel inspector de trabajo o funcionario que haga sus veces. Para tal efecto
debe presentar, ante el juzgado de paz letrado de su ámbito territorial de actuación, la respec
tiva solicitud. Esta debe resolverse, bajo responsabilidad, en el térm ino de veinticuatro (24)
horas, sin correr traslado124.
3. Entreg a d e d o cu m en to s. La mera solicitud de entrega de documentos se sigue como pro
ceso no contencioso siempre que ésta se tram ite como pretensión única. Cuando se presente
acumuladamente, se siguen las reglas establecidas para las otras pretensiones125.
