Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 830 of 1506 --

1. FUNCION Y FINES DEL DERECHO PENAL
La función del Derecho Penal como control social formal consiste en la protección de bienes
jurídicos. Se trata de la prevención de la lesión de bienes jurídicos. Debe tenerse en cuenta
sólo aquellas acciones que representan por lo menos un peligro objetivo de lesión de bienes
jurídicos. El derecho penal no protege valores estrictamente morales, sino de contenido es
trictamente jurídicos protegidos por la constitución.
El bien jurídico podemos definir como: B ien ju r íd ic o es un bien vital del grupo o del indi
viduo, que, en razón de su significación social, es amparado ju ríd ic a m e n te . Es, todo estado
social deseado que el derecho quiere asegurar contra lesiones. La significación de un bien ju
rídico no ha de ser apreciada aisladamente, sino tan sólo en relación conjunta con la totalidad
del orden social1.
La norma motiva el respeto de los bienes jurídicos. Busca crear en el ciudadano la inquietud
de protección de dichos intereses valiosos para la sociedad. En toda norma jurídica tiene que
existir un bien jurídico, individual o colectivo, que lo único que tiene que cumplir para su efi
caz protección es que no sea inconstitucional (por ej. No se puede proteger una determina
da moral individual o social porque la Constitución Política declara un pluralismo político e
ideológico), lo que no significa que todo lo recogido en la Constitución Política tiene que ser
protegido penalmente, sino solo aquello que los demás ámbitos del ordenamiento jurídico
no protegen previamente.
Para el fu n c io n a lism o el Derecho Penal lo que hace es proteger la vigencia de la norma y no
establecer un muro alrededor de bienes jurídicos: "el mundo social no está ordenado de manera
cognitiva, sobre la base de relaciones de causalidad, sino de modo normativo, sobre la base de compe
tencias y el significado de cada comportamiento se rige por su contexto... de allí que lo im portante sea
delim itar comportamientos socialmente inadecuados o socialmente adecuados... por eso el riesgo social
aceptado excluye el tipo”2.
Respecto a los fines d el D erecho Penal podemos señalar que esta rama de Derecho se con
figura y legitima por constituir un límite a la potestad punitiva del Estado. De esto, la pena se
