BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 831 of 1506 --

Tema 6: Temas de la Especialidad Penal
justifica en atención a los fines del Derecho Penal a los que sirve y siempre que se encuadre
dentro del más estricto respeto a los principios y garantías propios de un Estado social y de
mocrático de Derecho. Fuera de aquellos límites, como señala M ir Puig, la prevención penal
perderá su legitimación3.
La finalidad últim a que se persigue con el Derecho Penal es evitarquese lesionen ose pongan
en peligro esos bienes jurídicos, las normas penales son el instrumento para llevarlo a cabo, ya
que la pena con que amenazan intim ida al colectivo social de nocometerel delito. Ésta es una
fu n ció n de prevenció n g en eral del delito4.
Existe una segunda función que se atribuye al Derecho Penal, se trata de la I lamada función de
prevención esp ecial p o sitiva. Ésta, a diferencia de la anterior, no se dirige al colectivo social
sino que se dirige al sujeto que ya ha cometido el delitoy está cumpliendo la penay lo que se
persigue es reeducary resocializar al delincuente para que no reincida5.
2. PRINCIPIOS FUNDAMENTALES DEL DERECHO PENAL
Los principios del Derecho Penal son aquellas directrices de la doctrina que le han impuesto
barreras a la construcción del Derecho penal, de tal forma que éste no se extralimite y afecte
el Estado de Derecho.
A) L esivid a d : Principio básico garantista de un Derecho penal democrático. Esto es, que sólo
se persiguen hechos que afecten a un bien jurídico,ya que es el principio básico que des
de los objetivos del sistema determina qué es un injusto o un delito.
El principio de lesividad desde una consideración material implica el de lesividad de los
bienes jurídicos. No hay duda entonces que no se puede estar sino de acuerdo hoy, como
elemental a un sistema democrático, que los delitos han de definirse desde su lesividad
a los bienes jurídicos, ya que ellos surgen desde los objetivos que justamente definen el
sistemay por lo tanto a los delitosy las penas. Luego, ello quiere decir que la cuestión del
delito o del injusto no es de modo alguno, en primer término, una cuestión puramente
dogmática, sino que está regiday determinada político-criminalmente.
Cabe señalar, que la doctrina nacional y comparada es unánime en reconocer la necesi
dad de protección de bienes jurídicos colectivos, entendidos como aquellos bienes ju rí
dicos ligados al funcionamiento del sistemay las necesidades básicas de los sujetos. El
doble fundamento material de los b ie n e s ju ríd ic o s colectivos se sostiene en la realidad
social y en el modelo del Estado, en la medida que existen nuevas necesidades sociales
derivadas de la expansión de las relaciones jurídicas que surgen en la sociedad post in
dustrial, y que demandan su satisfacción a través de una eficaz protección jurídica para
enfrentar los riesgos de la modernidad6.
