Y NOMBRAMIENTO DE JUECES Y FISCALES 831

-- 832 of 1506 --

UBILEX
En esa perspectiva, Bustos Ramírez señala qu e «los bienes jurídicos colectivos hay que definirlos
a p a rtir de una relación social basada en la satisfacción de necesidades de cada uno de los miembros
de la sociedad o de un colectivo y en conformidad al funcionamiento del sistema social»7.
Para un sector de la doctrina8, los bienes jurídicos colectivos tienen autonomía frente
a los individuales y su titularidad pertenece a toda la ciudadanía por igual, siendo com
plementarios de los individuales en la medida que constituyen condiciones esenciales
para su adecuado funcionamiento, por lo tanto, la reacción penal frente a las ofensas que
sufren los bienes colectivos debe ser menor a la conminada respecto de los individuales.
La determinación del contenido y límites de los bienes jurídicos colectivos debe ser pro
ducto de una ponderación racional de diversos intereses legítimos, por ello, la tutela de
dichos bienes debe operaren relación con su propio contenido, sin necesidad de referen
cias implícitas o explícitas a los bienes individuales, y recurriendo sólo a tipos de lesión o
de peligro concreto.
B) Principio de legalidad: Este principio, usualmente expresado bajo la fórm ula latina “m -
llu m crimen, nuüapoenasinelege”, supone, según el pensamiento de Cesare Beccaria (1738-
1794), que: "(...) sólo las leyes pueden decretar las penas de los delitosy esta autoridad debe residir
en el legislador, que representa a toda la sociedad unida por el contrato social. Ningún magistrado
(que es parte de ella) puede con justicia decretar a su voluntad penas contra otro individuo de la
misma sociedad”.
Se puede concluir afirmando que el principio de legalidad en materia penal, y como ex
presión de su plural fundamento en la división de poderes y en la democracia representa
tiva9, en la seguridad jurídica, en el fin de prevención del Derecho Penal, y en su condición
de garantía de los derechos fundamentales del ciudadano frente al Estado, se plasma en
concretas exigencias o prohibiciones, dirigidas bien al legislador, bien a los Tribunales,
bien a ambos conjuntamente.-
i) Solamente la ley es la instancia normativa legitimada para establecer la punibilidad
de conductasy las penas correspondientes (Reserva de ley). De esta reserva se deriva
la exclusión en materia penal de otras fuentes de derecho, distintas de la ley formal:
disposiciones administrativas y normas consuetudinarias,
i i) La ley debe delim itar concreta y exhaustivamente la conducta punible y la pena con
la que se le conmina (Principio de tipicidad o de taxatividad de la ley penal).
iii) Prohibición de la analogía (aplicación analógica de la ley penal) y de su interpreta
ción extensiva (en contra del reo).
iv) Prohibición de dotar a la ley penal de efectos retroactivos desfavorables al reo y de
aplicación judicial de la ley penal con tal efecto retroactivo (irretroactividad).
v) Exclusión de la sanción penal y administrativa para un mismo hecho (nebisin ídem).
