BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 833 of 1506 --

Tema 6: Temas de la Especialidad Penal
C) Principio de Tipicidad. Mediante este principio se exige que, el legislador describa de
manera clara, precisa e inequívoca las conductas que han de considerarse como hechos
delictivos. Por esta razón, aquellas normas ambiguas, generales e indeterminadas, esto
es, las que consagran como hechos punibles comportamientos cuya descripción resulta
inexacta, difusa o imprecisa, que, desconozcan el mandato contenido en la norma, pues
permiten diferentes interpretaciones y dan lugara la arbitrariedad judicial.
En la moderna dogmática del Derecho Penal, toda conducta punible supone una acción
típica, antijurídica, culpable. En este sentido, la acción es típica, “en la medida que coincide
con una de las descripciones de delitos que se encuentran en su gran mayoría descritas en la parte
especial del Código Penal”10. Por tanto, quien a través de una acción “sustrae una cosa mueble
ajena con el ánimo de apropiársela antijurídicamente”, realiza el tipo del hurto.
La estricta vinculación a la tipicidad es una consecuencia del principio “nullum crimen sine
lege". Por consiguiente, no es posible derivar acciones punibles de principios jurídicos ge-
neralesy sin un tipo fijado.
Por lo tanto, se debe diferenciar la tipicidad del tipo, ya que este últim o es la actuación
que se expresa en la ley, mientras que la tipicidad es el medio de acoplamiento requerido
al momento de evaluar la conducta ejecutada con la norma promulgada por el legislador.
La tipicidad tiene las siguientes funciones, las cuales deben cumplirse de manera total y
efectiva:
• Función Motivadora: Es cuando el legislador expresa qué conductas son delitos y
qué consecuencias acarrean llevar a cabo dichos comportamientos. Lo que se busca
es la abstención de las personas a cometer delitos.
• Función de Garantía: Si una conducta no pertenece o no está ti pificada en el ordena
miento jurídico, por más grave que sea ésta, no será castigada por el aparato judicial,
límite de protección frente a la potestad punitiva del Estado.
• Función Seleccionadora de Actos o Indiciaría: Analiza los actos que ha realizado la
personay se observa si convergen en tipos penales.
D) Principio de Culpabilidad. Llamado también principio de la responsabilidad o culpa
bilidad, que proviene del principio democrático elemental de la dignidad de la persona
humana. El principio de culpabilidad se extrae del aforismo ‘''m illa poena sine culpa”, por
lo cual, de conformidad con este principio, no se puede castigara un sujeto que actúe sin
culpa11.
Únicamente puede ser objeto de sanciones los individuos que pueden comprender lo
injusto del hecho que realizan. Además, que su voluntad se fundamenta en esa com
prensión, lo cual implica la idea de responsabilidad. Como también reúne el concepto de
Derecho Penal de acto de conformidad con el cual ni interesa la personalidad del autor,
sino que importa el hecho delictivo que realiza. Por lo tanto, El principio de culpabilidad
10 M UÑOZ CO NDE, op.cit., p. 124.
11 Ibidem.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 833

-- 834 of 1506 --

UBILEX
implica que la pena tiene como límite la culpabilidad Es decir, la sanción no podría ser
superior a la culpabilidad del hecho.
Para el funcionalismo el principio de culpabilidad está compuesto de la siguiente mane
ra: El principio de culpabilidad significa que sólo ha de pensarse cuando se produce un
hecho culpable, y no después de la realización de un injusto culpable12. La culpabilidad,
la falta de fidelidad al derecho actuada en cuanto desautorización de la norma, a su vez,
es un asunto social y no es susceptible de ser descrita como suceso en la psique del autor.
En conclusión, únicamente el principio de culpabilidad autoriza al Estado a hacer respon
sable al individuo por sus delitos y a imponerle sanciones que afectan el núcleo de su
personalidad. Por otro lado, sólo el principio de culpabilidad puede evitar también que
el Estado, en interés de una protección preventiva de bienes jurídicos, llegue a castigar
incluso aquellos hechos que el autor no podía evitar y por los cuales no se puede diri
gir ningún reproche personal. De este modo, el principio de legitimación conocido como
"culpabilidad" opera, a la vez, de modo necesario, como principio de limitación y, más allá
de todas las causas de exclusión de la culpabilidad configuradas preventivamente, ha
propiciado una extraordinaria depuración del Derecho Penal.
Para un sector de la doctrina la relación entre la culpabilidady prevención tampoco pue
de ser otra en la determinación de la magnitud de la pena, esto es, en la medición de la
pena, pues resultaría paradójico que el principio de culpabilidad, que es insuficiente para
fundamentar el “si” de la pena, fuera determi nante a la hora de fundamentar el “quantum ”
de la misma13.
Al principio de culpabilidad le corresponde en la medición de la pena, como en la funda-
mentación de la pena, una mera función de limitación, im pidiendoque se tomen en con
sideración todas aquellas circunstancias que el autor no pudo conocery que, por lo tanto,
no se le pueden reprochar. El significado del principio de culpabilidad para la medición
de la pena sólo puede consistir en la exigencia de que únicamente se utilicen en la medi
ción de la pena, aquellos aspectos que se encuentran sometidos al poder de evitación del
autor.
E) Principio de Proporcionalidad. Consecuencia del principio de igualdad es también el de
proporcionalidad, en cuanto la pena ha de ser proporcional a la gravedad del hecho, tanto
por su jerarquía respecto del bien jurídico afectado, como por la intensidad del ataque al
mismo. Ha de excluirse penas iguales para hechos diferentes, puesto que esto implica
también discriminación. Una afección a la vida nunca puede tener la misma pena que
una afección al patrimonio.
En general, de la proporcionalidad se predica el adecuado equilibrio entre la reacción
penal y sus presupuestos, tanto en el momento de la individualización legal de la pena
(proporcionalidad abstracta) como en el de su aplicación judicial (proporcionalidad con
creta).
12 MIR PUIC, op. cit., p. 86.
13 Ibídem.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 835 of 1506 --

Tema 6: Temas de la Especialidad Penal
Cabe precisar que el principio de proporcionalidad se erige en un elemento definidor de lo
que ha de ser la intervención penal, desde el momento en que trata de traducir el interés de la
sociedad en imponer una medida de carácter penal, necesariay suficiente, para la represión y
prevención de los comportamientos delictivos, y por el otro, el interés del individuo en la efi
cacia de una garantía consistente en que no sufrirá un castigo que exceda el límite del mal
causado, en otros términos, la minimización de la violencia en el ejercicio del ius pumendi. Así,
la justa medida de la pena se configura como un princi pió rector de todo el sistema penal.
Conforme a este principio la actuación dolosa se califica como más grave que la im pru
dente, la reacción penal a la tentativa sea de menor entidad que la consumación, etc.
El principio de proporcionalidad, también denominado prohibición de exceso, exponiendo
otros principios que vendrían a integrarlo14. Así, el principio de finalidad, vendría en primer
lugar a establecer como presupuesto que el fin perseguido por la norma deba ser legítimo,
es decir, el bien o interés protegido a través de la limitación debe estar amparado constitu
cionalmente; el principio de adecuación, vendría a operar como un examen de idoneidad
y coherencia con el fin perseguido; el principio de necesidad por su parte exigiría que la in
tervención de la norma produzca el menor daño posible, y que no exista otra medida alter
nativa quesea igualmente eficaz; mientras que el principio de proporcionalidad en sentido
estricto vendría a establecer una ponderación racional entre el beneficio para el bien común
que se obtiene de la limitación y el perjuicio que sufre el derecho afectado.
En conclusión, laesencialidadde este principio consiste en queopera como un límite a to
das las restricciones de los derechos esenciales o fundamentales, derivando su aplicación
del principio del Estado de Derecho, por lo cual tiene rango constitucional.
F) Principio de humanidad de las penas. Por este principio se prohíbe la tortura y las pe
nas o tratos inhumanos o degradantes. Se trata de no acarrear sufrimientos de especial
intensidad, o penas inhumanas o que provoquen una humillación o sensación de envile
cimiento que provoque en el condenado una aplicación de la pena con un nivel superior
al que corresponda por la simple aplicación de la condena.
La humanidad de las penas se debe entender dentro del contexto de la dignidad de las
personas. Nuestra Constitución señala que los seres humanos nacen iguales en digni
dad y derechos. Todos los seres humanos, sin excepción, delincuentesy honorables. Aun
cuando la pena es un mal impuesto al condenado, que importa la privación o restricción
de algún derecho, el reconocimiento de la dignidad de la persona humana por la consti
tución exige no imponerse penas crueles o degradantes, evitarse las sanciones estigmati-
zadoras, tendientes a suprimir las penas como la pena de muerte o castigos corporales.
C) Principio de intervención mínima. Se expresan dos características del Derecho Penal
subsidiariedad o últim a ratioy fragmentariedad. Atendido a que la aplicación del Dere
cho Penal importa la más violenta afectación legítima de derechos que puede sufrir un
individuoy al hecho de que regula las normas básicas sobre las que descansa la conviven
cia humana pacífica, es que se hace necesario restringirel ámbito de lo punible15.
14 Ibidem, p. 88.
15 Ibidem, p. 89.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 836 of 1506 --

H) Principio de subsidiaridad. Mediante este principio se entiende al imponer la sanción
penal como último medio de contención de lo ilícito El Derecho Penal y el recurso de
la pena sólo deben ser empleados cuando el ataque al bien jurídico no pueda impedirse
acudiendo a los medios de solución dispuestos por otras ramas del derecho. Lo contrario,
además de deslegitimar el sistema penal, conlleva el riesgo de que el Estado sea incapaz
de perseguir todo lo que prohíbe16.
I) Principio de fragmentariedad. La aplicación de este principio importa que el Derecho
Penal, además de castigar sólo aquellos comportamientos peligrosos o lesivos para un
bien jurídico que no sean susceptibles de evitarse acudiendo a otras formas de conten
ción, deba actuar sólo ante los ataques más intolerables en contra de aquellos bienes
jurídicos esenciales para la convivencia17. Tiene estrecha vinculación al principio de lega
lidad, lo anterior se expresa en que las conductas que la ley amenaza con una pena se
encuentran descritas en ella y se precisa de la mejor forma posible, todo lo que quede
fuera de ella se encuentra al margen de la reacción punitiva estatal, aun cuando revista
caracteres de ilicitud o de lesión a bienes jurídicos.
3 . LA LEY PENAL
A. Aplicación de la ley penal en el espacio.- La ley puede ser aplicada tanto en el tiempo como
en el espacio (tiempo-vigencia de la ley), (espacio-territorio). En cuanto al espacio podemos
señalar que la ley tiene un carácter territorial, en cuanto los delitos que han sido cometidos o
perpetrados en el territorio nacional.
La ley penal es esencialmente territorial esto es que rige solamente para los delitos cometidos
en el territorio del estado del cual emana18. La validez de la ley penal se obtiene mediante la
consideración de varias disposiciones legales, la extraterritorialidad de la ley penal es sólo de
carácter objetivo nunca de carácter judicial, sólo excepciones por ejemplo cuando la autoridad
viaja con pasaporte diplomático, a este principio lo acompañan el principio de la defensa, el
de la personalidady la universalidad.
Esta materia consagra tres principios básicos19:
i) El principio de la territorialidad. Es un principio de carácter fundamental que hace regir
la ley penal en todo el territorio nacional. Este principio se encuentra consagrado en el
Art.1. Código Penal. El concepto de territorio es de aspecto jurídicoy no físico ya que com
prende la superficie terrestre dentro de los límites naturales y convencionales de un país
incluyendo ríos, lagos, islas, etc., sobre los cuales se ejerce soberanía incluyendo mar te
rritorial, espacio aéreo, el subsuelo, incluyendo naves y aeronaves de las fuerzas armadas
cuando ocupan un territorio determinado.
i i) Principio de la defensa. Señala que el principio de la territorialidad encuentra su funda
mento en que el orden jurídico de un estado no se ve afectado por sucesos que ocurran
