cional se le atribuya competencia para ser aplicada a ciertos delitos que se perpetre en el
extranjero en virtud de las repercusiones que este hecho ilícito tendría sobre la economía
y sobre el orden jurídico nacional.
iii) Principio de la universalidad. Éste tiene su fundamento en la idea de la existencia de una
comunidadjurídica de carácter internacional todavezqueel objeto del Derecho Penal es
la protección de los derechos humanos más que la soberanía nacional. En consecuencia,
se puede afirmar que el derecho que tiene cada Estado a juzgar nace de la circunstancia
deque el delincuente se encuentra bajo la jurisdicción del estadoy que no hayasido juz
gado en otra parte.
B. La validez temporal de la ley penal (El principio fundamental: aplicación de la ley v ig e n
te en el momento de comisión del delito.)
La exigencia de la ley previa tiene jerarquía constitucional, se refiere tanto a la tipificación del
hecho punible como la amenaza de pena, a las medidas de seguridad y a las consecuencias
accesorias del delito.
La ley penal debe entenderse como aplicable a hechos que tengan lugar sólo después de su
vigencia. Quedan eliminadas las llamadas leyes ex postfacto. La garantía de legalidad, tiene el
claro sentido a) de impedir que alguien sea penado por un hecho que, al tiempo de su comi
sión, no era del itoo no era punible o perseguí ble, y b) de prohibir que a quien cometa un delito
se le aplique una pena más gravosa que la legalmente prevista al tiempo de la comisión20.
La ley penal, una vez sancionada, rige desde el momento en que empieza a obligar por su pro
mulgación y publicación y hasta que deja de ser obligatoria por su derogación.
La vigencia de una ley cesa21: a) por otra ley posterior que, expresamente deroga la primera, o
que tácitamente la abroga, por contener disposiciones contrarias o regular de modo completo
la materia tratada en la anterior; b) por llevaren el propio texto o en el de otra ley, de igual o
superior rango, la fecha de su caducidad (leyes temporales); c) por haber desaparecido el obje
to, las circunstancias o los privilegios personales que le dieron nacimiento.
