UBILEX
i) El momento de comisión del delito. Así como el principio territorial requería determinar
el lugarde comisión, la exigencia de la ley previa exige determinar el tiempo de comisión
del delito. El delito se comete en el momento de ejecución de la acción o en el momento
en que debía realizarse la acción om itida o en el del resultado no impedido. Por tiempo de
la comisión del hecho debe entenderse, en consecuencia, el de la realización de la acción
típica (y no el de la producción del resultado).
El profesor Raúl Zaffaroni señala cuando una ley más gravosa entra en vigencia en un mo
mento posterior al comienzo de la acción, existe un tramo de ella que no está abarcado
por latipicidad de la nueva ley, salvo que se haga una aplicación retroactiva de ella22.
La ley penal quiere prevenir la comisión de hechos punibles imponiendo deberesy ame
nazando su incumplimiento con la aplicación de una pena. La ley quiere ante todo m oti
var al autory esto sólo podría hacerlo una ley preexistente a la decisión del autor.
ii) Determinación de la ley más favorable. Requiere una determinación concreta de las dos
situaciones legales surgidas de la reforma legal posteriora la comisión del hecho. La com
paración es concreta porque debe referirse al caso que se juzga.
La comparación referida a penas principales no es problemática cuando se trata de penas
de la misma especie. La ley más favorable será la que permita una pena mínima menor.
Cuando las penas son de distinta especie habrá que considerar-además del m áxim oydel
mínimo-, los elementos diferenciales de ambas penas y deducir de ellos cual es el más
favorable al acusado o condenado23.
iii) El principio de retroactividad benigna. Propugna la aplicación de una norma penal pos
teriora lacomisión del hecho delictivo, a condición de que dicha norma contenga disposi
ciones más favorables al actor. Ello, sin duda alguna, constituye una excepción al principio
de irretroactividad de la aplicación de la ley sustentada en razones político-criminales, en
la medida en que el Estado no tiene interés (o no en la misma intensidad) en sancionar
un comportamiento que ya no constituye delito (o cuya pena hasido disminuida) y, esen
cialmente, en virtud del principio de humanidad de las penas, el cual se fundamenta en la
dignidad de la persona (artículo 1o de la Constitución) (STCExp. N° 02744-201 o-PHC/TC)
iv) Leyes intermedias más favorables24. Se denomina ley intermedia la que entra en vigor
después de la comisión del hecho, pero es modificada nuevamente antes de la sentencia
definitiva de últim a instancia, por otra ley más rigurosa. Si la ley intermedia resultara
más favorable que la vigente en el momento de comisión del delito habrá que aplicarla
aunque haya dejado de regiren el momento de la sentencia definitiva, porque así lo esta
blece el principio de la retroactividad de la ley más favorable.
Las dudas, hoy definitivamente zanjadas, se presentaban una vez dictada la sentencia de
finitiva y durante el tiempo de ejecución. Sin embargo, los límites temporales que deben
tomarse en cuenta son los de la comisión del hecho y de la extinción de la condena. Por
duración de la condena debe entenderse cualquier tiempo en que persista algún efecto
