Tema 6: Temas de la Especialidad Penal
jurídico de la sentencia condenatoria. La CADH establece expresamente la excepción al
principio de irretroactividad en el caso de la ley más benigna, sea que se haya sancionado
antes de la sentencia o bien durante la ejecución de la misma.
v) El criterio de la ultraactividad de la ley penal más gravosa25. Al tratarse de leyes dicta
das para reforzaren circunstancias excepcionales la protección de ciertos bienes jurídicos,
por lo general, contienen agravaciones de las penas o incriminaciones excepcionales que
permiten llevar a cabo la finalidad perseguida por la ley. Tomando como punto de partida
el método teleológico, se argumentó que la ultraactividad de las leyes penales tempora
les constituía una excepción al principio de la retroactividad de la ley penal más favorable,
que quedaba derogado por razones de prevención general.
C. La validez personal de la ley p e n a l- La ley penal se aplica en principio a todos por igual.
Esto es una consecuencia de la garantía de igualdad con rango constitucional expreso en las
normas nacionales. Art. 2, inc. 2 de la Constitución Política.
No obstante, debe mencionarse respecto de algunas personas que desempeñan ciertas fun
ciones, el propio texto constitucional establece el cumplim iento de determinados requisitos
para que puedan ser sometidas a los jueces en caso de delito. A saber26:
i. Inmunidad: Corresponde a los congresistas, Defensor del Pueblo y magistrados del Tri
bunal Constitucional (artículos 93°, 161oy 201ode la Constitución), no pueden ser procesa
dos ni detenidos sin autorización del Congreso o de la Comisión Permanente, o en el úl
tim o caso autorización del Pleno del Tribunal. Es un obstáculo para la persecución penal.
Desde que son elegidos hasta un mes después de haber cesado en el cargo, salvo delito
flagrante donde son puestos a disposición de la autoridad.
ii. Inviolabilidad: Congresistas, Defensor del Pueblo y magistrados del Tribunal Constitu
cional, durante el ejercicio de sus funciones; no son responsables por las opiniones y vo
tos que emiten en el ejercicio de sus funciones: excusa absolutoria.
iii. Prerrogativas de otros funcionarios: Antejuicio: Presidente de la República, Ministros,
miembros del Tribunal Constitucional, del Consejo Nacional de la Magistratura, vocales
de la Corte Suprema, fiscales supremos, Defensor del Pueblo y Contralor de la República
(artículo 99° de la Constitución). No están sujetos a acusación de cualquier persona o ins
tancia de los delitos o violación cometidos en el ejercicio de sus funciones.
iv. Exenciones del Derecho Internacional Privado: jefes de Estados Extranjeros, represen
tantes diplomáticos, tropas extranjeras, sometidos a las leyes penales de su lugar de ori
gen.
4. TEORÍA DEL DELITO
El delito, en sentido dogmático, es una acción u omisión típica (tipificada por la ley), antijurí
dica (contraria a Derecho), culpabley punible. Supone una conducta infraccional del Derecho
penal, es decir, una acción u omisión tipificaday penada por la ley.
