26 Ibidem, p. 106.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 840 of 1506 --

UBILEX
Von Liszt señala, que, el delito es el acto culpable, contrario a derecho y sancionado con una
pena27.
El concepto ofrece dos acepciones:
a) Desde una noción amplia. En este sentido delito equivale a toda especie delictiva, ha
hecho punible. Se emplea usualmente con este significado pero algunas veces se utiliza
frecuentemente la expresión infracción criminal, hecho delictivo o, simplemente, infrac
ción.
b) Desde una noción restringida o propia. Designaba la más grave de las clases de hechos
punibles y para designar dos clases de infracciones, habrá que adjetivar el delito como
grave o menos grave para acabar de especificar la clase de hecho punible de que se trata.
Según la Escuela Técnico Jurídica. El delito es una acción típicamente antijurídicay culpable
castigada por la Ley con una pena.
La dogmática jurídico penal es la disciplina que se ocupa de definir el delito a partir de la
regulación positiva. Dado que se trata de una ciencia cuyo método no es la verificación, sino la
comprensión, la determinación del contenido del delito no puede pretender tener un carácter
exacto e inm utable.28
Estructura del delito: A partír de la definición usual de delito (acción típica, antijurídicay cul
pable), se ha estructurado la teoría del delito. Así se divide esta teoría general en:
a. La Acción.
b. Tipicidad.
c. Antij uricidad.
d. Culpabilidad.
Aunque también algunos autores agregan a lo anterior, la punibilidad. No obstante, aunque
hay un cierto acuerdo respecto de tal definición, no todos le atribuyen el mismo contenido. Así
son especialmente debatidas las relaciones entre sus diversos elementos y los componentes
de cada uno de ellos.
A) ACCIÓN.- La conducta humana (acción uomisión) es la base sobre la cual descansa toda la
estructura del delito. Si no hay acción humana, si no hay conducta, no hay delito29. Sin embar
go, el concepto de acción engloba igualmente el de omisión, en la cual existe una conducta en
la que conscientemente se evita una acción concreta.
Constituye el soporte conceptual de la teoría del delito y el eje de la consideración axiológica
y natural del hecho punible.
Concepto causal de acción: Von Liszt como máximo representante del causalismo señala que
la acción es conducta voluntaria hacia el mundo exterior; más exactamente: modificación,
