Carlos Pérez del Valle, Colección Los Argonautas, Granada, 1995, p. 77-
28 SILVA SÁN CH EZ, jesús María .Aproximación al Derecho Penal contemporáneo. Barcelona. 1992. p. 170.
29 VON LISZT, obcit. p. 79.
