Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 841 of 1506 --

Tema 6: Temas de la Especialidad Penal
es decir, causación o no evitación de una modificación (de un resultado) del mundo exterior
mediante una conducta voluntaria30.
Beling, otro representante del causalismo, hace mención que la acción debe afirmarse siem
pre que concurra una conducta humana llevada por la voluntad, con independencia de en
qué consista esa voluntad (es decir, no considera dentro de su concepto el contenido de la
voluntad).
Concepto finalista de acción: Como introducción al concepto finalista de acción diremos que
los miembros de la sociedad pueden actuar conscientes del fin, es decir, proponerse fines,
elegir los medios requeridos para su obtención y ponerlos en movimiento con conciencia del
fin. Esta actividad final se llama "acción”.
El objeto de las normas penales es la conducta humana, esto es, la actividad o pasividad cor
poral del hombre sometida a la capacidad de dirección final de la voluntad. Esta conducta
puede ser una acción (el ejercicio efectivo de actividad final), o la omisión de una acción (el no
ejercicio de una actividad final posible).
Hanz Welzel como máximo representante del finalismo señala que la acción se basa en que
el hombre, gracias a su saber causal, puede prever, dentro de ciertos límites, las consecuencias
posibles de su actividad, ponerse fines diversos y dirigir su actividad, conforme a su plan, a
la consecución es estos fines. Actividad final es un obrar orientado conscientemente desde
el fin, mientras que el acontecer causal no está dirigido desde el fin, sino que es la resultante
causal de los componentes causales existentes en cada caso. Por eso la finalidad es “vidente”,y
la causalidad "ciega”.
Esta conducta puede ser una acción (el ejercicio efectivo de actividad final), o la omisión de
una acción (el no ejercicio de una actividad final posible). Para la configuración de esta teoría
se menciona que la dirección final de una acción se lleva acabo en dos etapas31:
i) La primera transcurre totalmente en la esfera del pensamiento. Empieza con la anticipa
ción (el proponerse) del fin, que el autor quiere realizar. De ello sigue la selección de los
medios de la acción para la consecución del fin. El autor determina los factores causales
que son requeridos para el logro del mismo.
ii) De acuerdo con la anticipación mental del fin y la elección de los medios, el actor efectúa
su acción en el mundo real. Pone en movimiento, conforme a su plan, los medios de ac
ción escogidos con anterioridad, cuyo resultado es el fin. La segunda etapa de la dirección
final se lleva a cabo en el mundo real.
Concepto funcional de acción: Claus Roxin hace mención que la acción debe entenderse
como ia “manifestación de la personalidad”, esto es, “todo lo que se puede a trib u ir a un ser humano
como centro anímico, espiritual de acción”32 para diferenciarlo de los efectos que parten únicamen
te de la esfera corporal, sin estar sometidos al control del "yo”.
30 Ibidem.
31 ROXIN, Claus, op. cit., p. 280.
32 Ibidem.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 841

-- 842 of 1506 --

UBILEX
Las acciones dolosas e imprudentes son manifestaciones de la personalidad tanto como las
omisiones, e incluso la omisión por imprudencia inconsciente es una manifestación de la per
sonalidad que se le puede imputar al sujeto como infracción de la norm ay contraria a la pro
hibición, como “obra” suya.
La acción como “exten o rizad ó n de la personalidad”, el comportamiento es “la relación del yo
consciente y físicamente libre con el mundo exterior manejando procesos causales. Por ejem
plo, “un hombre habrá actuado si determinados efectos procedentes o no del mismo, se le
pueden atribuirá él como persona, o sea como centro espiritual de acción, por lo que se puede
hablar de "una manifestación de la personalidad”33.
No constituyen acción los pensamientos y los impulsos de la voluntad, en tanto permanecen
en el plano interno y no se ponen en relación con los sucesos del mundo exterior, es decir,
no son manifestaciones de la personalidad. Por lo tanto, el concepto personal de acción es
un concepto normativo, porque el criterio de la manifestación de la personalidad designa de
antemano el aspecto valorativo decisivo, que es el que cuenta jurídicamente para el examen
de la acción.
Por otro lado, Ghunther Jakobs menciona que la acción sería “la causación de un resultado evi
table”, digamos que se trata de “una expresión de sentido”, dicho de otra manera: "la realización
individualy evitable del resultado”}/ la omisión "la no evitación evitable del resultado”34. Es un concepto
de naturaleza social, y lo causal está enfocado desde el contexto social. Así vemos que la socie
dad “aceptará” ciertos riesgos y éstos estarán excluidos de reproche. El delito para este autores;
quiebra la vigencia de la norma, es una comunicación defectuosa, una desautorización de la
norma o falta de fidelidad a la misma. La norma es una expectativa social institucionalizada.
En consecuencia, el concepto normativo de la acción nos permite concluirque existe ausencia
de acción en los siguientes supuestos:
• Movimientos reflejos: actos no procesados por el cerebro. Ejemplo: reacciones nervio-
musculares. Son distintos de los actos de cortocircuito, los cuales refieren a reacciones
explosivas, impulsivas o instintivas donde sí se da una acción en sentido jurídico penal
(ahí se traslada el análisis a la culpabilidad).
• Fuerza Física Irresistible: (vis absoluta) la fuerza puede provenir de un tercero o de la na
turaleza. Es distinta de la coacción (viscompulsiva), en lo que se vicia no es la acción sino la
voluntad de quien actúa.
• Estado de Inconsciencia: producido por hipnosis, embriaguez, sonambulismo.
Ahora bien, no debe confundirse los supuestos anteriores cuando la ausencia de acción
fue provocada dolosamente por el agente con el fin de cometer un delito llamada por la
doctrina A ctio Libera In Causa.35
33 Ibidem.
34 JAKOBS, Giinther, op. c¡t, p. 190.
35 ZAFFARONI, Raúl, op. cit., p 236.
