Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 843 of 1506 --

Terra 6: Temas de la Especialidad Penal
Teorías:
i. Teoría de Adelantamiento (principio de coincidencia): el comienzo de la acción típica se
produce con la provocación del estado de defecto. Porello, no existe quiebre del principio
de coincidencia.
ii. Teoría de la Excepción: se rompe con el principio de coincidencia. Señala que la acción
típica relevante no consiste en la producción del defecto, sino en el hecho cometido en
estado defectuoso.
¡ii. Teoría de la Función Sistémica: la imputación a la persona debería hacerse en estos ca-
sos basándose en la competencia por la causación del estado de defecto.
Tratamiento respecto a las personas jurídicas.-
Teoría del actuar por otro36: consecuencia del societas delinquere non potest. Lo que importa es
quien actúa como directivo u órgano de una persona jurídica o en representación de la misma
lo haga de modo legal y tenga, por tanto, capacidad de decisión, lo que permite la respon
sabilidad individual. En efecto, si bien la empresa ostenta el rol especial, la responsabilidad
penal se traslada al representante que resulta competente por el incumplimiento de deberes
positivos derivados de una relación institucional específica que afecta, en principio, a su repre
sentado (persona jurídica)37.
Como bien señala Percy García Cavero: «(..J la imputación del hecho al representante cobra una
especial configuración en los delitos de infracción de un deber. No se trata de demostrar una compe
tencia por el dominio de la esfera de organización del representado, sino una transferencia de deberes
institucionales que surgen de la posición especial del representado, siempre y cuando esta transferencia
del deber resulte posible mediante la relación de representación. El representante habrá realizado el tipo
penal correspondiente por el incum plim iento de un deber institucional transferido por el representado,
siendo aquí también irrelevante si este incum plim iento tiene lugar mediante una acción u omisión»38.
B) LA TIPIC1PA P.- Se denomina tipicidad al encuadramiento de la conducta humana al tipo
penal (el tipo). Así cuando la ley describe el homicidio diciendo "el que matare a otro”, la con
ducta típica está dada por el hecho concreto de matar a otro.
El profesor Muñoz Conde los define como la adecuación de un hecho cometido a la descrip
ción que de ese hecho se hace en la ley penal. Es una consecuencia del principio de legalidad
y el de intervención mínima39. En el tipo se incluyen todas las características de la acción pro
hibida que fundamenten positivamente su antijuricidad. Pero no siempre se pueden deducir
directamente del tipo estas características y hay que dejaral juez la tarea de buscar las carac-
36 A r t íc u lo 2 7 o d e l C ó d ig o P e n a l:
«El que actúa como órgano de representación autorizado de una persona jurídica o como socio representante autorizado
de una sociedad y realiza el tipo legal de un delito es responsable como autor, aunque los elementos especiales que
fundamentan la penalidad de este tipo no concurran en él, pero sí en la representada».
