terísticas que faltan. Ello se debe a la dificultad de plasmar legalmente tales características en
el tipo legal.
El profesor Muñoz Conde40 refiere que el elemento de tipicidad cumple dos funciones: i) Fun
ción de instrucción: la norma cumple de comunicación con los sujetos sobre las conductas
que no deben realizarse; y, ii) Función indiciaría de la antijuricidad: indicio de la existencia
de un delito.
i) TipoObjetivo.-
El-tipo objetivo positivo está contenido por el bien jurídico, sujetos, acción típica, elemen
tos descriptivos y normativos:
• Bien jurídico protegido (objeto jurídico): la norma penal siempre busca prote
ger un interés necesario para la vida en sociedad. Hay bienes jurídicos individuales
(ejemplos: la vida, la salud) y bienes jurídicos supraindividuales (ejemplos: el am
biente, la hacienda pública) todos con reconocimiento en la constitución.
• Sujeto Activo: es quien realiza el tipo penal, directamente (autoría directa), u tili
zando a otro sujeto (autoría mediata); o en conjunto con otras personas (coautoría).
También se incluye a los partícipes (instigadores o colaboradores del delito).
• Sujeto Pasivo: es el titu lar del bien jurídico que ha sido afectado por la acción delic
tiva. No siempre el sujeto pasivo es el mismo sujeto sobre quien recayó físicamente
la acción típica. Tampoco coinciden siempre el sujeto pasivo con el perjudicado por
el delito (que es quien tiene el derecho de acción: de denunciar el delito ante las
autoridades estatales).
• Acción Típica: el tipo penal describe una determinada conducta (desvalor de ac
ción), la cual sanciona con una determinada pena.
• Objeto material: Es el o b je t o s o b r e el c u a l re c a e la a c c ió n t íp ic a .
• Elementos descriptivos: son los elementos del tipo que no requieren de mayor in
terpretación, debido a que son aprehensibles por los sentidos, se puede recurrir a la
experiencia externa e interna. Ej. el término "otro" empleado en el tipo de homicidio.
• Elementos normativos: son aquellos elementos del tipo que deben ser interpreta
dos a la luz de otras disciplinas o cuerpos normativos. Son valoraciones con las que
se caracterizan los elementos descriptivos. Ej. El térm ino "prenda" en el art. 193o del
Código Penal.
Imputación objetiva:
DOCTRINA CAUSALÍSTICA:
Concibe el nexo entre acción y resultado como
mera relación de causalidad -e n TÉRMINOS
NATURALÍSTICOS (ONTOLÓGICOS).
DOCTRINA ACTUAL:
Concibe dicha relación en TÉRMINOS
NORMATIVOS (AXIOLÓGICOS)
