Tema 6: Temas de la Especialidad Penal
a. Teorías de la relación de causalidad:
a.i Equivalencia de condiciones: (Teoría general izadora) debe considerarse causa toda con
dición de un resultado que no puede ser suprimida mentalmente sin que desaparezca el
resultado concreto.
Críticas:
• Es demasiado relativa: infinita cantidad de causas, la causalidad es solo el primero,
pero no el único presupuesto de la imputación.
• La supresión mental presupone ya lo que debe averiguarse mediante la misma: no
llega a descubrir la causa (verifica lo que ya se sabe).
• Puede inducir a error en los siguientes casos:
Causalidad hipotética: (ejemplo: si me niego a fusilar en guerra, cualquier otro
lo habría hecho).
Causalidad alternativa-, (ejemplo-, A y B ponen veneno en café de C y cada uno
por sí s o lo -s in la actuación del otro - hubiera provocado la muerte de C).
Curso causal irregular: (ejemplo: envío de viaje en avión a mi suegra con la espe
ranza de que se caiga el avión y muera).
Curso causal complejo: (ejemplo: causo lesiones leves en A y la ambulancia que
transporta a A al hospital choca, causando la muerte de A).
a.2 Adecuación: (Teoría individualizadora) busca depurar y encontrar la causa adecuada
(apta para producir el resultado).
NO ES TEORÍA CAUSAL, SINO DE IMPUTACIÓN: intenta dar una respuesta a qué circuns
tancias causales son jurídicamente relevantes. Complementa la teoría de la equivalencia.
Utiliza dos criterios de selección:
• Previsibilidad Objetiva: se basa en los criterios de lo que hubiera hecho un hombre
promedio en las mismas circunstanciasy lo que la sociedad considera adecuado (co
nocimiento social de la causa).
• Diligencia Debida: se realiza una prognosis objetivo posterior: el juez se coloca pos
teriormente (en el proceso) en el punto de vista de observador objetivo que juzgue
antes del hecho y disponga de los conocimientos de un hombre inteligente del co
rrespondiente sector del tráfico y además del saber especial del autor para m edir si
el sujeto actuó diligentemente.
Críticas:
• ¿Cómo defm irqué es un hombre promedio?
• Hay causas que la sociedad todavía no las incorpora como normales (ejemplo: algu
nas personas consideran que el celular produce cáncer).
b. Teoría de la imputación objetiva: Desvalor de acción y desvalor de resultado:
La imputación objetiva será un problema de la parte general cuando el tipo requiere un
resultado en el mundo exterior separada en el tiempo y el espacio de la acción del autor
