(delitos de resultado) y será un problema de la parte especial cuando la imputación al
tipo objetivo se agota en la subsunción en los elementos del tipo respectivo (delitos de
peligro).
b.i Imputación objetiva según Roxin:
“(...) un resultado causado por el sujeto que actúa sólo debe ser Imputado al causante como su
obra y sólo cumple el tipo objetivo cuando el comportamiento del autor haya creado un riesgo
no perm itido para el objeto de acción (i ) cuando el riesgo se haya realizado en el resultado con-
, creto (z )y cuando el resultado se encuentre dentro del alcance del tipo”41.
A juicio de este autor, la imputación del tipo objetivo presupone la realización de
un peligro comprendido dentro del alcance del tipo penal, creado por el autor y no
encubierto por el riesgo permitido. La variable es el riesgo y se materializa en la re
glamentación de los comportamientos en la sociedad. Por lo tanto, se propone una
serie de criterios normativos, cuyo denominador común está en el “principio de ries
go", según el cual, partiendo del resultado, el tema estaba en determinar si la con
ducta del autor creó o no un riesgo jurídicamente relevante de lesión típica de un
bien jurídico en relación con dicho resultado.
Debe verificarse los siguientes presupuestos42:
i. Que exista un nexo de causalidad (a veces no es necesario como en los casos de
omisión impropia o la autoría mediata).
ii. Se realice una conducta contraria al fin de la norma.
iii. Que la conducta entrañe un peligro cierto para el bien jurídico tutelado.
iv. La lesión del bien jurídico debe producirse a consecuencia de la conducta
a. Los criterios propuestos por Roxin para determinar el juicio de imputación
objetiva del resultado son los siguientes43:
v. La disminución del riesgo (ejemplo: A desvía una piedra que viene volando para
que golpee a B en la pierna en vez de en la cara);
vi. La creación de un riesgo jurídicamente relevante (ejemplo: tenencia ilegal de
armas);
vii. El incremento del riesgo permitido (ejemplo: conduce un vehículo en estado de
ebriedad); y,
viii. La esfera de protección de la norma.
b.2 Imputación objetiva según ]akobs:
La teoría de la imputación objetiva cumple un papel fundamental que permite de
term inar los ámbitos de responsabilidad dentro de la teoría del delito, así faculta
constatar cuando una conducta tiene carácter (objetivamente) delictivo.
