Tema 6: Temas de la Especialidad Penal
La vida social se organiza con permiso de riesgo44: todo contacto social entraña ries
go, pero por ello no ha de ser evitado. Aquello que está permitido se rige principal
mente por la configuración social generada a lo largo del tiem poy no por un cálculo
aislado de costes y beneficios.
Los comportamientos que generan un riesgo permitido son atípicos,ya que no pue
den ser considerados como justificados. Se trata del juicio objetivo, pero no de un
experto, sino del titu lar de un rol que en desempeño de ese rol puede realizar tal
actividad de modo socialmente adecuado. El rol del mejor experto sólo es relevante
cuando la actividad sólo puede ser realizada de modo socialmente adecuado portal
especialista (ejemplo: central nuclear).
La teoría de la imputación objetiva se divide para este autor en dos niveles45:
a) La calificación del comportamiento como típico (imputación objetiva del com
portamiento); y,
b) La constatación -e n el ámbito de los delitos de resultado- de que el resultado
producido queda explicado precisamente por el comportamiento objetivamen
te imputable (imputación objetiva del resultado).
En el primer nivel de la imputación objetiva, la imputación de comportamientos,
Jakobs propone cuatro instituciones dogmáticas a través de las cuales ha de estable
cerse el juicio de tipicidad46:
i. El riesgo permitido: Parte de una definición claramente normativa del “riesgo”,
desligada de probabilidades estadísticas de lesión. El riesgo permitido se define
como el estado normal de interacción, es decir, como el vigente status quo de
libertades de actuación, desvinculado de la ponderación de intereses que dio
lugar a su establecimiento, hasta el punto de que en muchos casos se trata de un
mecanismo de constitución de una determinada configuración social por acep
tación histórica; dicho de otro modo, se refiere más a la identidad de la sociedad
que a procesos expresos de ponderación.
Bajo el rótulo de riesgo permitido se agrupan dos bloques de supuestos47: por una
parte, casos en que una determinada actividad riesgosa es jurídico-penalmente
permitida en atención a ciertas circunstancias, ya sea en virtud de una positiviza-
ción o reglamentación expresa (como sucede en el tráfico viario, el ámbito indus
trial, competiciones deportivas, juegos autorizados de apuestas, etc.), ya sea en
ausencia de dicha reglamentación (los clásicos deberes de cuidado traducidos en
la lexartis, por ejemplo, en la práctica médica). Por otra parte, se encuentran aque
llas conductas que, aunque generadoras de riesgos, se hallan caracterizadas por
