íi. Principio de confianza: Determina cuándo existe, con ocasión del desarrollo de
una actividad generadora de un cierto riesgo (permitido), la obligación de tener
en cuenta los fallos de otros sujetos que también interviene en dicha actividad
(de modo que si no se procediera así, el riesgo dejaría de ser permitido), y cuán
do se puede confiar lícitamente en la responsabilidad de esos otros sujetos.
Por ello no es la confianza en sentido coloquial, psicológico o sentimental la que
se manifiesta en la teoría de la imputación, sino la confianza de carácter social,
esto es, aquella que posibilita los contactos sociales.- el ciudadano racional, fiel
al ordenamiento jurídico confiará en que los demás se comporten del mismo
modo, es decir, cumpliendo las expectativas sociales que les atañen y respetan
do a los demás como personas49.
íií. Prohibición de regreso: Con ella pretende jakobs enmarcar de forma sistemáti
ca la teoría de la participación dentro de la imputación objetiva. La prohibición
de regreso satisface la necesidad de lim itar el ámbito de la participación puni
ble, tanto para comportamiento imprudentes como dolosos, con base a crite
rios objetivo-normativos. De ese modo, la prohibición de regreso se presenta en
cierto modo como el reverso de la participación punible.
Este autor sostiene que no es jurídico-socialmente congruente que el carácter
delictivo de una actividad sea impuesto arbitrariay unilateralmente por el autor
del hecho, aun cuando el posterior resultado lesivo producido se halle conecta
do causalmente con la aportación prestada por un tercero50: «quien asume con
otro un vínculo que de modo estereotipado es inocuo, no quebranta su rol como
ciudadano, aunque el otro incardine dicho vínculo en una organización no per
mitida. Por consiguiente, existe una prohibición de regreso cuyo contenido es
que un comportamiento que de modo estereotipado es inocuo no constituye
participación en una organización no permitida»51.
iv. Actuación a riesgo propio de la víctima o competencia de la víctima: Median
te esta institución Jakobs propone tener en cuenta la intervención de la víctima
en el suceso. En este punto, la teoría de la imputación objetiva implica la intro
ducción de elementos valorativos que determinan cuáles son los límites de la
