La imputación a la víctima tiene lugar necesariamente de modo normativo cuan
do la aparente víctima ha infringido determinadas incumbencias de autoprotec-
ción, esto es, cuando en pleno ejercicio de su autonomía administra su ámbito de
organización de manera defectuosa o cuando menos inocua, asegurando la inco
lumidad desús bienes jurídicos. Por ello es que la institución dogmática de la im
putación a la victimase erige sobre el principio de autorresponsabilidad, en virtud
del cual cada ciudadano debe responder por sus propios actos.
En nuestra doctrina, García Cavero prefiere referirse precisamente a «incumbencias
de autoprotección»,ya que no se trata propiamente de deberes impuestos a la vícti
ma, sino de «criterios objetivos para determinar los ámbitos de competencia»
Clasificación de los tipos penales y sus efectos52:
De acuerdo a su estructura:
a) Tipo básico: modelo de la conducta prohibitiva.
b) Tipos derivados: circunstancias atenuantes o agravantes.
Por la relación entre la acción y el objeto de la acción:
a) Tipos de resultado: lesión material o inmaterial del bien jurídico.
b) Ti pos de mera actividad: simple comportamiento del agente.
Por el menoscabo del objeto de la acción:
a) Tipos de lesión: objeto de la acción sea dañada.
b) Tipos de peligro: solo es necesaria la puesta en peligro.
c) Peligro concreto: el objeto material del delito ha corrido un efectivo peligro de verse
vulnerado por lo que es necesaria que se pruebe la existencia del peligro, en otros
términos, el bien jurídico debe haber corrido un riesgo real de lesión.
d) Peligro abstracto: donde la acción en sí constituye ya un peligro para el bien jurídico,
aunque no se acredite que haya corrido un peligro efectivamente. Por ejemplo: Deli
to de Apología al terrorismo.
Por las formas básicas de comportamiento:
a) Tipos de comisión: Realizar una conducta positiva.
b) Tipos de omisión: conducta pasiva.
c) Omisión propia “ no hacer" que viola una norma que contiene un mandato, se deja
de hacer lo que la ley manda.
d) Omisión impropia abstiene de hacer lo que se espera que hiciera, por estar jurídica
mente obligado, posición de garante (comisión por omisión).
