■ Por el número de bienes jurídicos protegidos:
a) Tipos simples o monofensivos: sólo un bien jurídico.
b) Tipos compuestos o pluriofensivos: simultáneamente varios bienes jurídicos. Por
ejemplo: el robo (artículo 188o del Código Penal) que se dirige contra la propiedad e
integridad física.
Por el número de agentes:
a) Tipos unisubjetivos o individuales: sea cometido por sólo una persona,
b) Tipos plurisubjetivos o colectivos: concurso de dos o más personas.
Por las características del agente:
a) Tipos comunes o impersonales: cualquier persona. En la mayoría de los casos co
mienza la descripción penal aunque no necesariamente con el térm ino “quien” o "el
que".
b ) Tipos especiales: ciertas características en el agente. Especial propio: sujeto activo
una cualidad o característica especial. Especial impropio: una condición especial
única, actúa como atenuante. Por ejemplo: los delitos de funcionarios en el ejercicio
de su cargo; para cometer este tipo de delitos el agente tiene que ser funcionario
públicoy encontrarse en el ejercicio de su cargo.
Por la pluralidad de hipótesis típicas:
a) Tipos mixtos alternativos: en estos tipos penales, las acciones que configuran el de
lito son plenamente equivalentes y fungióles, es decir, no existe posibilidad de con
curso entre esas conductas. Por ejemplo: recibir dinero o aceptar una promesa.
b) Tipos mixtos o acumulativos: estos tipos penales tratan de la previsión de varios
delitos que pueden concurrir entre sí en concurso material o ideal. Por ejemplo: uso
de insignias y la acción de ejercer públicamente actos propios de una facultad para
la que se requiere título oficial.
Tipo Subjetivo.- Latipicidad incluye un aspecto objetivo y uno subjetivo. El subjetivo se refiere
al actuar del sujeto, pudiendo ser éste por dolo o por culpa; aquí veremos el tratamiento del dolo
y la culpa, sus elementosy sus clases.
a) Delito doloso.- Anal izando el dolo desde el punto de vista de la Teoría Finalista (Teoría
Volitiva), diremos que el existe dolo cuando el sujeto realiza el acto con conciencia y vo
luntad de realizar el tipo objetivo, es decir, el sujeto sabe lo que hacery lo quiere hacer.
La conciencia es el conocimiento de estar realizando el tipo objetivo, debe ser actual, es
decir debe estar presente en el momento que se realiza el hecho; el conocimiento no
tiene que ser exacto o científico, sino el propio de una persona promedio. No se exige que
el sujeto conozca que ese hecho está en contra del ordenamiento jurídico. La voluntad es
querer realizar los elementos objetivos del tipo.
El dolo incluye el conocer y querer la realización de la situación objetiva descrita por el
tipo del injusto, y no requiere que se advierta que dicha relación es antijurídica, no in
cluye la conciencia de la antijuricidad. Por ejemplo: en el homicidio, un sujeto sabe que
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 851 of 1506 --

Tema 6: Temas de la Especialidad Penal
disparando un arma de fuego sobre una parte vital del cuerpo humano de otro le causará
la muerte y, aun así dispara porque quiere matarlo.
Clases de dolo: El dolo puede variar de acuerdo a la intensidad en torno a la conciencia o
voluntad en el comportamiento del agente:
i. Dolo Directo: (de Primer Grado, intencional o inmediato) la realización del tipo ha
sido perseguida directamente por la voluntad del agente. Hoy resulta mejor enten
der una voluntad referida a la producción de la acción y no del resultado. Ejemplo: A
dispara a la cabeza de B (dolo directo de homicidio).
ií. Dolo Indirecto: (de Segundo Grado o de consecuencias necesarias o de resultado
accesorio necesario) cuando el sujeto activo sabe que para realizar un hecho necesa
riamente tendrá que producir una consecuencia adicional que se encuentra ligada al
resultado. El sujeto asume las consecuencias generadas por el hecho que comete. En
este caso prima el elemento intelectual- el conocimiento-, ya que el sujeto advierte
que su comportamiento trae consigo otro delito. Ejemplo: Miguel quiere matar a
Juan que está en un bus y lo hace caer de un puente poniendo una tranquera cuando
éste pasaba, Miguel tiene dolo directo de matar a Juan y dolo de segundo grado res
pecto a todos los demás pasajeros.
iii. Dolo Eventual: el agente se ha representado interiormente la eventual realización
del tipo como posible y actúa asumiendo esta probabilidad, a pesar de no querer
que se produzca el resultado. Ejemplo: Un delincuente ha decidió asaltar un bancoy
sabe que hay un vigilante de 8 o años, sabe también que, de amordazarlo éste puede
m orir por asfixia, pese a todo lo hace y al día siguiente en los periódicos aparece la
noticia de que el vigilante murió de la forma descrita.
Dolo eventual y culpa consciente: Existen problemas para diferencias los casos de dolo
eventual y culpa consciente, dado que tiene una estructura común53:
En ninguno se desea el resultado (ausencia de voluntad); y,
En ambos el autor conoce la posibilidad de que se produzca el resultado.
Existen diversas teorías con la intención de diferenciar claramente el dolo eventual de la
culpa consciente, tres son las más aceptadas54:
a. Teoría de consentimiento: La disti nción entre dolo eventual y cul pa consciente está
en que el autor consienta la posibilidad del resultado, en el sentido que lo apruebe.
Se debe, entonces preguntar el agente: ubicándose en un punto anterior al hecho
y sabiendo que su comportamiento provocaría el resultado típico ¿habría realizado
igual la acción? Si la respuesta es positiva, hay dolo eventual. Si la respuesta es nega
tiva, es decir, si el agente realiza su conducta abrigando la posibilidad de que no se
va a producir el resultado típico, hay culpa consciente.
