b. Teoría de la probabilidad o de la representación: Lo decisivo para esta teoría es el
grado de probabilidad del resultado advertido por el autor. Cuando la probabilidad
es alta surge el dolo eventual, si es bajo hay culpa consciente. Esta teoría puede ser
criticada porque se pueden presentar casos intermedios.
c. Teoría ecléctica: Surge de la combinación de los dos anteriores. Se exige que el su
jeto tome en serio la posibilidad del delito y, al mismo tiempo, que se conforme con
dicha posibilidad. Tomaren serio la posibilidad es no descartar que se pueda produ
cir (cierto conocimiento) y conformarse con dicha posibilidad significa resignarse a
'' ella. De cumplirse con estos dos puntos existiría dolo eventual.
d. Teoría Cognitiva del Dolo:
Formulación y aplicación. - El juicio para determinar el carácter doloso de una ac
ción debe asentarse sobre la constatación en la realidad, teniendo en cuenta los indi
cadores externos que ésta nos suministra, de que el sujeto conocía la situación en su
globalidady su correcto significado (es decir que su acción acarreaba la vulneración
de un bien jurídico protegido) y que, en base a ella, adoptó la decisión de actuar. Bas
ta que el sujeto conozca que con su actuación produce un riesgo para la afectación
de un bien jurídico55.
Se suele aplicar a los casos en que se vulneran bienes jurídicos supraindividuales (no
requieren de un resultado), generalmente para delitos de peligro abstracto.
Problema: aplicación a delitos en los que se vulneran bienes jurídicos individuales.
Elementos subjetivos distintos del dolo:
i. Tendencia interna trascendente: realizo el hecho porque lo requiero para realizarotro.
Pueden ser:
a. Delitos mutilados en dos actos: cuando el agente participa en la primera acción
para participar de la segunda. Ejemplo: H urto-se sustrae un bien para obtener
un provecho.
b. Delitos cortados: la consumación se da por la i ntervención de una persona dis
tinta del autor. Ejemplos: Estafa, Seducción.
íh Tendencia interna intensificada: son elementos que se encuentran dentro del pro
pio autor pero son distintos del dolo. Ejemplo: la excitación en los delitos contra la
libertad sexual.
iii. Delitos de expresión: aplicable a delitos que utilizan como medio la expresión de la
voluntad (injuriante por ejemplo) del sujeto activo. Ejemplo-, injuria, difamación.
El dolo en los delitos de omisión: Tienen como punto de partida el respeto del Principio de
Solidaridad56. La conducta que sirve de base a la norma penal y que ésta regula, puede consis
tir, tanto en un hacer, como en un no hacer. Por tanto, en la dogmática penal se distinguen los
tipos penales según se expresen en la forma de la infracción de una prohibición de hacer o en
55 CARO JOHN, José Antonio, Dogmática penal aplicada, Ara Editores, Lima, 2010, p. 63.
56 VILLAVICENCIO, Felipe, op. cit., pp. 382y ss.
52 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

