Tema 6: Temas de la Especialidad Penal
la forma de una desobediencia a un mandato de acción. En el primer caso se trata de delitos
de comisión y en el segundo de delito de omisión57.
La omisión se construye sobre la base de normas imperativas, que vinculan a la persona a rea
lizar una acción esperada,y que no lo hace, pudiendo hacerlo. La omisión no es pues un simple
no hacer nada, sino un no hacer porque no se quiere hacer. La conducta omisiva se encuentra
pues también gobernada por la voluntad, y por consiguiente, si falta la voluntad no hay com
portamiento omisivo58.
La norma imperativa impone al autor la obligación de realizar una acción esperada, y la con
ducta omisiva deberá estar dirigida a no hacer esa determinada acción al cual está obligado.
Por eso es que básicamente un delito de omisión constituye siempre una infracción de un de
ber. El deber puede ser un “deber genérico” que vincula a cualquier persona en razón de los
valores de la convivencia social (por ejemplo, el deber de ayudar a una persona en peligro), o
también puede ser un “deber específico” que vincula a determinadas personas, por ejemplo
en razón a su función o profesión.
De ahí que los requisitos generales del delito de omisión sean: el conocimiento del deber ju
rídico que le impone el deber de actuar; la capacidad de actuar del sujeto conforme el deber
impuesto; y la ausencia de dicho comportamiento.
El delito de omisión es de dos clases59:
a. Delitos de omisión propia:
Estos delitos se encuentran taxativamente señalados por la Ley penal, y sancionan sim
plemente la mera infracción del deber (deber general), por eso que estos delitos son
siempre dolosos y de mera actividad. No se lleva a cabo la acción exigida por la ley, sin
exigirse la producción de un resultado de lesión a un bien jurídico.
Por ejemplo: si encontramos a un herido en la calle, tenemos la obligación de socorrerlo,
la omisión propia se consumará con el solo hecho de no haberlo socorrido. (Art. 127 Códi
go Penal).
Aspecto Objetivo: sus requisitos son:
i. Situación típica: verificar una situación en la que la norma me exige un comporta
miento. Ejemplo: encontrar a un herido en la vía pública.
¡i. Comportamiento distinto a la norma. Ejemplo-, al veral herido, me voyy no lo auxilio
como manda la norma.
iii. Capacidad de realizar la conducta exigida por la norma: físicay cognitiva
Aspecto Subjetivo: Dolo. Conocimiento y voluntad de no actuar. No se admite la culpa
(no hay resultado).
57 Ibidem.
58 Ibidern.
