UBILEX
b. Delitos de omisión impropia:
También conocidos como comisión por omisión, por tener en esencia, la misma estruc
tura y configuración ontológica que la conducta comisiva. En la omisión impropia tam
bién se da una infracción al deber, pero éste adopta una característica especial, dado que
el deber jurídico es específico y cualificado: el deber de garante.
El autor en los delitos de omisión, tiene la posición de garante6061, esto es, un deber espe
cífico que le impone actuarde determinada manera para evitar la lesión del bien jurídico
a su cuidado. Si el autor decide no actuar conforme a su deber de garante.se producirá la
afectación del bien jurídico.
El delito de omisión impropia es un delito de resultado, que puede ser cometido de forma
dolosa o culposa. Los delitos de omisión impropia no están señalados expresamente por
la Ley penal, sino que se extraen de los tipos comisivos.
Por ejemplo, será delito de homicidio doloso por omisión impropia, cuando el rescatista
omita su deber frente a una persona en peligro, porque quiere que dicha personase muera.
Aspecto Objetivo: sus requisitos son:
i. Acción típica + Posición de garante: el sujeto tiene el deber de proteger un bien jurí
dico o de custodiar una fuente de peligro:
Función de protección de bienes jurídicos:
a) Estrecha relación vital. Ejemplo: padres e hijos.
b) Comunidad de peligro. Ejemplo: grupo de alpinistas.
c) Aceptación voluntaria de función protectora. Ejemplo: bomberos
Deber de vigilancia de una fuente de peligro:
a) Actuar precedente (Injerencia). Ejemplo: fogata.
b) Deber de control de fuentes de peligro. Ejemplo: dueño de perro pittbull.
c) Deber de cuidado de terceros. Ejemplo: padres e hijos.
ii. Falta de realización de la acción esperada + Producción de un resultado.
iii. Capacidad de actuar + Deber de evitar el resultado: dicho deber tiene dos requisi
tos:
• Condiciones externas: cercanía especial (situación típica se da en la esfera de
dom inio del sujeto), y cercanía temporal (la presencia del sujeto concurre en el
momento de la acción típica).
• Condiciones internas: varían según el sujeto
Aspecto Subjetivo: Dolo. Conocí miento y voluntad de evitar el resultado. Se admite la culpa.
Ausencia de dolo: “No hay pena sin tipo”6\ es deci r, sólo lo que queda dentro del ámbito del
tipo de injusto puede desencadenar consecuencias jurídicas penales.
60 Ibidem.
61 FEIJOO, Bernando, op. cit., p. 342.
