Tema 6: Temas de la Especialidad Penal
c) Delito culposo.- El tipo culposo individualiza una conducta (al igual que el doloso). La
conducta no se concibe sin voluntad, y la voluntad no se concibe sin finalidad, la conduc
ta que individualiza el tipo culposo tendrá una finalidad, al igual que la que individualiza
el tipo doloso. Pero el tipo culposo no individualiza la conducta por la finalidad sino por
que en la forma en que se obtiene esa finalidad se viola un deber de cuidado.
El agente no quiere cometer el hecho previsto en el tipo, pero se comete por infracción a
la norma de cuidado, es decir, por inobservancia del cuidado. De acuerdo al artículo iz°
del Código Penal, los delitos culposos deben ser declarados en forma expresa (numeras
clausus). La premisa básica para la existencia de un delito culposo es la lesión efectiva al
bien jurídico, el cual no se quería lesionar.
c.i) Naturaleza de la culpa: Diversas teorías fundamentan la naturaleza de los delitos
culposos, entre ellas tenemos:
a. La no previsión de lo previsible: La culpa se presenta como un vicio sobre la inteli-
genciay la voluntad, porque estando en la posibilidad de poder evitar la producción
del resultado típico, el sujeto no actuó.
b. La culpa proviene de un defecto de la inteligencia: Se plantea una deficiencia en la
asociación de ideas, lo cual llevado al extremo nos conduciría a que ciertos casos no
se sancionen.
c. La culpa es un vicio o defecto de la atención: Es decir, el agente no ha prestado la
atención a la que estaba obligado.
d. La concepción normativa de la culpa: Afirm a que su reproche se basa en la valo
ración del deber de diligencia, atención y cuidado indispensables para evitar que
de nuestra actividad consciente, incluso perfectamente lícita, deriven consecuencias
previsibles, dañosas para los demás.
c.z) Fundamento y casos de incriminación del comportamiento culposo: La esencia del
delito culposo está en incumplir la norma de cuidado, la cual es objetiva y general y, por
tanto, normativa. Si una persona cumple las normas de cuidado y manifiesta su diligencia
para cum plir las exigencias del ordenamiento, no se le puede exigir ningún tipo de res
ponsabilidad penal por el resultado que se haya producido.
Específicamente, entre los fundamentos que justifican el requerimiento de la existencia
de un resultado para sancionar un delito por culpa tenemos:
a. Garantía de seguridad: Dado que sirve de prueba en un proceso para demostrar la afec
tación que has ufrido Ia vícti ma. Además, Ia existencia deI resultado Ii mita Ia responsabi-
lidad del sujeto pues, sólo responde en base al daño o lesión que ha ocasionado.
b. Sobre el peligro: Resulta complicado demostrar la existencia de peligro sobre el
bien jurídico si éste no ha sido afectado. Así, el resultado se vuelve un indicio del
peligro del comportamiento realizado por el sujeto.
Teniendo en cuenta estos fundamentos y, sobre la base de los principios de seguridad
jurídica e indubio pro libértate, resulta necesario exigir la presencia de un resultado que
afecte al bien jurídico para sancionar una conducta culposa.
