el cuidado requerido en la vida de relación social respecto del hecho acaecido; y,
el cu id a d o n o rm ativo , surge de la confrontación entre la conducta que hubiera
seguido un hombre razonable y cuidadoso en la situación del autory la realiza
da por el autor realmente. Los elementos del juicio normativo son intelectual y
valorativo.
El deber objetivo de cuidado puede ser.-
a.i. D e b e r de cu id a d o in te rn o: advertí r el peligro para el bien jurídico protegi
