d) D elito p re te rin te n c io n a l.- El normal desarrollo del delito supone una concordancia en
tre el fin del comportamiento del delincuente y el resultado efectivamente producido.
Pero, esto no ocurre en el delito preterintencional, pues el dolo de la acción produce un
resultado más grave que el previsto, es decir, hay dolo en la acción y culpa en el resultado.
En los delitos preterintencionales se presenta una conducta dolosa contraria a deberes
de cuidado, pero culposa frente al resultado acaecido, es decir, el comportamiento dolo
so concurre con un resultado ulterior que hubiese podido preverse y evitarse (resultado
culposamente provocado). Ahora bien, si el ilícito penal se configura por una infracción
consciente de deberes de cuidado que ocasiona culposamente un resultado prohibido,
no queda más que aceptar que estamos ante un delito culposo62. Solución correcta: con
curso de delitos, se aplica la pena del delito más grave.
En esta línea argumentativa, el Prof. Villavicencio Terreros señala que el delito preterin
tencional refiere a la «tipificación simultánea, dolosa y culposa, de una misma conducta, sea
quede no hallarse así tipificada, el caso se resuelve por concurso ideal, o bien que, fuera de esta tip i
ficación compleja, la conducta culposa sea atípica»63.
