? ■ e) Delito cualificado por el resultado.- Tradicionalmente, el delito cualificado por el resul-
fr—^ tado ha sido considerado como aquel ilícito penal que experimenta un aumento de la
pena cuando se verifica un resultado dañoso posterior más grave del que se proponía
causar el agente; este resultado dañoso posterior se imputaba a la persona por el solo
hecho que se ha originado de su conducta delictiva y, en consecuencia, independiente del
dolo o de la culpa64.
Esta noción tradicional resulta incompatible con la actual concepción del Derecho Penal
Garantista basado en el Principio de Responsabilidad Penal Personal o Principio de Cul
pabilidad55 previsto en el artículo Vil del Título Preliminar del Código Penal al señalarque:
«la pena requiere de la responsabilidad del autor Queda proscrita toda forma de responsabilidad
objetiva». El valor de este principio no solo radica en fijar una responsabilidad penal per
sonal que descarta claramente la posibilidad de responder por hechos ajenos o de otros,
sino que prohíbe toda forma de responsabilidad objetiva, es decir, aquella que vaya más
al la y no respete los límites del d o lo yd e la culpa.
De este modo, la moderna doctrina penal define el delito cualificado por el resultado
como aquel delito donde el autor dolosamente ejecuta el hecho, pero por imprudencia
produce un resultado mayor; diferenciándose del delito preterintencional en que aquí la
acción dolosa base constituye por sí misma un hecho delictivo66. Es por ello que la doc
trina penal señala que en los delitos cualificados por el resultado se deberá im putar de
manera objetiva y subjetiva, pues se requiere una conexión de inmediatez entre el delito
básico y el resultado más grave, y la existencia de culpa respecto del resultado mayor67.
En tal sentido, se imputará al autor la comisión del delito siempre que el resultado le sea
imputable producto del riesgo derivado de la infracción de la norma de cuidado.
C aso Fortuito: cuando el resultado se produce sin dolo o culpa por parte del agente. Es
capa al control situacional del sujeto. Ejemplo: doy somnífero a hombre que sufre del
corazón y muere.
Error de tip o .- Es el desconocimiento o ignorancia por parte del sujeto activo de uno o más de los
elementos que conforman el tipo objetivo (falsa representación de la realidad)68. El sujeto piensa
que está realizando un hecho lícito, atípico, pero objetivamente ha realizado un tipo penal.
C lases:
a. Irrelevan te: Cuando no hay cambio cualitativo, ni cuantitativo en la afectación del bien
jurídico. El sujeto/objeto afectado goza de la misma protección jurídica de aquel que se
quiso afectar.
