Ejemplo: A quiere lesionara B, pero en la oscuridad se confunde y le empieza a pegar a C,
hermana de ésta.
b . R elevante: Hay un cambio cualitativo (bien jurídico con protección especial -sujeto/obje
to afectado tiene una protección jurídica distinta.) y/o cuantitativo (más bienes jurídicos)
en la afectación del bien jurídico.
i. Sobre los e le m e n to s ese n ciale s: Su concurrencia determina la configuración o no
de un determinado tipo penal.
Ejem plo: A tiene relaciones sexuales con B, creyendo que B tiene 20 años cuando en
realidad tiene 13.
En este caso, el error es sobre un elemento esencial (la edad), puesto que la concu
rrencia-o n o -d e dicho elemento, determina la existencia o inexistencia del delito
de violación.
a) V e n cib le : Con mayor diligencia se podría haber evitado. Excluye el dolo, mas no
la imprudencia (en los casos que está tipificada).
b) In ven cib le: Ni aún con mayor diligencia (se puede seguir el doble baremo) se
habría evitado el error. Excluye el doloy la imprudencia: conducta es a típ ica.
ii. So bre los e le m e n to s a ccid e n ta le s: Se ha realizado una acción típica, pero se busca
determinar la acción típica de qué delito se ha realizado. Analiza las circunstancias
en las que se ha realizado una acción que, de por sí, es típica.
a) Error sobre el objeto sobre el cu al recae la acción o error “ in pe rson a": Existe
una representación errónea respecto de cuál es el sujeto/objeto al que se busca
afectar, siendo que el sujeto/objeto afectado tiene una protección jurídica dis
tinta. "Te confundes”.
Ejem plo: A quiere matar a su esposa C, pero, en la oscuridad se confunde y mata
a B, amiga de ésta.
b) A b e rra tio Id u s : Error en el golpe o en la ejecución. No "te confundes", sino que
cometes un error al momento de ejecutar la acción.
Ejem plo: A quiere m atara B, pero tropieza al momento de disparar, y el C recibe
el impacto.
c) Error en el cu rso ca u sa l: Se produce el resultado querido, pero se rompe el nexo
causal del mismo con la acción que estaba orientada a producirlo, siendo conse
cuencia (el resultado) de una causa distinta.
Ejem plo: A dispara a B, pero cuando B es llevado en taxi al hospital, éste choca y
B muere como consecuencia del choquey no del disparo.
d) D olusC eneralis: El agente realiza una serie de acciones que crean un riesgo para
un determinado bien jurídico, actuando con pleno conocimientoy voluntad res
pecto de éstas (concurren el elemento objetivo y subjetivo); siendo que yerra en
la creencia de cuál ocasionó el resultado deseado.
Ejem plo: A planea matar a B ahorcándolo y luego enterrar su cuerpo. Luego de
ser ahorcado, B sólo queda inconsciente, muriendo por asfixia al ser enterrado.
