plo: construcción de la vía expresa.
La autoridad justificadora funciona en el ámbito de la autoridad familiar, en razón de la
facultad de corrección de ambos padres o de los tutores y curadores. Al marido no le co
rresponde, en cambio, una potestad correctiva de igual índole respecto de la esposa, sino
que, limitadamente al casode lavioladón porla m ujerde su obligación de cohabitar con
su esposo, debe hacer valer su autoridad marital, policial o judicialmente. Los padres pue
den delegar el ejercicio de su autoridad en otras personas o establecimientos.
b. C u m p lim ie n to de un deber: cuando el agente practica actos legítimos, facultados por
orden o norma vinculante, en razón de su oficio o cargo, o en razón de un deber legal.
El ejercicio del cargo debe ser legítimo. La legitimidad supone la legalidad del título en
cuya virtud el autor desempeña el cargo y la legalidad de su ejercicio en el caso concreto.
Lo primero requiere que la autoridad no haya sido usurpada. El ejercicio es legal si el autor
obra en materia de sucompetenciay no lo hace con abuso de autoridad, ni con exceso en
la acción, sea en el modo o en la medida de su ejercicio.
Ejem plo: Policía que detiene a un delincuente.
El juez que ordenó un desalojo con uso de ia fuerza publica, aunque su acto se adecúa for
malmente a la instigación de un despojo, no es punible, porque ha obrado legítimamente.
También obra justificadamente, aunque cause lesiones, el guardia cárcel que hiere a un
preso para impedir su fuga.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 861

-- 862 of 1506 --

UBILEX
C) LA A N U I U RUO DAD.- La antij uridicidad es aquel juicio de desvalor que posee un hecho
típico contrario a las normas del Derecho en general (no sólo al ordenamiento penal). Es lo
contrario a Derecho, por lo tanto, no basta que la conducta encuadre en el tipo penal, se nece
sita que esta conducta sea antijurídica, considerando como tal, a toda aquella definida por el
ordenamiento, no protegida por causas de justificación.
Se le puede considerar como un “elemento positivo" del delito, es decir, cuando una conducta
es antijurídica, es considerada como delito. Para que la conducta de un ser humano sea delic
tiva, debe contravenir el Derecho, es decir, ha de ser antijurídica.
a) D e sva lo r d e acció n y d e sva lo r d e re su lta d o : La antijuricidad del hecho no se agota en la
desaprobación del resultado delictivo, sino que también debe ser incluida en el juicio de
desvalor la form ay el modo en que se origina la situación jurídicamente desaprobada.
b) C la se s de a n t iju r ic id a d .- Por tradición se ha venido distinguiendo entre la antijuridici
dad formal, que es aquella que viola lo señalado por la Ley, y el material, cuando se trata
de una conducta antisocial.
En realidad, una antijuridicidad material sin la antijuridicidad formal no tiene ninguna
relevancia para el Derecho. Por otro lado, la antijuridicidad material sirve de fundamento
para la formal, de tal modo que aquella conducta prohibida por la Ley debe serlo porque
protege un bien jurídico (antijuridicidad material)69.
i. A n tiju ric id a d fo rm a l: Se afirma de un acto que es "formalmente antijurídico”, cuan
do a su condición de típica se une la de ser contrario al ordenamiento, es decir, no
ésta especialmente justificado por la concurrencia de alguna causa de tal naturaleza
(por ejemplo: defensa propia).
Por lo tanto, la antijuricidad formal no es más que ¡a oposición entre un hecho y el
ordenamiento jurídico positivo, juicio que se constata en el modo expuesto.
ii. A n tiju ric id a d m a te ria l: Tradicionalmente se basa en el carácter de lesión o puesta
en peligro de un bien jurídico, a lo que se añade la ausencia de un interés prevalente
que justifique el hecho (perspectiva ex post). Actualmente, se destaca la necesidad
de atender también a la peligrosidad de la conducta desde una perspectiva ex ante
e incluirse en el injusto también el aspecto subjetivo, representado por la finalidad
que guía la acción.
c) C a u sa s d e ju s tific a c ió n .'' Las causales de justificación son situaciones reconocidas porel
Derecho en las que la ejecución de un hecho típico se encuentra permitido, es decir, su
ponen normas permisivas que autorizan, bajo ciertos requisitos, la realización de actos
generalmente prohibidos.
Vienen a ser normas dirigidas a situaciones específicas que excluyen la antijuridicidad de
un determinado comportamiento típico, que a priori podría considerarse antijurídico.
Los efectos de las causas de justificación se extienden en razón del Principió de Unidad de
lo antijurídico y exceden el ámbito penal. El efecto penal de las causas de justificación es
la impunidad del hecho.
69 B A C IG A L U P O , E n riq ue, op. cit., pp. 241 y ss.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 863 of 1506 --

Tema 6: Temas de la Especialidad Penal
i. L e g ítim a d e fe n sa .-
La legítima defensa es una causa de justificación regulada en el artículo 20, inciso
3 del Código Penal, que se entiende como la defensa contra una agresión ilegítima,
actual y no provocada contra la persona o sus derechos propios o de terceros. La le
gítima defensa puede ser propia, cuando se trata de la defensa de la propia persona
o sus derechos, o impropia, cuando se defiende a terceros. El principio de la legítima
defensa se basa en la idea de que el derecho no puede permitir lo injusto, y se susten
ta en los principios de protección individual y mantenimiento del orden jurídico
Se basa en tres requisitos fundamentales establecidos en el numeral 3 del artículo 20
del Código Penal70. Para que se configure la legítima defensa, deben concurrir:
1. A g resió n a ctu a l, ile g ít im a y real: La agresión debe ser real y no fingida. La agre
sión puede ser física, psicológica o moral, y debe ser ilegítima, es decir, no debe
ser una respuesta justificada por la víctima.
2. N e ce sid a d ra cio n a l del m e d io e m p le a d o : El medio utilizado para la defensa
debe ser racional y necesario para impedir o repeler la agresión. No se conside
ra el criterio de proporcionalidad de medios, sino que se evalúa la intensidad y
peligrosidad de la agresión, la forma de proceder del agresor y los medios de
defensa disponibles.
3. Falta d e provocación suficiente d e q u ie n hace la d efen sa: La víctima no debe
haber provocado suficientemente la agresión. La legítima defensa no se justifica
si la víctima ha causado la agresión de manera intencional o imprudente.
Además, la legítima defensa también se aplica en situaciones de peligro inminente
y necesidad de proteger la vida o integridad propia o de terceros. En estos casos, se
puede repetir razonablemente una agresión, irrupción, ingreso violento o subrepti
cio ilegítimo dentro de un inmueble, vehículo, negocio, empresa, asociación civil o
lugar de trabajo, siempre que se ejerza la legítima propiedad o posesión con título
propio o de parientes hasta el tercer grado de consanguinidad o afinidad. La legítima
defensa es una causa de justificación que cancela la antijuridicidad de la conducta,
es decir, convierte una conducta típica en una conducta lícita.
Por ejemplo, en un supuesto en el que una persona es agredida por un puñal y solo
tiene disponible su arma de fuego, una defensa racional sería utilizarla para defen
derse. Sin embargo, una defensa abusiva, grotesca o innecesariamente despropor
cionada, como vaciar el cargadory disparar seis veces en el cuerpo, no se consideraría
legítima defensa.
Requisitos
La jurisprudencia nacional71 refiere sobre este tema:
