Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 864 of 1506 --

"OCTAVO, En atención a lo precedentemente acotado, que para que poder aplicar la causal exi
mente de responsabilidad penal por legítima defensa en favor de la procesada, tenemos que
analizar los hechos ocurridos, las circunstancias precedentes y concomitantes del evento cri
minal, la conducta desarrollada por el agente y la víctima, y el desenlace final. En ese orden,
tenemos:
:->H8;lyPrlmer-presupuesto: agresión ilegítima. Se trata de un comportamiento dirigido a lesionar
o poner en peligro un bien legalmente protegido, donde el adjetivo ilegítimo es utilizado en el texto legal para
calificar a la agresión de ilícito e injusto, contrario al orden jurídico. De tal forma que la agresión debe ser in
minente, actual opresente,::
8:2, Segundo presupuesto: necesidad racional del medio empleado para impedirla o repelerla. Se trata de
ur¡a apreciación de valor con referencia a la justicia y la equidad. La racionalidad de la defensa se determina
apreciando la proporcionalidad entre el peligro propio a la agresión y la acción de defenderse: es decir, entre las
condiciones, instrumentos, y riesgos de la agresión y los propios del comportamiento defensivo.
¡8.3:íTeroer presupuesto: falta de provocación suficiente de quien hace la defensa. Se trata de una actitud es
pecial de quien se defiende, esto es, de poner cuidado en comportarse de manera tal que no origine, de parte
de cualquier persona,una reacción contra él. La apreciación del carácter suficiente de la provocación debe
hacerse mediante un juicio objetivo de valor, no puede depender, por ejemplo, de la extremada susceptibilidad
o irritabilidad del sujeto en cuestión".
Clases
a. Personal: se defienden bienes jurídicos personales.
b. De terceros: se protegen bienes jurídicos de terceros.
c. Perfecta: se cumple con el presupuesto y con los requisitos de legítima defensa.
d. Im perfecta: se cumple con presupuesto pero falta uno o más requisitos.
e. Mecánica: se encuentra previamente establecido. Ejemplo: colocación de un
cerco eléctrico, perro guardián, disparos automáticos (es necesario que se cuen
te con el aviso correspondiente de que existen estos mecanismos de defensa en
una propiedad).
f. Presunta: se presume la necesidad de la defensa. Ejemplo: cuando el ladrón
está escalando.
ii. Estado de necesidad ju stifica n te .'' Es la situación en que se encuentra el que causa
re un mal a un bien ajeno, por evitar otro mayor inminente a un bien propio o ajeno,
al que ha sido extraño. Su fundamento justificador reside en la preponderancia del
bien jurídicamente más valioso que representa el mal menor.
Presupuesto:
Situación de peligro grave, actual e inm inente (provocado por la naturaleza o por
tercero de manera indirecta).
Requisitos:
• La lesión al bien jurídico no debe ser mayor a la que se pretende evitar.
• No hay obligación de sacrificarse.
• La situación no debe habersido provocado por el sujeto.
• Todos los bienes jurídicos son defendibles.
• Acción salvadora: Debe ser la única posibilidad para evitar el peligro para sí o
para tercero.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 865 of 1506 --

Tema 6. Temas de la Especialidad Penal
• La acción realizada debe ser idónea para conjurar el peligro.
ííL Consentimiento. - El titu lar de un bien jurídico de libre disposición consiente en su
lesión antes o durante la lesión, pero no después de ésta.
Clases:
a) Presunto: el titu la r del bien jurídico no está presente, pero se presuma que de
estarlo consentiría.
b) Expreso: el titu la r del bien jurídico de a conocer de modo directo su voluntad.
Requisitos:
a) Debe referirse a un bien jurídico de libre disposición.
b) No es necesaria la capacidad civil para brindarlo, sólo una capacidad natural de
discernimiento.
iv. Ejercicio legítimo de un derecho.- La ley reconoce derechos que permiten lesionar
bienes jurídicos. Es el derecho subjetivo reconocido por la ley a una persona para co
meter un hecho penalmente típico. Estos derechos subjetivos no deben confundirse
con las autorizaciones legales porque éstas, a diferencia de aquellos derechos, no
implican facultades de exigir algo a terceros.
Estos derechos son de dos tipos:
a. No procedentes de cargo u oficio:
• Vías de hecho. Ejemplo: artículo 920o del Código Civil.
• Derecho de corrección. Ejemplo: inciso 30del artículo 430odel Código Civil.
• Deportes: según los reglamentos (adecuación social)
b. Procedentes de cargo u oficio: profesiones que suponen realización de actos
típicos. Ejemplo: periodista que publica delitos cometidos.
Sólo el ejercicio legítimo o regular del derecho propio es justificante. La ley no am
para el ejercicio abusivo del derecho. Se considera tal el ejercicio que contraría los
fines que la ley tuvo en mira al reconocer el derecho de que se trata o que excede los
límites supuestos por la buena fe, la moral o las buenas costumbres.
D) LA CULPABILIDAD.- Elemento de la teoría del delito que más ha evolucionado con el paso
de los años. A saber:
i. Tradicional: Cometer hecho antijurídico pudiendo actuar de un modo distinto (concepto
de libre albedrío).
ii. Psicológica: Los hechos psíquicos de la fase interna (dolo e imprudencia) constituyen cul
pabilidad.
iii. Normativa: Reprochabilidad de un comportamiento, relacionada con la constitución psí
quica normal, la relación psíquica con el hecho y la configuración normal de las circuns
tancias en que actúa el autor.
iv. Determinismo: Como deber de responder por el carácter propio.
v. Funcionalismosistémico: Como atribución según las necesidades preventivo generales
positivas.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 866 of 1506 --

UBILEX
vi. Teoría de Roxin: Como una actuación injusta a pesar de la existir una asequibilidad nor
mativa. Sabiendo y pudiendo realizar otro comportamiento, el sujeto no lo hace,
vií. Teoría de Schünemann: La libertad es social (parte de la individual), la sociedad en su
propio desarrollo permite o no esa libertad.
Se presenta cuando el sujeto activo que estuvo en la calidad y cualidad de haberse motivado
por la norma puede ser considerado culpable, pasando por los tres requisitos.- imputabilidad,
conocimiento de la antijuricidady no exigibilidad de una conducta distinta:
i. Imputabilidad.- Es la capacidad psíquica que tiene el sujeto activo para comprender lo
injusto del hecho (como expresión de la libertad de voluntady entendí miento) y de dirigir
la actuación conforme a dicho entendimiento. Depende de la motivación de la norma.
Ejemplo: un psicópata extremo no tiene capacidad para motivarse por la norma, es decir
de darse cuenta de los alcances de la norma con respecto a su conducta y a la posible
sanción.
La motivación de la norma no es sinónimo de conocimiento de la norma. El sujeto debe
tener capacidad idónea de motivarse por la norma.
Causales de inimputabilidad:
a. Físicas.-
a.i. Alteraciones psíquicas permanentes:
• Psicosis: enfermedades mentales que afectan la capacidad para mantener
se en contacto con la realidad.
• Oligofrenia: insuficiencia cualitativa de la inteligencia por deficiencia en el
desarrollo cerebral.
• Neurosis: reacciones psíquicas anormales que pueden producir inim puta
bilidad en situaciones determinadas.
• La Psicopatía no es causa de inim putabilidad porque no afecta la capaci
dad intelectual.
a.2 Trastorno mental transitorio: se refiere a una anomalía psíquica de carácter fu
gaz, gravey breve, que no ha sido buscada con el propósito de delinquir.
a. 3 Alteración en la percepción: se refiere a una alteración en la percepción sufrida
desde la infancia, que produzca distorsión en la conciencia de la realidad. Ejem
plo: sordomudo de nacimiento.
b. Normativas.- Minoría de edad penal
b. i Los menores de 14 años son incapaces de culpabilidad de manera absoluta.
b.2 Los adolescentes d e i4 a i8 años que infrinjan la ley penal son considerados ado
lescentes infracto res y son pasibles de medidas socioeducativas.
ii. Conocimiento de la antijuricidad.- Implica el conocimiento de la ilicitud de su hacer por
parte del sujeto activo, para algunos es el principal elemento de la culpabilidad. Se trata
de ver el elemento cognitivo del conocimiento de lo que se está realizando como un acto
contrario a la normay bajo ese supuesto únicamente se puede considerar la culpabilidad.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 867 of 1506 --

Tema 6: Temas de la Especialidad Penal
Excepciones: Error de prohibición y error de comprensión culturalmente aceptado.
iii. No exigibilidad una conducta distinta.- Evalúa la situación motivacional en la que se
encontraba el sujeto, en la cual un hombre promedio no hubiera podido actuar conforme
a la norma.
Causales de exculpación:
a. Estado de necesidad exculpante:
Presupuesto: Situación de peligro actual e inminente
Requisitos:
• Bienes jurídicos defendibles: sólo pueden protegerse la vida, la libertad o la in
tegridad.
• Debe ser un estado de necesidad invencible.
• No procede cuando el agente tenía la obligación de soportar el peligro; espe
cialmente cuando el agente haya causado el peligro o se encuentre obligado por
una particular relación jurídica.
b. Obediencia jerárquica:
Presupuesto: sujeto se encuentra en una situación de jerarquía
Requisitos:
• Relación de subordinación.
• Orden de apariencia legal.
• Orden emitida por autoridad competente.
c. Coacción:
• La voluntad del agente se encuentra viciada por la amenaza de un mal prove
niente de tercero.
• Esta amenaza recae sobre el agente o sobre alguien vinculado a éste.
d. Miedo insuperable:
• Ocurre cuando el agente actúa por miedo a sufrir un mal de igual o mayor inten
sidad.
• En esta situación el miedo no produce enajenación (trastorno mental) en el
agente.
• Debe ser un factor externo el que produzca el miedo, no uno interno.
• Debe ser de tal intensidad que el hombre medio no hubiera podido resistirlo.
La Punibilidad.- La punibilidad no considerada un elemento constituyente del delito, pues
puede o no exigirse, empero si se exige, entonces resulta un elemento necesario sin el cual el
delito no podrá ser punible.
Las condiciones objetivas de punibilidad. Son unacondición adicional que se presenta como
una exigencia que no está cubierta por el d oloy que en su ausencia la acción será impune.
La exclusión de la punibilidad se presenta cuando concurre una excusa absolutoria (Ejemplo:
el parentesco en los delitos contra el patrimonio).
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 868 of 1506 --

5. ITER CRIMINIS
Proceso de desarrollo del delito. Desde la resolución de cometer el hecho punible hasta su
terminación.
a) Fases:
Fase Interna: Idealización, deliberación y decisión de cometer el delito. ES IRRELEVANTE.
Fase Externa: Manifestación de voluntad del agente, empieza con la exteriorización de
los actosy termina con la consumación del delito (todos son actos verificables).
b) Actos preparatorios: el autor se provee de medios necesarios para la posterior realiza-
ción del delito. Son impunes, salvo que la ley prevea una sanción determinada (ejemplo:
tenencia ilegal de armas, asociación ilícita para delinquiry terrorismo).
c) Teorías de la distinción entre actos preparatorios y actos ejecutorios:
1. Univocidad: ajuicio de un tercero.
2. Subjetiva: los actos ejecutivos comienzan con la intención del sujeto.
3. Objetiva: los actos ejecutivos comienzan con la objetividad de los actos equívocos,
donde se conoce la intención. Puede ser:
a. Formal: es acto ejecutivo el que cumple con el comportamiento exigido por el
tipo penal.
b. Material: es acto ejecutivo cuando produce una afectación al bien jurídico protegido.
4. Objetiva-individual: se conjuga el plan del autor con lo señalado por la norma.
5. Negativa: no hay distinción entre los actos preparatorios y los actos ejecutivos.
d) Formas imperfectas de ejecución:
Tentativa: El sujeto da inicio a la ejecución del delito, pero no llega a producirse la consu
mación por causas voluntarias o involuntarias. Es un TIPO INCONGRUENTE: lo que pien
so y conozco en lo subjetivo que me va a llevar en actos a la consumación del delito, en lo
objetivo se me queda a mitad del camino.
e) Formas de la tentativa:
1. Acabada: se realizan todos los actos ejecutorios.
2. Inacabada: no se llevan a cabo todos los actos ejecutorios.
3. Absolutamente Inidónea: desaparece la pena porque no es posible la consuma
ción. Ejemplo: disparo a un cadáver.
4 . Relativamente Inidónea: se atenúa la pena. Ejemplo: la sustancia que agrego al
café de la víctima es veneno, pero no suficiente para causar la muerte.
5 . Irreal: no se puede probar ni siquiera la relación causal (naturalística).
6 . Delito putativo: el sujeto cree haber cometido un delito, pero en realidad no lo ha
cometido: ERROR DETIPO INVERSO.
f) ¿Por qué se sanciona la tentativa?
i. Teoría objetiva: porque pongo en riesgo el bien jurídico protegido. Trae como con
secuencias:
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 869 of 1506 --

Tema 6: Temas de la Especialidad Penal
• No se sanciona la tentativa inidónea.
• No se sanciona la tentativa irreal.
• No se sanciona el acto preparatorio.
2. Teoría subjetiva: voluntad contraria al derecho, lo que interesa es la intención del
sujeto. Trae como consecuencias:
• Equipara actos ejecutorios y consumación, otorgándoles la misma pena.
• Sanciona la tentativa inidónea.
• Sanciona los actos preparatorios.
3. Teoría Mixta: la variable es la conmoción social. Trae como consecuencias:
• No sanciona la tentativa inidónea.
• No sanciona la tentativa irreal.
Desistimiento: Evitación voluntaria por parte del sujeto activo de la consumación del delito,
bien desistiendo de la ejecución ya iniciada o impidiendo la producción del resultado. Debe
partir del propio sujeto, no de factores externos. Mediante esta figura el agente puede evitar
ser penado por el delito evitado, pero podría serlo si los actos realizados constituyen por sí
mismos otros delitos.
Requisitos:
1. En la Tentativa Inacabada: (desistimiento voluntario)
a) Abstención voluntaria (espontánea, motivada por la esfera personal) de continuar la
acción.
b) La abstención debe ser eficaz: evita que se produzca la consumación.
c) La abstención debe ser permanente, definitiva.
2. En la Tentativa Acabada: (arrepentimiento)
a) El agente debe abstenerse voluntariamente de continuar la acción.
b) La abstención debe ser eficaz.
c) La abstención debe ser permanente (definitiva).
d) La abstención debe impedir el resultado.
Consumación: Cuando el agente realiza todos los actos conducentes a la ejecución del
delito y éste se produce.
6. AUTORÍA Y PARTICIPACIÓN
6 .1 . A utoría
La noción de autor se encuentra descrita en el artículo 23o del Código Penal, así como las defini
ciones de autor mediato o indirectoy de coautor. La norma penal da un concepto de autor ade
lantando la idea general que modelará la autoría, pues la expresión “el que realiza” es obvio que
lo que se ha requerido es individualizar al sujeto sobre quien recaerá el título de la imputación.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 870 of 1506 --

UBILEX
I Esta condición significa, además, que el autor debe obrar con el dom inio de la realización del
hecho, que supone una acción típica y antijurídica como mínima: la sola realización de los
elementos objetivos y subjetivos de la descripción típica fundamentan únicamente el título
de "sujeto activo”.
Significa, que los criterios que nos permitirán saber quién es autor deberán deducirse de cada
tipo legal en la parte especial, del Código Penal, complementado por las prescripciones con
tenidas en la Parte General. Autor será, en ese sentido, el sujeto (“el que”) a quien se le impu
ta el hecho como suyo, esto es.- el que mató, robó, estafó, etc., con un dom inio final sobre el
acontecer. Al decir de JESCHECK, autor es “el que” anónimo con que empiezan la mayoría de
descripciones típicas; el legislador parte del presupuesto de que el autor es quien realiza la
totalidad de los elementos del tipo en su propia persona.
Autor y sujeto activo: Es importante destacar la diferencia entre el concepto de autor con la
expresión sujeto activo. No son conceptos del mismo nivel, ni iguales. La noción de autor con
tiene la responsabilidad criminal por el hecho cometido, en tanto que el sujeto activo es exclu
sivamente la persona que realiza la conducta típica, persona que, puede o no ser catalogada
como autor en el sentido indicado. Es más, el concepto de sujeto activo es la base objetiva
sustentadora de la noción de autor, porque alude a la persona que realiza el tipo,ya que efec
tivamente la tipicidad excepcionalmente no comporta antijuricidad; visto así, el sujeto activo
normalmente es el autor del hecho.
Autor y participe: El problemaen torno al cual giran y es punto de inicio uorigen de las teorías
sobre la autoría y participación es encontrar la manera de lograr, lo más exactamente posible
que se pueda, la distinción entre el autory los colaboradores que hayan participado en la rea
lización de un hecho delictuoso, valorar cada conductay de acuerdo a esa distinción y partici
pación penar dichas conductas. La complejidad de esta separación, complejidad que resulta
de la gran variedad deformas del comportamiento hum anoy sus manifestaciones, fue lo que
dio base para que surgieran diversos sistemas:
a) Concepto unitario de autor (participación en sentido amplio)
Partiendo de la teoría de la equivalencia de condiciones, considera como autoría toda
aportación causal para la realización del ilícito, no hay diferencia entre autory partícipe. El
concepto unitario de autor considera a todos los intervinientes que prestan una contribu
ción causal a la realización del tipo como autores, con independencia de la importancia
que corresponda a su colaboración para el conjunto del hecho.
Ejm.: A mata a 8, con los instrumentos que C le proporciona. Según esta teoría, tanto A como C
deben ser penados como autores del delito de homicidio,ya que contribuyeron al hecho delictivo.
• Ventaja: Facilita la aplicación del Derecho porque otorga la misma pena a cualquier
interviniente.
• Objeciones:
No hay una definición clara de los elementos que el tipo objetivo debe de conte
ner. En el ejemplo anterior, no se sabe quién es el homicida ni cuál es la conducta
prohibida para el tipo.
No hay criterios precisos para la determinación de la intensidad de la pena, por
lo que excluye un marco punitivo más leve para los partícipes.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 871 of 1506 --

Tema 6: Temas de la Especialidad Penal
b) Subjetiva (concepto extensivo de autor)
Establece la diferencia entre el autor y el partícipe desde el ámbito subjetivo, conside
rando al autor aquel con animus de autor, y partícipe aquel con animus de partícipe. Sin
embargo, no señala las diferencias entre autory partícipe en un plano objetivo -al igual
que la teoría anterior- parte de la teoría de equivalencia de condiciones.
Ejm.: A manda a su amiga B a que mate al bebé de la primera, ocasionando dicho resultado. Esta
teoría determina que A es autora, pues tiene animus de a u to r;y B es partícipe, por tener animus de
partícipe. Aunque B realiza el tipo, es considerado partícipe, pues actuaba en interés de A.
• Ventaja: Ya presupone un mecanismo de diferenciación entre autory partícipe (aun
que con claras deficiencias).
• Objeciones:
Es difícil determinar el animus de cada persona.
Queda a la decisión de los jueces determinar la cuál de las voluntades tiene el
sujeto, atentando contra el principio de legalidad.
Al sólo interesarse por las actitudes internas del sujeto, se pierde la vigencia de
la estructura del Derecho penal como lo conocemos hoy pierde su vigencia, por
que ya no atendemos a los tipos objetivos descritos.
c) Objetivas (concepto restrictivo de autor)
Existe distinción entre auto ry partícipe desde el punto de vista objetivo, pues causación
no es igual a realización del delito. Según este concepto, autores, sólo, quien comete por
sí mismo la acción típica, mientras que la sola contribución a la causa del resultado me
diante acciones no típicas no puede fundamentar autoría alguna.
Desde el prisma del concepto restrictivo de autor, la previsión de especiales formas de
participación, como la inducción y la complicidad, significa que la punibilidadse amplía a
acciones que quedan fuera del tipo, pues con arreglo al propio tipo sólo podría castigarse
al que por sí mismo mata, hurta u ofrece resistencia. Sin embargo, tanto la formal como
la material dejan de lado la parte subjetiva.
c.i) Objetivo-Formal:
Autores el que realiza la acción que encaja en el comportamiento descrito en el tipo,
mientras que partícipe es el que da cualquier otra aportación que causa el hecho
delictivo, y no puede subsumirse en el tipo.
Ejm. i: A sujeta a B, mientras C lo golpea hasta que muera. C sería autor pues encaja en la
conducta típica de homicidio, mientras que A sería partícipe pues no cumple con el tipo.
Ejm. 2 : A vierte veneno sobre el café de B y espera a que C, quien desconoce dicha acción, le
lleve la bebida. C encajaría en el tipo por lo cual sería el autor, mientras Aseria partícipe.
Objeciones:
• Se remite sólo a lo tipificado, restringiendo la punibilidad de autor sólo a aquel
que cometa el tipo descrito en la norma penal.
