BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 873 of 1506 --

Tema 6: Temas de la Especialidad Penal
De acuerdo a esta teoría, se puede calificar de autor al agente si:
La persona sabe el qué, el cómo, y cuándo se va a realizar el hecho delictivo. O sí rea
liza la acción típica personalmente (dominio de la acción).
Si hace ejecutar el hecho mediante otro cuya voluntad, según parámetros jurídicos,
no es libre, o que no conoce el sentido objetivo de la acción de su comportamiento
o lo abarca en menor medida que el hombre de atrás o que es sustituible a voluntad
en el marco de una maquinaria de poder organizada (dominio de la voluntad).
Debe dar una contribución objetiva al hecho (dominio funcional del hecho).
Si intervienen varias personas se tiene que dar un acuerdo previo a la realización del
hecho delictivo (plan delictivo).
Esta teoría finalista se considera adecuada para los delitos dolosos, es conforme a los
principios limitadores del ius puniendi y el Código Penal peruano la asume, puesto que
permite la distinción entre diferentes clases de autores y partícipes.
Clases de autor: Existen tres clases de autoría: directa, mediata y coautoría.
a) Autoría directa: Es autor el que realiza la acción típica descrita, por sí mismo, por lo que
tiene dom inio del hecho. Se pueden encontrar dos niveles: el nivel subjetivo consiste en la
resolución criminal basada en el carácter finalista en la cual se desea un cambio objetivo;
el nivel objetivo consiste en llevar a cabo esa resolución criminal a los hechos a través del
dom inio funcional del hecho. Se tiene el dominio de las circunstancias absolutasy el au
tores imprescindible.
Ejm.: A quiere secuestrar a B, por lo que lo espera a la salida del colegio, lo mete al carro, lo lleva a
una casa abandonada y lo mantiene cautivo. A es autor del delito de secuestro, pues tiene resolución
crim ina!y dominio funcional del hecho.
b) Coautoría: Es la realización conjunta de dos o más personas de la acción típica, en la cual
cada uno de los autores cumple un papel imprescindible en la ejecución de los hechos de
forma voluntaria y consciente, pues todos son autores.
Se pueden encontrar dos niveles: el nivel subjetivo se refiere a la corresolución criminal de
los distintos autores, mientras el nivel objetivo se refiere al codominio funcional del hecho
-debe haber realizado una parte objetiva-, es decir, han de conocer el qué, cómo, y cuán
do, o dicho en términos de Claus Roxin74, se trata de un dominio funcional del hecho en
el sentido de que cada uno de los coautores tienen en sus manos el dom inio del hecho a
través de un aporte que le corresponde en la división del trabajo.
Ejm i: A, B y C planean violar a D. A sujeta a D, Blo viola y C vigila. En este caso A, B y C cumplen
la resolución criminal, pero solo A y B tienen codominio funcional del hecho. C es partícipe al no
cum plir con esto último.
74 ROXIN, Claus, op. c¡t.,p. 560.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 874 of 1506 --

UBILEX
Ejm 2: A y B son padres del bebe C y ambos deciden irse de viaje dejando a C indefenso en la casa.
Regresan del viajey C estaba muerto por inanición. A y B son coautores de omisión en el delito de
homicidio.
Ejm. 3: A y B han montado conjuntamente la bomba y la han escondido en el auditorio, donde C,
mientras pronuncia su discurso el oponente político, va a detonarla. Los 3 son coautores.
Tipos de coautoría:
b .i. Coautoría ejecutiva directa: todos los autores realizan los actos ejecutivos.
b.2. Coautoría ejecutiva parcial: se da un reparto de las tareas ejecutivas.
b.3. Coautoría en la cual se da un reparto de papeles entre los diversos intervinientes
en la acción típica: aquí se incluyen casos en los que ciertos autores no se encuen
tran en el momento de la ejecución.
"La coactaría implica que los imputados cumplan roles específicos dentro de un plan común,
de tal forma que pueda desprenderse de su comportamiento, que medió una decisión común
orientada a obtener un resultado exitoso, que el aporte de cada uno fue esencial, y que intervi
nieron en la fase de ejecución desplegando un dominio parcial del acontecer, de manera que lo
sucedido en la perpetración les sea imputable a todos."
Sala Penal Permanente de la Corte Suprema de Justicia, Recurso de Nulidad N” 170-2010-Amazonas.
c) Autoría Mediata: El autor mediato se sirve de otra persona como instrumento para co
meter el hecho delictivo. En realidad se constituye un dom inio del hecho, en tanto hay un
dom inio sobre la voluntad de la otra persona. Es el autor quien tiene los elementos del
tipo dominados, pero quien ejecuta la acción típica es el instrumento. Es imprescindible
que el instrumento actúe sin libertad o sin conocimiento de la situación.
Según la situación del instrumento (o utilizado) se pueden distinguir cuatro clases:
• El instrumento realiza un hecho atípico positivo: falta la concurrencia de uno de los
elementos del tipo objetivo.
Ejm.: Caso de las autolesiones que se inflingen los miembros de una secta religiosa, quienes
son guiados y llevados a tal conducta por el líder espiritual. Como se señaló, las autolesio
nes son atípicas.
• El instrumento actúa sin dolo: falta de concurrencia de uno de los elementos del tipo
subjetivo.
Ejm. i: A introduce una gran cantidad de drogas en el carro de B que está a punto de cruzarla
frontera, configurándose el hecho sin dolo por parte de B.
Ejm. 2: A pide a B encender la luz en un piso lo que inocentemente hace B, activando así como
había planeado A en un lugar lejano un explosivo que mata a una persona.
• El instrumento es un inimputable-, cuando el instrumento es incapaz de culpabili
dad como los menores de edad, enfermos mentales, ebrios habituales, etc. Pero es
importante tener en cuenta lo mencionado por López Barja de Quiroga: “Es preciso
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 875 of 1506 --

Tema 6: Temas de la Especialidad Penal
conocer hasta que punto existe esa falta de capacidad, pues si a pesar de dicha carencia puede
tener dominio del hecho, en vez de autoría mediata, se trataría de una inducción."75
Ejm: A manda a su hijo de 5 años a que coloque la secadora enchufada en la tina donde está
tomando un baño de espuma la esposa de A.
• El instrumento actúa bajo coacción o miedo insuperable: el instrumento obra con
conciencia, pero sin libertad.
Ejm. i: A obliga a B aque robe un banco, bajo amenaza de m atar al hijo de este último.
Ejm. 2 : A determina a la m ujer B, fácilmente influenciabley sometida del todo a él sexual y
psicológicamente, para que mate a su esposo amenazándola con abandonarla si no lo hace.
En los dos primeros casos el instrumento actúa sin antijuricidad, mientras que en los
casos restantes sí se llega a configurar un hecho típico, pero no hay culpabilidad.
d) Autoría sucesiva: Hay un autor y un segundo autor que se suma cuando el hecho o los
hechos se están realizando; sin embargo, su actuación es imprescindible solo en un mo
mento específico.
En este punto hay que hacer una diferenciación entre delitos de configuración instan
tánea y delitos permanentes. En los primeros se ejecuta y hace efecto en el mismo mo
mento, dependiendo de lo que señala el tipo penal (matar a una persona. Por otro lado,
en los segundos, la ejecución se demora en el tiempo (secuestro) se dice de los delitos
permanentes que estos subsisten por la voluntad delictiva del autor tanto tiempo como
subsiste el estado antijurídico creado por ellos mismos.
La autoría sucesiva se da en los delitos permanentes, pues en el caso del secuestro pue
de haber sujetos que ingresan en un momento distinto de la configuración del delito.
De esta manera, no todos los autores tienen corresolución criminal, pero sí dom inio del
hecho en determinados momentos. Sin embargo, hay que dejar en claro que la autoría
sucesiva es un supuesto distinto a la coautoría.
Ejm.: A secuestra a B y lo mantiene cautivo en una casa abandonada; A le cuenta el hecho delictivo
a su amigo C, el cual decide ayudarlo cuidando a B.
PARTICIPACIÓN.- Los partícipes no tienen dominio del hecho. Para que exista participación
debe constatarse previamente el hecho principal de un autor al que relacionar el hecho acce
sorio del partícipe. La participación no es autónoma, sino dependiente del hecho del autor-
accesoriedad de la participación.
Principio de accesoriedad limitada:
La existencia del hecho accesorio (hecho del partícipe) depende de la existencia del hecho
principal (hecho del autor), es decir, para que exista un partícipe, es necesario que exista un
autor del mismo delito.
Según M ir Puig: “(...) la participación es accesoria respecto del hecho del autor, pero depende hasta cierto
punto: basta que el hecho del autor sea contrario al Derecho (antijurídico), no es preciso que el autor sea
culpable. Los elementos personalismos no se comunican entre ellos. Cuando se trata de delitos especiales
75 LOPEZ BARJA D EQ U IRO G A, Jacobo. op. cit., p. 289.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 876 of 1506 --

(tienen un elemento personal específico) se atenúa la pena para los extraneus por fa lta r en él el aspecto
de vulneración de deber que corresponde al intraneus”76.
Se puede ver este principio desde dos puntos de vista:
Externo.- Determina la participación en 3 casos:
Cuando el delito es consumado por al autor, se es partícipe del delito de consumación.
Ejm.: C convence a A que robe un banco y lo logra. A consuma el delito de robo. C es punible a título
de partícipe (instigador) de robo consumado por A.
Cuando el autor sólo realiza la tentativa (actos ejecutorios), se es partícipe del delito de
tentativa.
Ejm.:Z in te n ta m a ta ra ], inducido por K, pero falla en el disparo. I<será sólo partícipe (instigador)
de tentativa de homicidio de).
Cuando el autor sólo realiza actos preparatorios punibles, no se es partícipe porque viola
ría el principio de mínima intervención del Derecho Penal. De imputársele, se le sancio
naría por una participación muy lejana a la lesión del bien jurídico.
Ejm.:] compra un arma en el mercado negro del Rímac con la finalidad de m atar a su hermano. Z
acompaña a ); sin embargo,) no comete el delito. Entonces, no puede imputarse participación en
tenencia ilegal de armas a Z.
Interno.- Para sancionar al partícipe nuestro ordenamiento exige que la conducta del autor
sea por lo menos antijurídica (accesoriedad limitada)
Cuestiones problemáticas:
a. Excesos de autor: cuando el autor realiza un delito que va más allá de lo acordado con el
partícipe, no perjudica al partícipe.
Ejm.: A colabora con B para robarle a C, pero B además viola a C ¡a A sólo se le sanciona como par
tícipe de robo y no de violación.
b. Defectos del autor: cuando el autor realiza un delito más leve de lo acordado con el par
tícipe, beneficia al partícipe.
Ejm.: H induce a Baque mate a C; pero B disparay falla. H es sancionado como partícipe de tenta
tiva de homicidio y no de homicidio consumado.
c. Cualidad o naturaleza del delito: existen dos casos.-
Cuando la cualidad de los delitos es distinta, la conducta del partícipe no es punible.
