Tema 6: Temas de la Especialidad Penal
Ejm.:
Se planifica hurto: apoderamiento ilegítimo de un bien.
El autor realiza robo-, apoderamiento ilegítim o de un bien con violencia.
La conducta del partícipe es atípica y es impune, pues no hubo elemento de violencia en él.
Cuando la cualidad de los delitos es la misma, pero uno tiene un agravante, al partí
cipe de les castiga sólo por el delito básico.
Ejm.:
Se planifica roboapoderam iento ilegítim o de un bien con violencia.
El autor realiza un robo agravadoapoderam iento ilegítimo de un bien con violencia que des
encadena en muerte.
El partícipe, responde por el delito básico; el autor responderá por el delito cualifcado. La natura
leza del delito es la misma, por lo que la conducta del partícipe es típica pero sin agravante.
Clases de partícipe:
a) Instigación o inducción: Aquella acción que consiste en generar en otra persona la re
solución criminal, para la realización del hecho típicamente antijurídico. Sin embargo,
el inductor no tiene dom inio del hecho, pues su influencia es sólo psíquica, recayendo el
dom inio del hecho en manos del autor.
Teoría del O m ním odo Facturus - No hay inducción cuando la resolución criminal ya esta
ba presente con anterioridad en el sujeto.
El mensaje de la inducción debe ser:
Completo: que tenga contenido explícito de la acción típica.
Directo: dirigido a una persona o personas determinadas. Surgen dos interrogantes:
1. ¿Es posible inducción en masa? Es decir, inducción a muchas personas al mismo
tiempo. La respuesta es negativa.
2. ¿Es posible la inducción en cadena? En el Perú sí es posible, ya que no se exige que
el mensaje para ser directo, sea personal.
Concreto: el mensaje tiene que ser claro y eficaz.
Ejm.: A tiene un amigo que es chofer de “Hermes”y que tiene problemas económicos. Por esa
razón, A lo instiga a que robe una bolsa de dólares para solucionar sus problemas.
La instigación debe ser dolosa, no hay inducción imprudente. Se trata de un doble
dolo: por un lado, dolo de generar la resolución criminal en el sujeto; y por otro lado,
dolo de querer la materialización del delito.
Puede existir instigación de un delito imprudente, lo que tiene que ser dolosa es la
instigación.
Ejm.: A le dice al taxista 8 que acelere para llegar tem pranoy por esta razón choca.
Como señala el jurista Cobo del Rosal: “La inducción no seguida de realización es impune, mien
tras que en la autoría mediata, la punibi/idad comienza en la actuación sobre el instrumento.”77
77 COBO DEL ROSAL, Manuel. Derecho penal. Parte general, Tirant lo Blanch, Valencia, 1991, p. 758.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 878 of 1506 --

UBILEX
b) Complicidad: Cooperación para la realización de un delito ajeno. Se puede encontrar la
complicidad necesaria y no necesaria, las cuales se diferencian atendiendo al principio
de esencialidad o también llamado “de los bienes escasos”. Éste consiste en el análisis ex
ante para descubrirsi la participación del sujeto fue esencial (muy importante) o no para
cometer el delito.
Complicidad primaria o necesaria: cuando el aporte es importantísimo y difícil''
mente reemplazable, pero sí se puede sustituir (esencialidad no debe entenderse
como imprescindibilidad).
Ejm.: A quiere m atar a C, pero los únicos que tienen la llave de la casa de este son D y E. D
decide apoyara A, abriéndole la puerta.
Es importante resaltar que nuestro Código Penal, el artículo 25o describe la com
plicidad necesaria de una manera equivocada; pues al decir que sin la complicidad
necesaria no se hubiera perpetrado el delito, está diciendo que es imprescindible,
confundiéndola con la autoría. En realidad, no es imprescindible, sino difícil de re
emplazar, pero al fin y al cabo reemplazable.
Complicidad secundaria o no necesaria: cuando el aporte es fácilmente reemplaza-
bley el partícipe es de menor jerarquía.
E jm .:) decide golpeara K por lo que entra a su casa, mientras R está en la puerta percatándose
deque nadie venga. Cualquier otro pudo llevara cabo la participación de R.
El cómplice primario o necesario suele estar antes de la ejecución del delito, mien
tras que el secundario o no necesario, suele estar en la ejecución.
Por otro lado, puede haber instigación y complicidad a la vez:
Ejm.: H induce a Ba robar un banco,y además se encarga de avisarle si la policía llega mien
tras B roba.
c) Las organizaciones criminales.'' En este caso especial la figura de auto ría y participación,
antes estudiada, no puede ser aplicada eficazmente, ya que no se pueden identificar cla
ramente los sujetos activos de manera inmediata. Entre los delitos comunes más usuales
que cometen las organizaciones criminales están:
Trata de personas (art. 129 A)
Secuestro (art. 152o)
Tráfico ilícito de drogas (art. 296o)
Proxenetismo (art. 181o)
Pornografía (art. 189o)
Las teorías esbozadas para ser aplicadas, sobre todo cuando las bandas criminales realizan
delitos comunes (que puede cometer cualquier ciudadano) son:
• Teoría de la Instigación (Herzbery Kóhler):
Esta propone que el líder de la banda es un mero instigador y que los ejecutores de los
actos son autores. De estas surgen varias críticas ya que los ejecutores no tienen dominio
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 879 of 1506 --

Tema 6: Temas de la Especialidad Penal
de la organización; sin embargo, sí el líder de la banda. Se castiga como participe al que
realmente tiene el dom inio del hecho.
• Teoría de la coautoría (sostenida por Jakobs y defendida por Muñoz Conde):
Esta nos dice que en las bandas criminales hay una coautoría; es decir, que todos los
miembros son autores porque tienen dominio del hecho. Dentro de las críticas a esta
teoría, se dice que muchas veces no hay coresolución criminal de los cabecillas con los
ejecutores, pues hay ejecutores que ni siquiera conocen al cabecilla. Además, difícilmente
hay ejecución conjunta.
• Teoría del autor detrás del autor (Roxin):
En esta teoría, el líder es autor mediato, el cual utiliza como instrumento a otros autores
con voluntady conocimiento. Tiene dos argumentos principales-.
El dom inio organizacional del hecho. El lídertiene la dirección de todo el delito.
Intercambiabilidad de los sujetos ejecutores. Roxin acepta que los instrumentos tie
nen voluntad, pero ello lo ve como irrelevante, pues estos son fungióles.
Según Roxin, todos los sujetos de la banda criminal son punibles, en mayor o menor grado. El
sujeto que esté más lejos de la ejecución del delito es el más responsable, el más cercano a la
ejecución es el menos responsable. Es claro que Roxin propone el uso de la figura de la autoría
mediata, pero con la variante de que el instrumento sí posee dolo. En este punto ha sido muy
criticado, aunque él se ha amparado en la irrelevancia de la existencia del dolo debido a la
fungibilidad de los ejecutores.
CASO DE LOS DELITOS ESPECIALES: LA INFRACCIÓN DEL DEBER
a. Diferencia entre delitos comunes y especiales:
D. comunes: cualquier ciudadano puede ser sujeto activo de aquellos delitos.
Ejm.: art. 106o (homicidio simple), art. 188° (robo).
D. especiales: el ciudadano necesita de una cualificación especial para ser sujeto ac
tivo del delito. A su vez hay dos tipos de delitos especiales:
• Especiales Propios: delitos que sólo pueden ser cometidos por el sujeto que ostenta
la cualidad especial, no habiendo delito correlativo común para los particulares.
Ejm.: art. 418o (prevaricato).
• Especiales Impropios: son delitos especiales para los cuales existe un delito ho
mólogo o correlativo para los particulares.
Ejm.: art. 107 (parricidio, cuyo correlativo común es el homicidio).
b. Teorías aplicables a la realización de delitos especiales:
Roxin ha distinguido dos niveles de teorías, según se trate de delitos de d om inioy delitos
de infracción al deber.
i. Teoría del dominio del hecho: es la aplicada hasta el mom ento para los casos tra
dicionales de autoríay participación, pero presenta dificultades para su aplicación
en la determinación de la participación en sentido amplio en los delitos especiales,
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 880 of 1506 --

y en especial en los casos que los delitos sean cometidos por organizaciones crim i
nales.
íi. Teoría de la infracción del deber: se deshecha totalmente el dom inio del hecho
y lo que importa es si hay o no infracción a un deber de origen legal - extrapenal.
Siempre será autor, el intraneus (el que tiene el deber) y será partícipe el extraneus
(quien no tiene el deber).
En el caso de los delitos especiales propios, el intraneus es autor del delito especial y
el extraneus es partícipe también del delito especial,ya que en este caso no existe un
’ delito correlativo común para el extraneus.
Ejm.: El juez ju n to con el secretario confabulan contra una de las partes, configurando el pre
varicato (art. 478 o). Sólo el juez (intraneus) tiene el deber, por ello es autor de prevaricato. En
cambio, el secretario (extraneus) no reúne la cualidad especial y no tiene el deber, por lo cual
sólo es partícipe del delito especial.
En los delitos especiales impropios, el intraneus es el autor del delito especial y en
el caso del extraneus será partícipe del delito correlativo común. Ello no vulnera el
principio de accesoriedad limitada, pues el delito especial impropio cometido por el
autor vulnera el mismo bien jurídico y realiza la misma acción típica del tipo común.
Ejm.: A mata a su padre con la ayuda de B. A es autor del delito de parricidio (para el cual se
exige el requisito especial de parentesco). B sólo podrá ser partícipe del delito de homicidio,
pues no reúne el requisito especial de parentesco.
LA AUTORÍA Y LA PARTICIPACIÓN EN DELITOS DOLOSOS, IMPRUDENTES Y OMISIVOS
a) Delitos dolosos: se aplica la teoría del dominio del hecho desarrollada a lo largo del pre
sente trabajo. Esta teoría, al ser finalista, está orientaday elaborada básicamente en fun
ción de los delitos dolosos. Se utiliza un concepto restrictivo del autor, por eso sólo en
ellos se habla de un dominio final del hecho típico.
b) Delitos Imprudentes: ante las dificultades que planteaba la aplicación de la teoría del
dom inio del hecho en los delitos imprudentes (por la pérdida del control final del hecho
en el tipo imprudente), surgió la idea de plantear para los delitos imprudentes, la u tili
zación de una teoría unitaria en la cual todo sujeto que cause por imprudencia el hecho
será autor. Hoy en día, se está aplicando la teoría de la infracción al deber para los delitos
imprudentes, en los cuales se infringe un deber objetivo de cuidado.
c) Delitos omisivos: se desliga de la teoría del dom inio del hecho, aplicando en estos casos
la teoría de la infracción al deber. Lo único decisivo es la infracción del deber por parte del
garante, que será autor así no tenga dominio funcional del hecho.
ACTUAR EN LUGAR DE OTRO.- El artículo 27o del Código Penal78 regula la institución del
actuar en lugar de otro. Dicha institución sirve para cubrir los vacíos de punibilidad que se
presentan en los delitos especiales cometidos por representantes tanto de personas jurídi-
78 A rtíc u lo 27.- A ctu ac ió n en n o m b re d e otro:
El que actúa como órgano de representación autorizado de una persona jurídica o como socio representante autorizado
de una sociedad y realiza el tipo legal de un delito es responsable como autor, aunque los elementos especiales que
fundamentan la penalidad de este tipo no concurran en él, pero sí en la representada.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 881 of 1506 --

Tema 6: Temas de la Especialidad Penal
cas, como naturales. La justificación para trasladar responsabilidad a los representantes de
la empresa radica en la teoría de la representación79 por cuanto los deberes institucionales se
transfieren normalmente mediante una relación de representación.
El representante habrá realizado el tipo penal correspondiente por el incumplimiento de un
deber institucional transferido por el representado, siendo aquí irrelevante si este cum pli
miento tiene lugar mediante una acción o una omisión. Sólo bastará para imputar respon
sabilidad penal a los miembros de una persona jurídica, poder verificar la calidad de repre
sentante que ostenta en la empresa y la posibilidad de haber cumplido con el deber exigido.
7. CONSECUENCIAS JURÍDICAS DEL DELITO
Sistema de penas, medidas de seguridad, reparación civil y las consecuencias accesorias.
Sistema penal vigente es dualista: penas y medidas de seguridad que se aplican alternativa
mente, cuando se aplican ambas: sistema vicarial.
Sujeto en condiciones normales: aplica penas.
Sujeto adolece de un trastorno que exime de responsabilidad: aplica medidas de seguri
dad.
Trastorno no excluye responsabilidad: aplican ambas.
A. La pena.- Medio tradicional, consiste en la disminución o anulación de un bien jurídico
(personal, proporcional y legal).
Por su forma de aplicación, las penas pueden ser:
• Principales: aplican en forma autónoma.
• Accesorias: acompañan a una principal.
• Paralelas: alternativas o conjuntas.
El artículo z8° del Código Penal establece las siguientes clases de pena, en relación al bien
jurídico que se afecta, a saber:
- Multa."
"Artículo 28. - Las penas aplicables de conformidad con este Código son:
- Privativa de libertad;
- Restrictivas de libertad;
Limitativas de derechos; y
i) Pena privativa de libertad.- Consiste en el internam iento del responsable penal
en un centro penitenciario para que cumpla con la sanción impuesta por el Juez
en la sentencia condenatoria. El artículo 29o del Código Penal establece que la
pena de privación de libertad puede ser tem poral de una duración m ínim a de
dos días y máxima de treinta y cinco años; o, indefinida, llamada tam bién cade
na perpetua.
79 GARCÍA CAVERO, Percy, op. cit., p. 769.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 882 of 1506 --

Por otro lado, el condenado que no haya sido anteriormente sujeto de sentencia por
delito podrá acceder a la pena de vigilancia electrónica personal, cuyo cómputo de
aplicación por día será igual a un día de privación de libertady se ejecutará en el do
micilio o lugarque señale, a partirdel cual se determinarásu radio de acción, itinera
rio de desplazamiento y tránsito. El condenado estará sujeto a vigilancia electrónica
personal para cuyo cumplim iento el juez fijará las reglas de conducta que prevé la
ley, así como todas aquellas reglas que considere necesarias a fin de asegurar la ido
neidad del mecanismo de control.
Conforme lo establece el artículo 29°-A, la aplicación de la pena de vigilancia electró
nica personal será en prioridad a los siguientes sujetos:
a) Los mayores de 65 años.
b) Los que sufran de enfermedad grave, acreditada con pericia médico legal.
c) Los que adolezcan de dlscapacidad física permanente que afecte sensiblemente su capaci
dad de desplazamiento.
d) Las mujeres gestantes dentro del tercer trim estre del proceso de gestación. Igual tra ta
miento tendrán durante los doce meses siguientes a la fecha del nacimiento.
e) La madre que sea cabeza de familia con hijo menor o con hijo o cónyuge que sufra de disca
pacidad permanente, siemprey cuando haya estado bajo su cuidado. En ausencia de ella, el
padre que se encuentre en las mismas circunstancias tendrá el mismo tratamiento.
El condenado deberá previamente acreditar las condiciones de su vida personal, la
boral, fam iliar o social con un informe social y psicológico.
El Código Penal establece lavigilanciaelectrónica personal como una penay la ubica
como una pena privativa de libertad. Pero, ¿es una pena privativa de libertad en sí?, con
sideramos que no, pues ésta no afecta en modo alguno la libertad del procesado o
condenado para desplazarse, es decir, la persona no pierde su libertad ambulatoria,
tan sólo se le impone un mecanismo de control para monitorearel tránsito.
De ahí que, lo más correcto hubiera sido consignarla dentro de las penas limitativas
de derechos (art. 31 Código Penal), aplicable de manera sustitutiva a la pena privativa
de libertad.
Conforme a la Ley 32181 (Pub. 1 1 .1 2 .2 0 2 4 ) que modificó el art. 22 del CR los mayores de 80 años, por
razones humanitarias, afrontarán su condena conforme a ios alcances del artículo 2 8 8 o del artículo
2 9 0 de CPP, es decir, bajo comparecencia con restricciones o detención domiciliaria.
Pena restrictiva de la libertad.- El artículo 30o del Código Penal define la pena res
trictiva d libertad como aquella sanción de expulsión del país aplicable a los extran
jeros luego de haber cumplido la pena privativa de libertad por la comisión de un de
lito o la concesión de un beneficio penitenciario que acortada la sanción, quedando
prohibido su reingreso al país.
Finalmente, la disposición normativa establece que en el caso de expulsión por con
cesión d beneficios penitenciarios, el Perú mantiene jurisdicción exclusiva sobre la
condena impuesta.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 883 of 1506 --

Tema 6: Temas de la Especialidad Penal
ííi) Penas limitativas de derechos.- En términos generales, las penas limitativas de de
rechos consisten la suspensión en el ejercicio de determinados derechos, obligacio
nes de hacer o la realización de trabajos a favor de la comunidad. El artículo 31o del
Código Penal establece las clases de penas limitativas de derechos, a saber:
"1. Prestación de servicios a la comunidad;
2. Limitación de días libres; e
3. Inhabilitación."
Las penas lim itativas de derechos previstas en los dos primeros incisos del artícu
lo 31o se aplican como autónomas cuando están específicamente señaladas para
cada delito y también como sustitutivas o alternativas de la pena privativa de li
bertad, cuando la sanción sustituida a criterio del Juez no sea superior a 05 años
La duración de las penas de prestación de servicios a la com unidady lim itativa de
días libres se fijará, cuando se apliquen como sustitutivas de la pena privativa de
libertad, de acuerdo con las equivalencias establecidas en el artículo 52o del Códi
go Penal.
a. Prestación de servicios a la comunidad: Esta penaobligaal condenado a traba
jos gratuitos en entidades asistenciales, hospitalarias, escuelas, orfanatos, otras
instituciones similares u obras,ya sean públicos o privados.
Los servicios son asignados, en lo posible, conforme a las aptitudes del conde
nado, debiendo cumplirse en jornadas de diez horas semanales, entre los días
sábados, domingos o feriados, de modo que no perjudiquen la jornada normal
de su trabajo habitual.
El condenado puede ser autorizado para prestar estos servicios en los días há
biles semanales, computándose la jornada correspondiente. Esta pena se ex
tiende de diez a ciento cincuenta y seis jornadas de servicios semanales, salvo
disposición distinta de la ley.
b. Limitación de días libres: Esta pena obliga al condenado a permanecer los días
sábados, domingos y feriados, hasta por un máximo de diez horas semanales, a
disposición de una institución pública o privada para participar en programas
educativos, psicológicos, de formación laboral, cultural o social.
Esta pena se extiende de diez a ciento cincuentay seis jornadas de limitación se
manales, salvo disposición distinta de la ley. Durante este tiempo, el condenado
recibe orientaciones y realiza actividades adecuadas e idóneas para su rehabili
tación y formación.
c. Inhabilitación: La pena de inhabilitación puede ser impuesta por el Juez como
principal o accesoria, produciendo las medidas establecidas en el artículo 36odel
Código Penal, a saber:
