1. Privación de la función, cargo o comisión que ejercía el condenado, aunque provenga de elección
J popular;
2. Incapacidad o impedimento para obtener mandato, cargo, empleo o comisión de carácter público;
Suspensión de los derechos políticos que señale la sentencia;
Incapacidad para ejercer por cuenta propia o por intermedio de tercero profesión, comercio, arte o indus
tria, que deben especificarse en la sentencia;
Incapacidad para el ejercicio de la patria potestad, tutela o cúratela;
Suspensión o cancelación de la autorización para portar o hacer uso de armas de fuego. Incapacidad de
finitiva para renovar u obtener licencia o certificación de autoridad competente para portar o hacer uso d e:
armas de fuego, en caso de sentencia por delito doloso o cometido bajo el influjo del alcohol o las drogas.
Suspensión, cancelación o incapacidad definitiva para obtener autorización para conducir cualquier tipo
