Privación de grados militares o policiales, títulos honoríficos u otras distinciones que correspondan al
cargo, profesión u oficio del que se hubiese servido el agente para cometer el delito;
Incapacidad definitiva de las personas condenadas con sentencia consentida o ejecutoriada por los deli
