el inciso 2 del artículo 316 del Código Penal, por cualquiera de los delitos de violación de la libertad sexual
tipificados en el Capítulo IX del Título IV del Libro Segundo del Código Penal o por los delitos de tráfico ilíci- ■
to de drogas para ingresar o reingresar al servicio docente o administrativo en instituciones de educación
básica o superior, pública o privada, en el Ministerio de Educación o en sus organismos públicos descen
tralizados o, en general, en todo órgano dedicado a la educación, capacitación, formación, resocialízación
o rehabilitación, Esta medida se impone obligatoriamente en la sentencia como pena principal;
Privación del derecho a residir en determinados lugares o acudir a ellos;
Prohibición de aproximarse o comunicarse con la víctima, sus familiares u otras personas que determine
el juez; o,
Prohibición de comunicarse con internos o visitar establecimientos penitenciarios."
En caso que la inhabilitación sea principal, la misma se extenderá de seis meses a
diez años, incapacidad definitiva a que se refieren los numerales 6 , 7 y 9 del artículo
36° del Código Penal. Por otro lado, la inhabilitación accesoria se impondrá cuando el
hecho punible cometido por el condenado constituya un abuso de autoridad, de car
go, de profesión, oficio, poder o violación de un deber inherente a la función pública,
comercio, industria, patria potestad, tutela, cúratela, o actividad regulada por ley; y
se extiende por igual tiempo que la pena principal.
Finalmente, la pena de inhabilitación referida a la suspensión, cancelación o incapa
cidad definitiva para obtener autorización para conducir cualquier tipo de vehículo
se podrá aplicar como pena accesoria en los delitos culposos de tránsito.
iv) M ulta.- El artículo 40° del Código Penal define la m ulta como aquella pena que obli
ga al condenado a pagar al Estado una suma pecuniaria fijada en días-multa, cuyo
importe equivale a su ingreso diarioy se determina atendiendo a su masa patrimo
nial (rentas, remuneraciones, nivel de gasto y demás signos exteriores de riqueza).
La pena de multa se extenderá de diez a trescientos sesentay cinco día-multas, salvo
disposición distinta de la Ley, siendo el importe de cada día-multa un valor ascen
dente entre el veinticinco al cincuenta por ciento del ingreso diario del condenado
cuando viva exclusivamente de su trabajo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 885 of 1506 --

Tema 6: Temas de la Especialidad Penal
La multa fijada en la sentencia deberá ser pagada dentro de los diez días posteriores
a dicha diligencia; sin embargo, a pedido del condenandoy de acuerdo a las circuns
tancias, el Juez podrá permitir que el pago se efectúe en cuotas mensuales. El cobro
de la m ulta se podrá efectuar mediante el descuento de la remuneración del con
denado cuando se aplica aisladamente o cuando se aplica acumulativamente con
pena lim itativa de derechos o fuere concedida la suspensión condicional de la pena.
El descuento no debe incidir sobre los recursos indispensables para el sustento del
condenadoy su familia.
B. Medidas de seguridad.- Consiste en instrumentos de tratam iento a sujetos que se en
cuentran en supuestos de inim putabilidad total o relativa.
Diferencias entre penay medidas de seguridad:
Modalidades:
• Internamiento: Ingreso y tratamiento del inimputable, el peligro de que el agente
cometa delitos considerablemente graves.
• Tratamiento ambulatorio: conjuntamente con la pena del imputable relativo.
Duración de las Medidas de Seguridad: Internación no puede exceder el tiempo de du
ración de la pena privativa de libertad que hubiera correspondido aplicarse al delito co
C. Reparación civil- Se determina conjuntamente con la penay está dirigida a satisfacer la
pretensión pecuniaria de la víctima.
Características:
Derecho renunciable, objeto de transacción, dación en pago o condonación.
No se extingue con la muerte del autor, es transmisible a los herederos.
Se basa en los efectos que el delito ha producido.
Los herederos del agraviado pueden exigir el pago de la reparación civil.
En casos de amnistía, indulto y causas de exculpación, la reparación civil subsiste.
Varios sentenciados o terceros civilmente responsables: obligación solidaria.
Elementos:
La restitución del bien o su equivalente en dinero: restitución cuando se haya en
poder de un tercero, restauración del bien al estado existente antes de la producción
del ilícito penal.
Sustento: culpabilidad del autor
Imputables
Finalidad: resocialización
Fundamento: peligrosidad del sujeto
Inimputables absolutos o relativos
Finalidad: Tuitiva y curativa
metido.
