La indemnización por daños y perjuicios: daño emergente y lucro cesante.
Sí no paga reparación civil:
Actos u obligaciones asumidas con posterioridad al delito se pueden declarar inefi
caces, siempre que disminuya su patrimonio.
Si no tiene bienes, retener hasta un tercio de su remuneración.
(]_.) "TERCERO - Que está fuera de toda discusión la culpabilidad del encausado en la comisión
del hecho punible; que la impugnación se circunscribe al extremo de la determinación judicial
IggSLr. de la pena de inhabilitación impuesta y al monto de la reparación civil; que la confesión sincera
a S B B m del citado encausado no puede ser valorada como presupuesto para establecer la cuantía de la
reparación civil -que no es una pena-, en tanto que está reservada de ser el caso para rebajar
la pena del confeso a límites inferiores del mínimo legal; que la naturaleza de la acción civil ex
delito es distinta, pues tiene como finalidad reparar el daño o efecto que el delito ha tenido sobre
la víctima y, consecuentemente, debe guardar proporción con los bienes jurídicos que se afectan; que de autos
se advierte que el encausado Arge Chanca se apoderó de mil novecientos dólares destinados a la compra de
computadoras para un centro educativo, lo que generó perjuicio tanto a la propia institución académica cuanto
a los educandos; que, siendo así, el monto fijado por el Tribunal sentenciador por concepto de reparación civil
se encuentra arreglado a ley." Sala Penal Permanente de la Corte Suprema de Justicia, Recurso de Nulidad N° 0948-
2005-Junín.
(2.) "SEXTO.- Que en este contexto, la restitución, pago del valor del bien o indemnización por los daños y per
juicios ocasionados, según corresponda cuando se trate de procesos en los que exista pluralidad de acusados
por el mismo hecho y sean sentenciados independientemente, por diferentes circunstancias contempladas en
nuestro ordenamiento procesal penal, debe ser impuesta para todos, la ya fijada en la primera sentencia firme,
esto con el objeto de que: a) exista proporción entre el daño ocasionado y el resarcimiento, b) se restituya, se
pague o indemnice al agraviado sin mayor dilación, y c) no se fijen montos posteriores que distorsionen la
naturaleza de la reparación civil dispuestas mediante los artículos noventa y tres, y noventa y cinco del Código
Penal. Sala Penal Permanente de la Corte Suprema de Justicia. Recurso de Nulidad N° 0216- 2005-Huánuco:
D. Consecuencias accesorias.- Orientadas a prevenirla continuidad en la actividad delictiva
y a los efectos de la misma. Se consideran como consecuencias adicionales a la pena, por
una responsabilidad subsidiaria que corresponde a la persona jurídica que estuviera vin
culada a la actividad criminal.
• El decomiso: alcanza a los efectos o instrumentos del delito, que pasan a ser propie
dad del Estado.
• Privación de beneficios a personas jurídicas y otras consecuencias. Cuando la in
fracción fuera cometida en ejercicio de sus actividades por sus funcionarios o repre
sentantes, cuando sea necesario para cubrir la reparación, se les priva de sus benefi
cios o utilidades.
De acuerdo al Principio de Culpabilidad la pena debe recae sobre una persona individual o
individualizadle; sin embargo, siempre surgió la interrogante de cómo se puede sancionar a
las empresas por las cuales se ha perpetrados hechos punibles o cuya constitución sólo tuvo
como fin la comisión de ilícitos penal. Ante esto, el artículo 105o del Código Penal80 regula las
80 Artículo 1 0 5 .-Medidas aplicables a las personas jurídicas.
Si el hecho punible fuere cometido en ejercicio de la actividad de cualquier persona jurídica o utilizando su organización
para favorecerlo o encubrirlo, el Juez podrá aplicar todas o algunas de las medidas siguientes:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 887 of 1506 --

Tema 6: Temas de la Especialidad Penal
consecuencias accesorias impuestas a la persona jurídica cuando el hecho punible fuera co
metido en ejercicio de la actividad de dicha entidad.
En ese sentido, en nuestra legislación la persona jurídica no responde penalmente por la co
misión de un ilícito penal por parte de uno de sus miembros o funcionarios en ejercicio de su
actividad; sin embargo, dentro del proceso penal puede imponérsele un conjunto de medidas
preventivas de carácter civil o administrativo81.
El artículo 105odel Código Penal exige presupuestos materialesy procesales necesarios para la
imposición de las consecuencias accesorias.
• Los presupuestos materiales son la concurrencia necesaria de un hecho principal realiza
do por una persona natural, el juicio de prognosis y el test de proporcionalidad del juez.
En prim er lugar, el hecho principal (punible) debe estar vinculado a la actividad u
organización de la persona jurídica, no necesariamente debe ser culpable el autor
para que se le imponga consecuencia accesoria a la empresa, por el ejemplo, el re
presentante puede incurriren una causal de inimputabilidad.
En segundo lugar, el juicio de prognosis refiere que el juez al momento de imponer la
consecuencia accesoria debe valorar la estructura de la persona jurídica con la fina
lidad de determinar si es probable la comisión futura de hechos delictivos a través o
con ayuda de la persona jurídica.
Finalmente, en tercer lugar, el juez debe realizar un test de Proporcionalidad respec
to a la idoneidad, necesidady proporcionalidad propiamente dicha de imponer una
consecuencia accesoria a la persona jurídica y su contraste con los derechos de sus
trabajadores y acreedores que podrían verse perjudicados con dicha medida82.
• En cuanto a los presupuestos procesales, se exige que la persona jurídica haya sido cons
tituida en tercero civilmente responsable durante el proceso penal instaurado contra el
autor del delito. Ello, se fundamenta en la garantía procesal que ostentan todas las perso-
i. Clausura de sus locales o establecimientos, con carácter temporal o definitivo. La clausura temporal no excederá de
cinco años.
i. Disolución de la sociedad, asociación, fundación, cooperativa o comité.
3. Suspensión de las actividades de la sociedad, asociación, fundación, cooperativa o comité por un plazo no mayor de
dos años.
4. Prohibición a la sociedad, fundación, asociación, cooperativa o comité de realizar en el futuro actividades, de la clase
de aquellas en cuyo ejercicio se haya cometido, favorecido o encubierto el delito.
La prohibición podrá tener carácter temporal o definitivo. La prohibición temporal no será mayor de cinco años.
5. Multa no menor de cinco ni mayor de quinientas unidades impositivas tributarias.
Cuando alguna de estas medidas fuera aplicada, el Juez ordenará a la autoridad competente que disponga la
intervención de la persona jurídica para salvaguardar los derechos de los trabajadores y de los acreedores de la persona
jurídica hasta por un período de dos años.
El cambio de la razón social, la personería jurídica o la reorganización societaria, no impedirá la aplicación de estas medidas.
Respecto de los partidos políticos no se aplica lo dispuesto en los numerales i, i y 3 del primer párrafo. A dichas organizaciones
solo se aplica el régimen sancionador en los supuestos previstos en la Ley 28094, Ley de Organizaciones Políticas.
La responsabilidad penal se aplica de manera individual a los sujetos implicados en el ilícito.
