UBILEX
ñas, ya sean naturales o jurídicas, de poder ejercer el derecho de defensa consagrado en
el artículo 139o Inciso 14) de nuestra Constitución Política83.
Por otro lado, el artículo 105°-A establece los siguientes criterios para la determinación de
las consecuencias aplicables a las personas jurídicas:
"Las medidas contempladas en el artículo anterior son aplicadas de forma motivada por etjmz>i:em.
atención a los siguientes criterios de fundamentación y determinación, según corresponda:
1. Prevenir la continuidad de la utilización de la persona jurídica en actividades delictivas.
2. La modalidad y la motivación de la utilización de la persona jurídica en el hecho punible.
3. La gravedad del hecho punible realizado.
4. La extensión del daño o peligro causado.
5. El beneñcio económico obtenido con el delito.
6. La reparación espontánea de las consecuencias dañosas del hecho punible.
7. La finalidad real de la organización, actividades, recursos o establecimientos de la persona jurídica.
La disolución de la persona jurídica se aplica siempre que resulte evidente que ella fue constituida y operó
habitualmente para favorecer, facilitar o encubrir actividades delictivas."
8 . D E T E R M IN A C IÓ N J U D I C I A L D E L A P E N A
Conforme a lo previsto en el artículo 45o del Código Penal, el juez, al momento de fundamen-
ta ry determinar la pena, tiene en cuenta:
a. Las carencias sociales que hubiese sufrido el agente o el abuso de su cargo, posición eco
nómica, formación, poder, oficio, profesión o función que ocupe en la sociedad;
b. Su culturay sus costumbres; y,
c. Los intereses de la víctima, de su fam ilia o de las personas quede ella dependen.
Individualización de la pena (Art. 45°-A Código Penal): Toda condena contiene fundamen
tación explícita y suficiente sobre los motivos de la determinación cualitativa y cuantitativa
de la pena. Para determinar la pena dentro de los límites fijados por ley, el juez atiende la
responsabilidad y gravedad del hecho punible cometido, en cuanto no sean específicamente
constitutivas de delito o modificatorias de la responsabilidad.
El juez determina la pena aplicable desarrollando las siguientes etapas:
a. Identifica el espacio punitivo de determinación a partir de la pena prevista en la ley para
el delito y la divide en tres partes.
b. Determina la pena concreta aplicable al condenado evaluando la concurrencia de cir
cunstancias agravantes o atenuantes observando las siguientes reglas:
• Cuando no existan atenuantes ni agravantes o concurran únicamente circunstancias
atenuantes, la pena concreta se determina dentro del tercio inferior.
• Cuando concurran circunstancias de agravación y de atenuación, la pena concretase
determina dentro del tercio intermedio.
83 Ibidem, pp. 97- 10 0 .
88 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 889 of 1506 --

Tema 6: Temas de la Especialidad Penal
• Cuando concurran únicamente circunstancias agravantes, la pena concreta se deter
mina dentro del tercio superior.
c. Cuando concurran circunstancias atenuantes privilegiadas o agravantes cualificadas, la
pena concreta se determina de la siguiente manera:
• Tratándose de circunstancias atenuantes, la pena concreta se determina por debajo
del tercio inferior;
• Tratándose de circunstancias agravantes, la pena concreta se determina por encima
del tercio superior; y
• En los casos de concurrencia de circunstancias atenuantes y agravantes, la pena con
creta se determina dentro de los límites de la pena básica correspondiente al delito.
El flamante artículo 4 5 °-A del Código Penal introduce un nuevo sistema de individualización
de la pena. Destina los dos primeros párrafos de este dispositivo a reglas básicas vinculadas al
deber de motivación de los fallos, así como al ne bisin ídem.
a. Concreción de la pena en delitos donde no concurran circunstancias modificativas
cualificadas o privilegiadas.
El caso más simple, sería aquel donde no concurren circunstancias de agravación cuali
ficada ni atenuantes privilegiadas. Aquí, se ha de proceder a dividir el marco penal abs
tracto del tipo penal (sea este un delito simple o en su forma agravada) en tres partes,
obtendremos así un tercio inferior, un tercio intermedioy un tercio superior (art. 45°-A inc.
i). Para determinar en qué tercio se ha de individualizar la pena (pena concreta) debemos
atender a la concurrencia de las circunstancias de atenuación y agravación genéricas, esto
es, las previstas en el artículo 46oCódigo Penal.
De este modo, si no existen circunstancias atenuantes ni agravantes o concurran única
mente circunstancias atenuantes, la pena concreta se determinará dentro del tercio infe
rior. Cuando concurran circunstancias de agravación y de atenuación, la pena concreta se
determina dentro del tercio intermedio. La pena se determinará dentro del tercio superior
cuando sólo concurran circunstancias agravantes. Ubicado el tercio correspondiente, el
Juez procederá a individualizar la pena en atención al alcance o entidad del injusto co
metido, para lo que hade atendera valorar los factores previstos en el artículo 45° Código
Penal y 46oCódigo Penal.
b. Concreción de la pena en delitos con circunstancias modificativas cualificadas o privi
legiadas.
En este supuesto, se ponen de manifiesto problemas de técnica legislativa. El inc. 3 del
artículo 45°''A pretende indicar cómo se determinará la pena concreta cuando concurran
atenuantes privilegiadas o agravantes cualificadas. Y así, señala que tratándose de cir
cunstancias atenuantes, la pena concreta se determina por debajo del tercio inferior [lit.
a)]; tratándose de circunstancias agravantes, la pena concreta se determina por encima
del tercio superior [lit. b)].
En este dispositivo el legislador indica que el marco penal abstracto siempre se habrá
de dividir en tres desde un principio, sea que concurran o no circunstancias agravantes
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 890 of 1506 --

UBILEX
cualificadas o atenuantes privilegiadas. Determinado así que la pena concreta se ha de
ubicar en el tercio superior o por encima hasta donde opere la agravante cualificada, o en
el tercio inferior o hasta donde opere la atenuante privilegiada, entendemos que se debe
proceder a individualizar la pena, para lo cual se ha de atender a los mismos criterios se
ñalados en el caso anterior, esto es, a las circunstancias de agravación y atenuación gené
rica del artículo 46o del Código Penal y a los factores de fundamentación y determinación
de la pena (art. 45° Código Penal).
Igualmente, se habrá de tener en cuenta la posible aplicación de normas procesales que
tengan por virtud una reducción de la pena ya individualizada. Sería el caso de los bene
ficios por confesión sincera o terminación anticipada (arts.i6i° y 471o del Código Procesal
Penal de 2004, respectivamente).
Sí parece cuestionable la regla prevista en el literal c) del inc. 3 del artículo 45°-A. Señala
que en los casos de concurrencia de circunstancias atenuantes [privilegiadas] y agravan
tes [cualificadas], la pena concreta se determina dentro de los límites de la pena básica
correspondiente al delito. Esto, más que una compensación, como ocurre en otros orde
namientos, supone simplemente una anulación de ambas circunstancias; lo que sería
más criticable cuando la atenuante privilegiada puede reducir la pena en una proporción
o cantidad mayor que el incremento de la agravante cualificada. Claro que mientras no se
defina o precise los límites hasta donde se puede reducir la pena en las atenuantes privile
giadas, la determinación de la pena seguirá estando librada al prudente arbitrio del Juez.
Ejemplo: Delito de Homicidio
Espacio punitivo (pena mínim a 6 -pena m áxim a 20) = 74 años.
Espacio punitivo debe dividirse en tercios = 74 años x 72 meses = 1 6 8 /3 = 5 6 meses por cada tercio.
