ii. Ejecutar la conducta punible sobre bienes o recursos públicos;
iii. Ejecutar la conducta punible por motivo abyecto, fútil o mediante precio, recompen
sa o promesa remuneratoria;
iv. Ejecutar el delito bajo móviles de intolerancia o discriminación de cualquier índole;
v. Emplear en la ejecución de la conducta punible medios de cuyo uso pueda resultar
peligro común;
vi. Ejecutar la conducta punible mediante ocultamiento, con abuso de la condición de
superioridad sobre la víctima o aprovechando circunstancias de tiempo, modo o lu
gar, que dificulten la defensa del ofendido o la identificación del autor o partícipe;
vii. Hacer más nocivas las consecuencias de la conducta punible, que las necesarias para
consumar el delito;
viii. Realizar la conducta punible abusando el agente de su cargo, posición económica,
formación, poder, oficio, profesión o función;
ix. La pluralidad de agentes que intervienen en la ejecución del delito;
x. Ejecutar la conducta punible valiéndose de un inimputable;
x¡. Cuando la conducta punible es dirigida o cometida total o parcialmente desde el
interior de un lugar de reclusión por quien está privado de su libertad o se encuentra
fuera del territorio nacional;
xii. Cuando se produce un daño grave al equilibrio de los ecosistemas naturales;
xiii. Cuando para la realización de la conducta punible se han utilizado armas, explosivos
o venenos, u otros instrumentos o procedimientos de similar eficacia destructiva.
H a b it u a lid a d y R e in cid e n cia : Son situaciones que podrían ser valoradas porel juez para efec
tuar el incremento de la pena, son circunstancias cualificadas de agravación que cumplen una
función di fe re ndadora basada en la prevención especial.
La reincidenciay la habitualidadson instituciones que han sido introducidas en el Código Pe
nal a través de la Ley N° 28726, Ley que incorpora y modifica normas contenidas en los artí
culos 46o,48o, 55o, 440°y 4 4 4 ° del Código Penal,yel artículoi35° del Código Procesal Penal.
De acuerdo a las incorporaciones efectuadas por la referida ley, será considerado reincidente
“quien después de haber cumplido en todo o en parte una condena privativa de libertad, incurre en nuevo
delito” (artículo 46-B del Código Penal), mientras que será considerado habitual quien “comete
un nuevo delito doloso, (...) siempre que se trate al menos de tres hechos punibles que se hayan perpetrado
en un lapso que no exceda de cinco años” (artículo 46-C del Código Penal). En ambos casos el juez
está facultado para aumentar la pena por encima del máximo legal fijado para el tipo penal
del nuevo delito doloso que configura la reincidencia o la habitualidad, según sea el caso.
