a. La re in c id e n c ia .- El reincidente es el que, después de haber cumplido en todo o en parte
una pena, incurre en nuevo delito doloso en un lapso que no excede de 05 años. Tiene
igual condición quien después de haber sido condenado por falta dolosa, incurre en nue
va falta o delito doloso en un lapso no mayor de tres años. El incremento de su pena pue
de ser hasta en una mitad por encima del máximo legal fijado para el tipo penal.
El plazo fijado para la reincidencia no es aplicable a los delitos previstos en los artículos
107°, 108o, io 8 °-A, 108°-B, 121°-A, 121°-B, 152°, 153°, 153°-A, 173°, 173°-A, 186°, 189o, 195°, 200°,
297o, 317°-A, 319o, 320°, 321°, 325o, 326o, 327o, 328o, 329o, 330o, 331°, 332°y 34 6° del Código Penal,
el cual se computa sin límite de tiempo. En estos casos, el juez aumenta la pena en no me
nos de 2/3 por encima del máximo legal fijado para el tipo penal, sin que sean aplicables
los beneficios penitenciarios de semilibertady liberación condicional.
