En lo s s u p u e s t o s d e r e in c id e n c ia n o se c o m p u t a n lo s a n t e c e d e n t e s p e n a le s c a n c e la d o s o
q u e d e b ie r e n s e r c a n c e la d o s , s a lv o e n lo s d e lit o s s e ñ a la d o s en el te rc e r p á rra fo d e l p r e s e n
te a rt íc u lo .
Según el Tribunal Constitucional en el fundamento 17 de la mencionada sentencia: “En
prim er término, la reincidencia constituye una circunstancia específica en que se halla una persona
a la que se le im puta la comisión de un delito y que abre espacio para la valoración desús conductas
anteriores, con miras a determ inar la graduación de las penas. (...) Así, la reincidencia es una situa
ción táctica consistente en la comisión de un delito en un momento en el cual el actor ha experimen
tado, previamente, una sanción por la comisión de uno anterior.” (Fj. 17). "Dependiendo de la opción
de política crim inal de cada Estado, la reincidencia puede considerarse existente en cualquiera de
estas dos situaciones: (1) cuando el im putado ha cumplido en su totalidad el tiempo de internam ien-
to en que consiste la pena que se le impuso, o (2) cuando se ha cumplido cierto plazo de la misma, el
cual es determinado por ley”.
En el f u n d a m e n t o 18 , el in t é r p r e t e d e la C o n s t it u c ió n s e ñ a la : “Si se consideran los alcances del
texto de la norma, se comprende que la reincidencia consiste en una calificación de la conducta de
lictiva, adicional a la calificación ya prevista por el tipo penal. Esto quiere decir que ante la presunta
realización de un delito, el juzgador evalúa, en un prim er momento, si la conducta puede subsumir
se en los elementos que conforman el tipo penal; si se produce dicha subsunción, la conducta es cali
ficada con el nomen iuris que corresponde al delito (primera calificación). En un segundo momento,
el juzgador evalúa nuevamente la conducta para establecer si califica o no como reincidencia, en
función a la existencia de antecedentes del im putado por cometer anteriormente el mismo delito
(segunda calificación). Una vez que se constata la comisión del delito y su carácter reincidente, se
produce la atribución de las sanciones: una sanción por la comisión per se del delito y la agravación
de dicha sanción como consecuencia de haberse identificado el carácter reincidente de la persona.”
