b, Habitualidad.- La habitual idad representa una situación más grave pues se trata de
aquel que se dedica a la actividad delictiva por lo que representa un mayor peligro, el
habitual tiene por lo menos tres delitos cometidos en un periodo que no supera los cinco
años. El plazo fijado no es aplicable para los delitos previstos en los artículos 107o, 108o,
108°-A, 108°-B, 121°-A, 121°-B, 152°, 153° 153°-A, 173, 173-A, 186°, 189o, 195°, 200°, 297°, 317°-A,
