En la s e n t e n c ia m e n c io n a d a , el T r ib u n a l C o n s t it u c io n a l s e ñ a la q u e : "En el derecho penal se entien
de la habitualidad como la comisión reiterada de delitos, usualmente los mismos. En su acepción legal, la
habitualidad implica la reiteración de más de tres delitos, en tiempos diversos e independientes unos de
otros.”
La habitualidad en el delito constituye circunstancia cualificada agravante. El juez aumenta la
pena hasta en 1/3 por encima del máximo legal fijado para el tipo penal, salvo en los delitos
previstos en los párrafos anteriores, en cuyo caso se aumenta la pena en una mitad por encima
del máximo legal fijado para el tipo penal, sin que sean aplicables los beneficios penitencia
rios desem ilibertady liberación condicional.
