UBILEX
3. ¿Cuáles son los principios de la aplicación y ejecución de la pena?
3.1. P rin cip io de le g a lid a d .
Conlleva a que se deban respetar los límites previos fijados por el legislador al momento
de imponer una pena concreta; así, el juez tiene parámetros de cuantificación de la pena
establecidos en la ley, los cuales deben ser acatados al momento de fijar la sanción que
corresponde a un hecho delictivo.
3.2. Prin cip io de c u lp a b ilid a d .
Establece que la penadebeserequivalentea la responsabilidad incurrida porel autordel
hecho delictivo (sea una conducta dolosa o culposa); importa una valoración del compor
tamiento humano llam ado''juicio de reproche1, que consiste en la valoración que se hace
cuando el individuo ha cometido un acto típico y antijurídico.
3.2. Prin cip io d e le siv id a d .
Este principio conlleva a que la pena fijada debe ser proporcional al daño causado, esta
bleciéndose, siempre, dentro de los lím itesy parámetros establecidos en la ley.
3.3. Prin cip io d e in h e re n cia .
Criterio que establece que el juez no puede, para efectos de determinación e imposición
de la pena, valorar nuevamente elementos ya considerados por el legislador en el tipo
penal.
3.4. Prin cip io de h u m a n id a d .
Principio que rige en el derecho penitenciario y establece la proscripción de cualquier tipo
de crueldad en la ejecución de la pena; se rechaza, así, toda sanción penal que resulte
brutal en sus consecuencias para el condenado.
4. Esquemas operativos para la determ inación de la pena
4 .1. S iste m a de tercios.
Se aplica a aquellos casos referidos a delitos o tipos penales simples que establecen una
conducta delictiva sin un catálogo especial de agravantes específicas; en este sistema la
pena prevista en la ley se divide en tres segmentos y, a partir de ello, operan las atenuantes
y/o agravantes genéricas establecidos en el artículo 45-A del referido código, para final
mente situarla en alguno de ellos..
4.2. S iste m a escalo n ad o .
Aplicable a los casos en que la ley establece un catálogo o listado de supuestos agravantes
de laconductaen diversos grados; conlleva a dividir el nuevo espacio de punibilidad entre
el número de agravantes específicas contempladas porel tipo penal; el resultado equiva
le a la duración de cada uno de los rangos o escalones m ínim oy el máximo legal.
