Tema 6: Temas de la Especialidad Penal
5. Operativización del sistema de tercios
P A S O 0
IDENTIFICACION DE LA PENA BÁSICA APRECIANDO LOS LÍMITES
INFERIOR Y SUPERIOR DE LA MISMA
Se establece un espacio o un marco punitivo que tiene un límite ]
o mínimo inicial y un máximo o limite final. |
Se establece la ubicación del tercio en el que se ha de fijar la
pena correspondiente al procesado evaluando la concurrencia
de las atenuantes y agravantes genéricas establecidas en la ley:
(art. 45-A del Código Penal).
El artículo 45-A del Código Penal establece las circunstancias atenuantes y agravantes genéri
cas que sirven para la determinación del tercio (inferior, medio o superior) dentro del cual se
ha de establecer la pena concreta.
Después de dividirse la pena prevista en la ley para un determinado delito en los tres espacios
(tercios), se establece la pena concreta aplicable al condenado evaluando la presencia, con
currencia o verificación de circunstancias agravantes o atenuantes observando las siguientes
reglas: a) si no hay atenuantes ni agravantes o solo se aprecian atenuantes, la pena concreta se
determina dentro del tercio inferior b) cuando concurran circunstancias genéricas de agrava
ción y de atenuación, la pena concreta se determina dentro del tercio intermedio; y, c) cuando
concurran únicamente circunstancias agravantes, la pena concreta se determina dentro del
tercio superior.
TERCIO INTERMEDIO TERCIO SUPERIOR
