6. Operativización del sistema escalonado
Se establece el tipo base (delito específico que es atribuido) y se avalúa, con-:
forme a la ley penal, si tal delito presenta agravantes específicas; de así, debe
determinarse la cantidad de agravantes y los grados de agravantes.
Después de establecer que el delito atribuido tiene agravantes específicas, el
marco mínimo y máximo de la pena, se divide en un número igual a las agra
vantes que han sido previstas en la ley, estableciéndose el valor de cada una
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 898 of 1506 --

UBILEX
Una vez establecidas las agravantes del delito y la cuantificación aritmética
de cada agravante, se procede a evaluar y determinar la cantidad de agravan
tes que le corresponden al hecho específico, siendo la surnatoria del espacio
que corresponde a las mismas el marco en el que se debe determinar la pena.
En muchos casos los delitos son descritos a partir de una conducta básica o inicial (lo que se
llama tipo penal básico)-como lo que ocurre en el delito de hurto (artículo 185odel Código Pe
nal) -y a ese supuesto se le agregan hipótesis de agravación con un rango penal más elevado,
algunas veces de varios grados, conforme a las circunstancias previstas en la ley, originándose
lo que en la practica legal se denomina el hurto agravado (artículo 186o del Código Penal).
El fundamento de este sistema escalonado se justifica en la premisa que sostiene que a mayor
número de circunstancias agravantes la posibilidad de alcanzar el extremo máximo de la pena
es mayor; caso contrario, la menor cantidad de circunstancias agravantes conducirá a que se
fije la pena en el mínimo legal o cercano a él.
