EJEMPLIFICACION:
Hecho
juan Córdova transitaba por inmediaciones de la cuadra 17 de la avenida jorge
Chávez, en el distrito de Independencia, una zona muy poco transitaday sin
iluminación, el 13 de marzo del 2024, a horas 9 3 0 de la noche; se percata en ese
momento de que, en sentido contrario, venía Rosa Hernández junto a su m enor;
hfja María de 12 años de edad, quien tenía en sus manos un teléfono celular con
el cual se comunicaba mediante video llamada con su padre; apreciando la vul
nerabilidad de la madre y su hija, sin pensarlo más, procedió asacar de su cin
tura un revólver que había adquirido en el sector conocido com o”La cachina" de
San Martín de Porras, y procedió a acercarse a ellas apuntándolas con el arma; a;
Rosa la despojó de su cartera, en la que se encontraban su teléfono celulary su
billetera con documentos personales y S/ 300.00; a la menor, la despojó del ce
lular que llevaba en sus manos. Inmediatamente de logrado su cometido, huyó
del lugar con dirección al distrito de Comas.
Inmediatamente Rosa Hernández acudió a la comisaría de Tahuantinsuyo a fin
de sentar la denuncia; en el lugar, un efectivo policial le sugirió verificar si algu
no de los teléfonos aún estaban encendidos e ingresó al aplicativo respectivo,
verificando que el teléfono que utilizaba la menor se encontraba funcionando y
arrojaba, mediante el sistema CPS, que su ubicación era el jirón Ramón Castilla
256, en el distrito de Los Olivos; a ese lugar llegaron agentes polícialesy la agra
viada, y, encontrándose el hecho en estado de flagrancia delictiva, procedieron
a allanar la vivienda, encontrando en su interior a Juan Córdova, quien preten-;
dió darse a la fuga por la pared vecina del inmueble. Se encontró, también, en;
una caja de cartón pequeña, el arma de fuego utilizada para perpetrar el robo,
así como los dos teléfonos celulares que fueron objeto del delito, escondidos
debajo de una cama, en una bolsa de plástico negra.
DATOS PARA LA DETERMINACIÓN DE LA PENA:
1. Delito: robo agravado. 2.Tipificación: artículos 188 (tipo base) y 189 (agravan
tes) del Código Penal. 3. Pena conminada: pena privativa de libertad no menor
de 12 ni mayor de 20 años. 4. Número de agravantes específicas previstas en
la ley: 9 (primer párrafo del artículo 189odel Código Penal). 5. Número de agra
vante aplicables al caso: 4.
