BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 901

-- 902 of 1506 --

UBILEX
9. REGLAS DE PRESCRIPCIÓN DE LA ACCIÓN PENAL Y DE LA PENA
Causas de extinción de la acción penal:
, a. Muerte del imputado: Principio de personalidad de las penas. Archiva la investigación o
provoca sobreseimiento.
b. Amnistía: derecho de gracia, olvido del delito, atribución del Poder Legislativo, produce
efectos de la cosa juzgada.
c. Cosa J u z g a d a : “ne bis ''m ídem”, está prohibido juzgar nuevamente a una persona por los
mishnos hechos,y no revivir procesos fenecidos.
d. Desistimiento: sólo procede respecto a la acción privada, en forma expresa o tácita.
e. Transacción: acción privada, deben hacerse concesiones recíprocas entre ambos.
f. Prescripción: es la institución jurídica mediante la cual, por el transcurso del tiempo, la
persona adquiere derechos o se libera de obligaciones85. Y, desde la óptica penal, es una
causa de extinción de la responsabilidad criminal fundada en la acción del tiempo sobre
los acontecimientos humanos o en la renuncia del Estado al iuspunendi, bajo el supuesto
de que el tiempo transcurrido borra los efectos de la infracción, existiendo apenas me
moria social de ella86.
La prescripción es una institución propia del Derecho Penal sustantivo. Así, en el Acuerdo
Plenario 8-2008/Q-116 F.J. 10 se menciona que: “La presencia de la prescripción en el ordenamiento
jurídico solamente puede explicarse de manera satisfactoria si se tiene en cuenta la función del Derecho
penal”,
Además, en cuanto al fundamento de la prescripción de la acción penal se afirma que éste
radica en “la falta de lesividad de tales hechos: los acontecimientos que ya forman parte del pasado no
ponen en peligro el modelo social vigente y, por tanto, carecen de contenido lesivo que justifique su san
ción"87. Asimismo, en el Acuerdo Plenario 1-2010/CJ-116, F.]. 31.B se indica lo siguiente: “Dicha
institución sustantiva está inspirada en el interés de la sociedad de que no haya delitos impunes, pero
limitando a los órganos encargados de la persecución penal".
De esta forma, su contenido y límites se describen en el Código Penal (arts. 8 o y ss)88. Por ello,
cualquier duda vinculada a la aplicación de dicha institución debe resolverse utilizando como
baremo la norma sustantiva.
85 La prescripción, "desde un punto de vista general, es la institución jurídica mediante la cual, por el transcurso del
tiempo, la persona adquiere derechos o se libera de obligaciones. Y, desde la óptica penal, es una causa de extinción de la
responsabilidad criminal fundada en la acción del tiempo sobre los acontecimientos humanos o la renuncia del Estado al
ius puniendi, en razón de que el tiempo transcurrido borra los efectos de la infracción, existiendo apenas memoria social
de la misma’’ (Exp. 1805-2005-HC/TC). Es decir, mediante la prescripción “se ¡imita la potestad punitiva del Estado,
dado que se extingue la posibilidad de investigar un hecho criminal y, con él, la responsabilidad del supuesto autor o
autores del mismo”(Exp. 2522-2005-HC/TC).
86 SAN MARTÍN CASTRO, César. Derecho Procesal Penal, Tomo 1,2 da edición, i era reimpresión, Editorial Crijley, Lima
2006, p. 393-
87 RAGUES Y VALLÉS, Ramón, La prescripción penal. Fundamentoy aplicación. Barcelona, 2004, p. 45-
88 El artículo 8o ° del Código Penal preceptúa que “La acción penal prescribe en un tiempo igual al máximo de la pena
fijadaporla ley para el delito, si es privativa de libertad”. Asim ism o,el artículo 83odel mismo cuerpo legal dispone
EE2 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 903 of 1506 --

Tema 6: Temas de la Especialidad Penal
Plazo ordinario de prescripción:
• Cadena perpetua: 30 años.
• Pena privativa de libertad: igual máxima de pena.
• Limitativas de derecho o pena pecuniaria: 2 años.
• Falta: 1 año.
Excepciones:
• Pena privativa de libertad mayor de 20 años: límite máximo 20 años.
• Delitos cometidos por funcionarios y servidores públicos contra el patrimonio del Es
tado o de organismos sostenidos por este, o cometidos como integrante de organiza
ciones criminales: se duplica el máximo de la pena prevista.
• Concurso real: prescriben en forma independiente.
• Concurso ideal: plazo igual al máximo correspondiente al delito más grave.
• Responsabilidad restringida: se reduce a la mitad.
Cómputo de los plazos:
• Tentativa: cesó la actividad delictiva.
• Delitos instantáneos: día en que se consumó el delito.
• Delitos continuados: día en que terminó la actividad delictuosa.
• Delitos permanentes: día en que cesó la permanencia.
Suspensión de la prescripción: (durante un plazoysesigue contando-inactividad del Estado
porque algo se lo impide)
Cuestión previa.
Cuestión prejudicial.
Antejuicio político.
Declaración de contumacia.
La suspensión de la prescripción no podrá prolongarse más allá de los plazos que se disponen
para las etapas del proceso penal u otros procedimientos. En ningún caso dicha suspensión
será mayor a un año.
Interrupción de la prescripción: (debido a la actividad del Estado, empieza a contar desde
cero).
Actos del Ministerio Público o del Juez.
Comisión de un nuevo delito.
Prescripción extraordinaria: máximo de la pena más la mitad.
que “La prescripción de la acción se interrumpe por las actuaciones del Ministerio Público o de las autoridades judiciales,
quedando sin efecto el tiempo transcurrido. (...) Sin embargo, la acción penal prescribe, en todo caso, cuando el tiempo
transcurrido sobrepasa en una mitad al plazo ordinario de prescripción”. Finalmente, e! artículo 8 2odel Código Penal
establece que el plazo de prescripción comienza “en el caso de delito instantáneo, a partir del día en que se consumó".
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 904 of 1506 --

UBILEX
Causa de extinción de la pena:
a. Muerte del imputado: responsabilidad civil se transmite.
b. Amnistía: olvido del delito, actos dejan de tener trascendencia penal.
c. indulto: derecho de gracia, perdón de la pena, corresponde al poder ejecutivo, funda
mento humanitario.
d. Prescripción: mismo que el de la prescripción de la acción. Se computa desde el día en
que la sentencia quedo firme. En la suspensión de la ejecución o reserva del fallo: desde
su revocación. Se interrumpe por el comienzo de ejecución de la pena o por la comisión de
un nuevo delito doloso. Concurso de personas: suspende o interrumpe separadamente.
e. Cosa juzgada: nadie puede recibirz sanciones porel mismo hecho, se advierte a través de
la demanda de revisión.
f. Perdón del ofendido: delitos de persecución por acción privada, debe otorgarse en forma
expresa y sin condiciones, es personal. Se ordena la anulación o cancelación de los ante
cedentes.
g. Exención de la pena: esta medida alternativa se relaciona con los criterios generales del
llamado perdón judicial. Esto es, con la facultad conferida por la ley al órgano jurisdiccio
nal para dispensar de toda sanción al autor de un hecho delictivo.
El fundamento de la exención de pena resulta de consideraciones de prevención especial y
de oportunidad o merecimiento de pena. De modo tal, que en atención a las circunstancias
del hecho punible, a las condiciones personales del autor o partícipe, o a la naturaleza de los
bienes jurídicos afectados, la respuesta punitiva aparece en el caso concreto como innecesaria
o desproporcionada.
En términos concretos la medida que analizamos puede definirse como una condena sin
pena. Ella implica, por tanto, una declaración de culpabilidad pero además una renuncia del
Estado, a través del Juez, a sancionar el delito cometido. En el derecho extranjero existe singu
lar predilección por los procedimientos de renuncia a la pena. En ese sentido, el artículo 169o
del Código Penal italiano autoriza al Juez a perdonar la pena, declarándola extinguida, si el
autor del delito es menor de dieciocho años y siempre que la pena que correspondería apli
carle no exceda a dos años de pena privativa de libertad. Por su parte, el Código Penal alemán,
en su artículo 60o, permite renunciar a la pena cuando la sanción a imponer es inferior a un
año de pena privativa de libertady las consecuencias del hecho ¡lícito han afectado de modo
relevante a su autor. Pero además el legislador germano exige que la decisión de dispensar
la sanción no produzca riesgos a la defensa del orden jurídico, vale decir, que ella no afecte
criterios de prevención general.
En cuanto a la denominación dada porel legislador nacional ella resulta equívocay poco afor
tunada, en la medida que con el término exención de pena se designan también en el Código
Penal supuestos diferentes a los que contempla el artículo 6 8 °. Ello ocurre, por ejemplo, en el
caso de los artículos 208o (exención de pena por vínculo fam iliar entre el autor con la víctima
de un delito contra el patrimonio) o 406o (exención de pena en caso de encubrimiento real o
personal). Algo similar resulta de las normas sobre derecho penal premial que contemplan el
Decreto Ley N° 25499 (Art. I o, II) y el Decreto Legislativo N° 824 (Art. 19o, a) que también con-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 905 of 1506 --

Tema 6: Temas de la Especialidad Penal
sideran una “exención de pena” para “los arrepentidos” involucrados en actos de terrorismo o
tráfico ilícito de drogas.
Por consiguiente, quizás hubiera sido preferible designar a éste sustitutivo penal con otra no
menclatura, como dispensa de pena o renuncia de pena, tal como ocurre en el derecho com
parado.
La legislación peruana establece dos requisitos para la procedencia de la exención de pena.
Uno, cualitativo, está en función del tipo de pena conminada en la ley para el delito cometido.
Y el otro, valorativo, toma en cuenta el grado de culpabilidad del autor o partícipe.
• El primer requisito señala que la medida es procedente si la pena prevista para el delito
cometido es privativa de libertad no mayor de dos años o se trata de pena de multa o de
pena lim itativa de derechos.
• El segundo requisito alude a que la culpabilidad del agente sea mínima. Este criterio no
ha sido desarrollado por el legislador.
Tampoco la doctrina y la jurisprudencia nacionales han estructurado sobre el particular cri
terios de interpretación uniforme. En tal sentido, cabe sostener de lege data algunas consi
deraciones al respecto. En principio, es de afirmar que la ley toma en cuenta la culpabilidad
concreta y personal del autor o partícipe, por lo que ella se mide en función de la presencia
de circunstancias que aminoren su intensidad como lo son la im putabilidad relativa, la con
currencia de un error de prohibición vencible o de un error de comprensión culturalmente
condicionado vencible, o la producción de un estado de necesidad exculpante imperfecto o de
un miedo que en el contexto aparezca como superable. Ahora bien, por extensión se asume
también la posibilidad de una menor culpabilidad en el caso del cómplice secundario.
Si bien el Código Penal a diferencia del precitado texto boliviano no alude a los efectos de la
exención de pena sobre la reparación civil, resulta fácil inferir que su concesión no excluye el
señalamiento de responsabilidades indemnizatorias, puesto que éstas son exigióles desde la
producción de un hecho antijurídico. Por tanto, el Juez debe fijar en la sentencia la reparación
civil que corresponda.
Por ultimo, es de señalar que la sentencia condenatoria donde se aplique la exención de pena
no debe ser inscrita en el Registro Judicial. La razón de ello deriva de la propia función que
corresponde a la inscripción, cual es dartestim onio de la pena impuesta al condenado89.
10. CONCURSO DE DELITOS
Se da cuando uno o varios autores, cometen una o varias conductas, que a su vez se encuadran
en varios tipos penales.
Clases de concursos:
a) Concurso ideal o formal: se presenta cuando una sola conducta configura dos o más de
litos (unidad de acción y pluralidad de delitos).
89 CUBAS VILLANU EVA, Víctor, Derecho procesal penal, estudio y práctica, 2da. Edición, ampliada, editorial Grijley,
Lima, 2006, p. 327.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 905

-- 906 of 1506 --

UBILEX
• Concurso ideal heterogéneo: una misma conducta que vulnera delitos que prote
gen diferentes bienes jurídicos. (Ejm: violación sexual con lesiones).
• Concurso ideal homogéneo: una misma conducta a que le es aplicable el mismo
tipo penal. (Ejm: muerte de varias personas por la explotación de una bomba).
b) Concurso real o material: Concurrencia de varias acciones o hechos, pero cada uno con
siderado como delito independiente (pluralidad de acción y pluralidad de delitos).
• Concurso real heterogéneo: autor comete varias veces la misma violación a la nor-
,ma penal (Ejm: el agente comete hurto un díaya l día siguiente robo).
• Concurso real homogéneo: el autor viola diversos tipos penales (Ejm: una personas
que estafa a varias personas en momentos diferentes).
c) Concurso real retrospectivo: Existe una sentencia condenatoria y posteriormente se
descubre que ha cometido otro hecho punible, antes de que se expida la resolución.
Posibilidades:
• El injusto penal, de acuerdo con la naturaleza de su comisión, merece una pena in
ferior a la ya impuesta. Dictará el archivamiento definitivo de la causa en giro. No
impide pago de reparación civil.
• El injusto merece una pena superior.
"CUARTO - Que esta Sala Penal Suprema considera necesario hacerlas siguientes precisiones:
^ a) Que el denominado concurso real retrospectivo contemplado en el artículo cincuentíuno del
l É p i Código Penal se produce cuando los delitos que componen el concurso han sido juzgados si-
W B B j f muftáneamente en un solo proceso. Esto es, el procesado ha sido autor de varios delitos, pero
inicialmente fue juzgado y condenado sólo por uno o algunos de los delitos cometidos. De allí
que al descubrirse con posterioridad a tal juzgamiento y condena los delitos restantes, ellos
darán lugar a un nuevo juzgamiento. Sin embargo, tal anomalía procesal no afecta la integri
dad del concurso real de delitos que cometió el agente. Por consiguiente conforme a lo señala José Hurtado
Pozo: para la imposición de la pena en el denominado concurso retrospectivo se debe tener en cuenta el
criterio de que no debe castigarse el agente más severamente que si se le hubiese juzgado simultáneamente
por todos los delitos cometidos (Cfr. Hurtado Pozo, José: "Manual de Derecho Penal - Parte General",
segunda edición, editorial Eddili, Lima, mil novecientos ochentisiete, página quinientos noventitrés), b) Que con :
la modificación incorporada del citado articulo cincuentiuno del Código Penal por la ley número veintiséis mil
ochocientos treintidós, s e estableció como excepciones a dicha consecuencia general. En primer lugar, si el
delito de juzgamiento posterior merece una pena inferior a la ya impuesta en el juzgamiento inicial, se debe
indicar el sobreseimiento definitivo y el archivo de la causa. En segundo lugar si la pena conminada para el
delito posteriormente descubierto fuese superior a laya aplicada se debe realizar nuevo juicio e imponerse la
nueva pena que corresponde al procesado, c) Que para la operatividad de las excepciones mencionadas se
debe efectuar una comparación entre la pena concreta impuesta en la primera sentencia y la penal legal con
minada para el delito recién descubierto pero cometido antes de la primera sentencia, d) Que por otro lado, es
de señalar que el texto vigente del articulo cincuentiuno tiene una finalidad práctica orientada por los principios
de economía procesal y eficacia judicial frente al gasto y desgaste funcional que representa todo nuevo pro-
cepo que al estar vinculado con un concurso real de delitos demanda una sanción coherente con lo prescrito
en el artículo cincuenta del Código Penal. QUINTO. - Q u e el derecho de la víctima a una reparación por daños y
perjuicios no se afecta con el sobreseimiento que autoriza el articulo cincuentiuno y que tiene una efectividad
estrictamente punitiva; por t a n t o t a l facultad de la víctima puede ejercerse en sede civil. SEXTO.- Que, en ese
contexto, es importante resaltarque en la ciudad de Arequipa, con fecha dieciséis de diciembre del año mil no
vecientos noventisiete, los Vocales Superiores integrantes de las Salas Penales de la República se reunieron en
sesión de la Sala Plena Jurisdiccional Nacional Penal con la finalidad de establecer criterios comunes para la :
aplicación de la norma penal, procesal penal y penitenciaria. Que entre los problemas jurisprudenciales some- ;
tidos a consideración del Pleno en aquella ocasión se encontraba la aplicación del concurso real retrospectivo,
llegando a los siguientes acuerdos plenarios con relación a éste tema: a) Para efectuar la comparación entre
la pena impuesta en la sentencia y el delito recién descubierto cometido antes de ella, debe estarse a la pena :
6 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 907 of 1506 --

Tema 6: Temas de la Especialidad Penal
conminada legalmente, sin perjuicio de t e n e r s e presente tos. supuestos de eximentes, b) El sobreseimiento pon
concurso real retrospectivo no impide a (aparte civil interponer una demanda en sede civil-c) En ehcaso que:
el delitorecién descubiertomereciera una pena igualada impuesta en la sentenciacondenatoria-no-puede so
breseerse el proceso; y d) La Ley que modificó el artículo cincuentiuno del Código Penal no es inconstitucional,
ya que no afecta el principio del debido proceso, el derecho a la tutela jurisdiccional, el derecho a la presunción
de inocencia, ni el derecho a la igualdad de la ley. Segunda Sala Penal Transitoria de la Corte Suprema de Justicia.
Recurso de Nulidad N° 367-2004-Santa.
d) Concurso aparente de leyes: Sobre el hecho punible concurren diversos preceptos pena
les excluyentes entre síy donde sólo uno de ellos debe ser aplicado.
Principios:
i. Principio de especialidad: si el mismo hecho está tipificado por dos o más disposi
ciones normativas se aplicará la especial sobre la genérica (tipos básicos y califica
dos).
ii. Principio de consunción: hecho previsto porunadisposlción normativa se compren
de en otra de mayor vastedad.
• El delito consumado excluye al frustrado y a la tentativa.
• El autor consume al cómplice y el cómplice al encubridor, si ambas calidades
concurren en la misma persona.
• El más grave consume al más leve.
• Los delitos compuestos o complejos consumen a los delitos que los conforman.
• Actos anteriores y posteriores son consumidos por el principal.
iii. Principio de subsidiaridad: ley prescribe que se aplicará ésta, siempre que no se
aplique la figura principal.
iv. Principio de alternatividad: dos disposiciones normativas se comportan como se
cantes, se debe elegir el de la pena más grave o el del bien jurídico más importante.
Figuras afines al concurso de leyes:
a. Delito continuado: Se configura cuando hay varias violaciones de la misma ley penal o
una de igual o semejante naturaleza, si éstos hubieran sido cometidos en el momento de
la acción o en momentos diversos con actos de la misma resolución criminal y se sancio
naran con la pena correspondiente al más grave.
Si con dichas violaciones, el agente hubiera perjudicado a una pluralidad de personas
la pena será aumentada en un tercio de la máxima prevista para el delito más grave. Por
ejemplo-. Si para llegar a su meta $2000 Juan hurta, receptay se apropia ¡lícitamente de los
bienes de María realiza un delito continuado porque, todos estos delitos son de la misma
naturaleza, es decir, son contra el patrimonio.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 908 of 1506 --

UBILEX
"El artículo 49 del Código Penal establece que cuando varias violaciones de la misma ley penal o
una de igual o semejante naturaleza sean cometidas en el momento de la acción o en momentos
diversos, mediante actos ejecutivos de la misma resolución criminal, estas serán consideradas
como un solo delito continuado y se sancionarán con la pena correspondiente al m á s grave".
Tribunal Constitucional. Exp. N° 02348-20 W-PHC/TC- Lima. Fj. 9 . 10/12/2010.
b. Delito masa: El delito masa es aquel donde el autor realiza una pluralidad de conductas,
pero del mismo delito que afectan un gran número de personas. Es una forma de delito
continuado, donde hay pluralidad de conductas del mismo delito que afecta a una plu
ralidad de agraviados. Nuestro Código Penal prevé en el artículo 4 9 °, que en el caso del
delito masa, la pena será aumentada en un tercio del máximo de la pena prevista para el
delito más grave.
"De modo qup el delito masa viene a ser una circunstancia agravante específica del delito continua
do. Se basa en la pluralidad de personas perjudicadas por el delito continuado que ejecuta el agente.
En este caso, la pena será aumentada en un tercio de la máxima prevista para el delito más grave". V
Pleno Jurisdiccional de las Salas Penales Permanente y Transitorias. Acuerdo Ptenario N° 8-2008/CJ-116,
Elementos:
• La realización de un delito continuados; y,
• Pluralidad de personas perjudicadas porel delito.
11. SUSPENSIÓN DE LA EJECUCIÓN DE LA PENA
11.1. Suspensión de la ejecución de la pena:
Consiste genéricamente en la suspensión del cumplim iento de la condena (sursis) durante un
cierto período en el que se establece determinadas condiciones que si son cumplidas permi
ten declarar extinguida la responsabilidad. Se trata de la condena condicional o pena condi
cionalmente suspendida.
Responde este instituto político - criminal a criterios del Derecho Humanitario que propicia
darle al infractor una oportunidad de probar para el futuro su respeto al orden jurídico-siste
ma de sometimiento a prueba-.
Existen diversas razones para evitar la aplicación de las penas privativas de libertad de corta
duración. Ellas desocializan antes que favorecer la resocialización del presidiario. Además, las
penas cortas de prisión se prevén para delitos poco graves, para los cuales bastarían penas
menos traumáticas.
El Código Penal de 1924 introdujo en su artículo 53o la llamada condena condicional, adoptan
do el sistema franco-belga (exposición de motivos). “El sistema franco-belga del sursis supone el
pronunciamiento de la pena pero con suspensión de su cumplimiento durante un determinado periodo de
prueba, sin necesidad de sometimiento a ciertos deberes ni control.”90
90 Ibidem, p. 3 9 0 .
8 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 909 of 1506 --

Tema 6: Temas de la Especialidad Penal
En verdad, nos parece acertada la decisión del legislador de reemplazar la denominación "con
dena condicional” por la de “suspensión de la ejecución de la pena”, pues en verdad lo que se
suspende no es la condena sino el cumplim iento de la pena impuesta.
Requisitos: El artículo 57° del C.R establece dos clases de presupuestos para que el juez decida
suspender la ejecución de la pena:
a) Presupuestos objetivos: que la condena se refiera a pena privativa de libertad no mayor
de 05 años. En caso de concurso de delitos, poco importa que cualquiera de las penas no
excedan el límite señalado y habrá que computaren función a la pena más grave.
b) Presupuestos subjetivos: que la naturaleza, modalidad del hecho punible, comporta
miento procesal y la personalidad del agente, permitan inferir al juez que aquel no volve
rá a cometer un nuevo delito. El pronóstico favorable sobre la conducta futura del conde
nado que formule la autoridad judicial requiere de debida motivación.
Que el agente no tenga la condición de reincidente o habitual.
Excepcionalmente, puede aplicarse lo establecido en el presente artículo cuando la condena
se refiera a pena privativa de libertad no mayor de ocho años y el autor o partícipe del delito
carezca de antecedentes penales y sea menor de 25 años al momento de cometer el delito.
Para este supuesto es aplicable lo previsto en el numeral 2 del párrafo anterior, exigiéndose
una motivación reforzada.
Plazo de suspensión: El período de suspensión de la ejecución de la pena es de 01 a 04 años.
Este plazo de suspensión debe ser fijado según la naturaleza del delito, personalidad del
agentey otras circunstancias.
Cuando la condena se refiera a pena privativa de libertad no mayor de ocho años y el autor o
partícipe del delito carezca de antecedentes penales y sea menor de 25 años al momento de
cometer el delito, el plazo de suspensión puede extenderse hasta 07 años.
11.2. Conversión de penas:
Entendida como la institución que se realiza de una por otra. Desde esta perspectiva algunos
autores nacionales la han denominado como conmutación de penas.
El campo de aplicación de esta institución penal tiene como característica central el ser resi
dual, pues al no poder el juez aplicar la suspensión de la ejecución de pena, ni la reserva de
fallo condenatorio, entonces de acuerdo con el artículo 52o del Código Penal, el juez podrá
convertir la pena privativa de libertad.
No mayor de dos años a pena de multa, o la pena privativa de libertad no mayor de cinco años en
otra de prestación de servicios a la comunidad, o limitación de días libres, a razón de un día de
privación de libertad por un día de multa, siete días de privación de libertad por una jornada de
prestación deservicios a la comunidad o por una jornada de limitación de días libres.
El juez también podrá convertirla pena privativa de libertad no menorde cuatro años ni mayora
diez años por expulsión inmediata del país conforme lo establecido en el artículo 30 del Código
Penal, siempre que haya cumplido los dos tercios de la condena.
Igualmente, el juez podrá, de oficio o a petición de parte, convertir la pena privativa de libertad
en pena de vigilancia electrónica personal, a razón de un día de privación de libertad por un día
