de vigilancia electrónica personal, en concordancia con el inciso 3 del artículo Z9°-A del Código
Penal.
Sin embargo, la aplicación de la conversión es reversible, pues si no se cumple injustificadamente
con las equivalencias antes referidas, entonces en un primer momento se la apercibirá judicial
mente, si el incumplimiento perdura se revocará la conversión (revocación por incumplimiento
de pena convertida) (artículo53° del Código Penal).
Dicha revocación implica la inmediata ejecución de la pena privativa de libertad fijada en la sen
tencia penal.
Cabe distinguir otro supuesto especial de revocación de pena convertida constituido por la co
misión de un delito doloso por parte del condenado, siemprey cuando el delito cometido tenga
como pena conminada la privativa de libertad no mayor de tres años. La revocación automática
se señalará en la condenada por el nuevo delito cometido.
La pena que cumplirá el condenado será considerando la primera condena, la privativa de li
bertad, descontando lo cumplido de acuerdo a las equivalencias señaladas en el artículo 53°
del Código Penal, es decir de las penas convertidas y considerando, la segunda condena, ésta se
cumplirá luego de agotada la primera condena.
En los artículos 55° y 56° del Código Penal, se precisa las reglas de conversión de las penas de
prestación de servicios a la comunidad y limitación de días libres; y la pena de multa respecti
vamente.
11.3. Reglas de conducta (artículos 58° y 59° del Código Penal):
El Juez al otorgar la sursis impondrá medidas de conducta:
i. Prohibición de frecuentar determinados lugares;
ii. Prohibición de frecuentar determinados lugares;
iii. Prohibición de ausentarse del lugar donde reside sin autorización del juez;
iv. Comparecer mensualmente al juzgado, personal y obligatoriamente, para inform ary jus
tificar sus actividades;
v. Reparar los daños ocasionados por el delito o cumplir con su pago fraccionado, salvo
cuando demuestre que está en imposibilidad de hacerlo;
vi. Prohibición de poseer objetos susceptibles de facilitar la realización de otro delito;
vi i. Obligación de someterse a un tratamiento de desintoxicación de drogas o alcohol;
viii. Obligación de seguir tratamiento o programas laborales o educativos, organizados por la
autoridad de ejecución penal o institución competente.
Otros deberes que el Juez podría señalar serían porejemplo: indicaral sentenciado lafrecuen-
cia de cursos de habilitación profesional, tratamientos de desintoxicación o deshabituación
u otros que no atenten contra su dignidad. No obstante, es necesario recalcar que el Juez no
puede imponer al condenado deber inexigible o de dudosa constitucionalidad (como visitar
periódicamente la Iglesia, afiliarse a determinadas asociaciones, etc.).
El incumplimiento de las reglas indicadas en el artículo 58o del Código Penal, o la condena por
otro delito puede originar:
