Tema 6: Temas de la Especialidad Penal
i. Amonestación al infractor;
ii. Prórroga del periodo de suspensión; o
iii. La revocación de la suspensión de la pena.
Todas las medidas a adoptar por el incumplimiento de las reglas de conducta o la condena
de otro delito, son entregadas a la discrecional idad del juez. De este modo, la práctica de otra
infracción penal durante el período de prueba no revoca necesariamente laswrs/s, siendo ne
cesaria una sentencia condenatoria.
Aquí está prevista la revocación facultativa diferente al supuesto de revocación obligatoria
prevista en el artículo 6 o°del Código Penal, pues en lugar de la revocación es posible disponer
la prórroga del periodo de prueba. La leyseñalaun límite hasta la mitad del plazo inicialmen
te fijado, sin que la prórroga acumulada exceda de tres años.
En cuanto a la amonestación: Esta medida aplicable a las infracciones menores de las reglas
de conducta o infracciones penales menores (delito con pena menor a tres años) supone re
prender o amonestar al infractory puede ser pública (audiencia admonitoria) y privada, situa
ción que no ha sido precisada por el Código Penal de 1991. La respuesta está condicionada a la
orientación preventiva general o especial que fundamentaría laswrs/s.
11.4. Revocación de la suspensión de la pena (artículo 60° del Código Penal):
La suspensión de la pena será revocada si, durante el plazo de prueba, el agente es conde
nado por la comisión de un nuevo delito doloso, cuya pena privativa de libertad sea superior
a tres años. Poco interesa el cuantum de la pena que se aplicó o la fecha de la comisión de la
infracción (anterioro posterioral que originó laswrs/s) o si fue realizado durante el periodo de
prueba.
En este caso, se ejecutará la pena suspendida y la que corresponda por la segunda infrac
ción.
11.5. Cumplimiento de las condiciones (artículo 6 1 0 del Código Penal):
Expirado el período de prueba sin que el condenado infrinja reglas de conducta de manera
persistente y obstinada o, sin que cometa nuevo delito doloso, la condena se considera como
no pronunciada.
Esto supone la extinción de la pena aplicada. El juez deberá declarar la extinción pero, en todo
caso, si no lo hace, la pena será igualmente extinta, pues “esa extinción no depende del despacho
judicial”.
Extinta la pena, el conocimiento posteriorde un delito doloso o de otra razón que haga pensar
que laswrs/s no le correspondía al sujeto, no puede originar la revocación de la suspensión.
11.6. La reserva del fallo condenatorio (artículo 62° del Código Penal):
Consiste en una alternativa a la pena privativa de libertad de corta duración lo mismo que a las
de m ultay limitativas de Derecho.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 912 of 1506 --

UBILEX
La reserva se diferencia de la suspensión de la ejecución de la pena por la no pronunciación
del fallo que produce como consecuencia la no existencia de antecedentes penales. El juez
deberá elegir entre las dos, cuál es la más conveniente al caso juzgado, utilizando los mismos
criterios preventivos que en la suspensión de la ejecución de la pena (artículo 57°, ¡nc. z del
Código Penal).
El plazo de la reserva será de uno a tres años desde que la decisión adquiere la categoría de
cosa juzgada, atendiendo a criterios preventivos como la personalidad del sujeto, las circuns
tancias del hechoy duración de la pena a imponer o impuesta, a condición de que con la apli
cación de esta medida no se cometa un nuevo delito. Se relaciona con el principio de preven
ción establecido en el artículo I del Título Preliminar del Código Penal. En caso de la excepción
incorporada por el Decreto Legislativo N°i585, Decreto Legislativo que establece mecanismos
para el deshacinamiento de los establecimientos penitenciarios, el plazo de suspensión puede
extenderse hasta seis (6) años.
Con respecto de los tipos de penas en que se dispondrá la reserva, ésta surgirá como sustituto
de la pena privativa de libertad, pero en la actualidad la sentencia es abarcar a los otros tipos
de penas. En este sentido nuestro Código dispone la reserva en los siguientes casos:
a. Cuando el delito está sancionado con pena privativa de libertad no mayor de 04 años o
con multa;
b. Cuando la pena a imponerse no supere las 90 jornadas de prestación de servicios a la
comunidad o de limitación de días libres;
c. Cuando la pena a imponerse no supere los 02 años de inhabilitación.
El Decreto Legislativo N ° i585 incorporó que excepcionalmente, puede aplicarse lo establecido
en el artículo cuando la condena se refiera a pena privativa de libertad no mayor de siete años
y el autor o partícipe del delito carezca de antecedentes penales y sea menor de 25 años al
momento de cometer el delito.
Para este supuesto es aplicable lo previsto en el primer párrafo, exigiéndose una motivación
reforzada. El Código sólo se refiere a las penas privativas de libertad, de multa, prestación de
servicios a la comunidad o limitativas de días libres, pero no de las penas restrictivas de liber
tad, por lo que no habrá reserva del fallo en ningún caso respecto de estas últimas.
Efectos de la reserva del fallo condenatorio:
• Resolución del fallo condenatorio: Toda sentencia está compuesta de tres partes: exposi
tiva, que contiene el relato de los hechos; la considerativa, donde el juez hace una aprecia
ción de la prueba actuada, valorándolay declarando la responsabilidad del sujeto; y la par
te resolutiva, que contiene la decisión del tribunal, fijando la pena o medida de seguridad
a imponer, así como las responsabilidades civiles.
En la reserva del fallo ("pw bation”) el juez sólo se abstiene de dictar la parte resolutiva,
pero se consideran tanto la parte expositiva como la considerativa en donde se declara
la responsabilidad del agente. Creemos que lo señalado no implica no resolver, sino so
lamente no fijar la pena. En este sentido, es recomendable que se resuelva suspender el
fallo abriendo un periodo de prueba en la que se establecen las reglas de conducta que
