Terra 6: Temas de la Especialidad Penal
el sujeto tendrá que cumplir. Del mismo modo, se establecerán las consecuencias civiles
derivadas del delito.
En la reserva del fallo, a diferencia de la suspensión de la ejecución de la pena, lo que se
suspende es la determinación de la pena y no su cumplimiento, en la que sí existe pena.
• Registro Judicial: Su finalidad no es otra que la de proporcionar información acerca de
condenas a penasy a medidas, para la rehabilitación del sujeto, a través de un certificado
de conducta llamado certificado de antecedentes penales.
Debido al obstáculo que ofrecen al sujeto los antecedentes penales para su normal des
envolvimiento social, el legislador ha optado por suspender su inscripción en el Registro
judicial, sólo para el caso de la reserva del fallo condenatorio, lo que nos parece positivo.
Reglas de conducta: El artículo 64o del Código Penal establece que al disponer la reserva del
fallo, se impondrán reglas de conducta que conformará el periodo de prueba. Estas reglas son
las mismas que las indicadas para la suspensión de la ejecución de la penay tienen un carácter
preventivo especial, es decir, educadory reintegrador.
Al pareceres favorable que no se establezcan obligaciones en forma genérica que pueden su
poner para el sometido a ellas, un control y una molestia adicionales que le dificulte en su
normal desenvolvimiento o libertad. En este sentido, las reglas no pueden imponer al sujeto
cargas inexigibles.
Las reglas señaladas en nuestro código son las siguientes:
• Prohibición de frecuentar determinados lugares.- Referido a determinados lugares que
pueden ser considerados como ambientes nocivos, con la finalidad de evitar la comisión
de un nuevo delito. Por ejemplo: bares, casas de juego, prostíbulos, etc.
• Prohibición de ausentarse del lugar donde reside sin autorización del Juez.- Tiene
como finalidad hacer efectivas las reglas de conducta impuestas y que puedan ser con
troladas.
• Comparecer mensualmente al juzgado, personal y obligatoriamente, para informar y
ju stifica r sus actividades.- Esta medida permite al juez que conoce del caso, fiscalizary
orientar al agente de modo que no haga innecesaria esta institución.
• Reparar los daños ocasionados por el delito, salvo que demuestre que esté imposibi
litado de hacerlo.- Esta se refiere a la reparación que debe hacerel sujeto hasta donde le
sea posible. Dicha regla refuerza el deber de indemnizar los daños que impone el Dere
cho Civil.
• Que el agente no tenga en su poder objetos susceptibles de facilitar la realización de
otro delito.-Con lafinalidadde prevenir nuevos delitos, el juez puede prior la tenencia de
armas o de cualquier otro objeto que pudiera servirle de ocasión o estímulo para cometer
nuevos delitos.
• Obligación de someterse a un tratamiento de desintoxicación de drogas o alcohol.
• Obligación de seguir tratamiento o programas laborales o educativos, organizados
por la autoridad de ejecución penal o institución competente.
