Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 914 of 1506 --

• Obligación de someterse a un tratamiento psicológico o psiquiátrico.
• Las demás reglas de conducta que el Juez estime convenientes para la rehabilitación
social de agente, siempre que no atenten contra la dignidad del condenado.- Aquí se
consideran todas las demás reglas que no se encuentren indicadas expresamente, pero
que el Juez la tome como necesarias siguiendo los criterios preventivos que mantiene
este Código.
Incumplimiento de las reglas de conducta: Cuando el agente incumpliere las reglas de con
ducta impuestas, por razones atribulóles a su responsabilidad, el Juez podrá:
a. Hacerle una severa advertencia;
b. Prorrogar el régimen de prueba sin exceder la mitad del plazo inicialmente fijado. En nin
gún caso la prórroga acumulada sobrepasará de tres años; o,
c. Revocar el régimen de prueba.
Cumplimiento del plazo: El artículo 67o del Código Penal establece que si expirara el plazo
del periodo de prueba sin la concurrencia de cualquier motivo de revocación, se declarará ex
tinguido este periodo, así como no efectuado el juzgamiento. Esta extinción no depende del
despacho judicial.
^ "QUINTO.- Que con relación a la aplicación de la reserva del fallo condenatorio regulada en los
j O m artículos sesentidós a sesentlsiete del Código Penal, es importante precisar, a) Que ésta es una
~ | d U g r medida alternativa a la pena privativa de libertad de uso facultativo para el Juez, que se carac-
| teríza fundamentalmente por reservar la imposición de la condena y el señalamiento de la pena
iSBBBH, concreta para el sentenciado culpable; b) Que en consecuencia, tal medida consiste en declarar
en la sentencia la culpabilidad del procesado, pero sin emitir la consiguiente condena y pena.
Estos últimos extremos se reservan y se condiciona su extinción o pronunciamiento a la culminación exitosa
o no de un periodo de prueba, dentro del cual el sentenciado deberá abstenerse de cometer nuevo delito y
cumplir las reglas de conducta que le señale el Juez; c) Que la reserva del fallo condenatorio procede cuando
concurren estos presupuestos: i) Que el delito es te sancionado con pena conminada no superior a tres años de
pena privativa de libertad o con multa; o con prestación de servicios a la comunidad o limitación de días libres
que no excedan a noventa jornadas semanales; o con inhabilitación no superior a dos años; ii) Que el Juez, en
atención a las circunstancias del hecho y a la personalidad del agente, emita un pronóstico favorable sobre la
conducta futura del imputado; iii) Es de señalar que la reserva del fallo condenatorio también es aplicable en
caso de penas conjuntas o alternativas, siempre que tales sanciones se adecúen a los marcos cualitativos y
cuantitativos antes mencionados. SEXTO. - Que la reserva del fallo condenatorio no genera antecedente pe
nal, pero su aplicación debe inscribirse en el registro respectivo. SÉPTIMO - Que se advierte de autos que la
Sala Superior Penal, ha aplicado indebidamente la reserva del fallo condenatorio por lo que debe precisarse
al respecto lo siguiente: a) Que según lo dispuesto por el artículo cuatrocientos veintiséis del Código Penal,
los delitos previstos en los capítulos segundo y tercero del título decimoctavo, serán sancionados, además
con pena de inhabilitación; b) Que la inhabilitación que corresponde a los casos del artículo precitado, tiene la
calidad de pena principal y conjunta, con un máximo de duración de tres años y con los alcances contenidos
en el artículo treintiséis, inciso uno y dos; c) Que, como ya se ha señalado, la reserva del fallo condenatorio
resulta aplicable solo cuando la pena conminada a imponerse no supere los dos años de inhabilitación; d)
Que, por consiguiente, para el caso en examen la pena conminada de inhabilitación, principal y conjunta, tiene
un máximo de duración de tres años, por lo que la aplicación de la reserva del fallo condenatorio hecha por
el Colegiado Superior es improcedente." Segunda Sala Penal Transitoria de la Corte Suprema de Justicia. Recurso de
Nulidad N° 3332-2004-Junín.
