Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 915 of 1506 --

Tema 6: Temas de la Especialidad Penal
] . DELITOS CONTRA LA HUMANIDAD
1.1. Descripción normativa
Genocidio (Art. 319 CP)
Será reprimido con pena privativa de libertad no menor de veinte años el que, con la intención de
destruir, total o parcialmente, a un grupo nacionalétnico, social o religioso, realiza cualquiera de los
actos siguientes:
1. Matanza de miembros del grupo.
2. Lesión grave a la integridad física o mental a los miembros del grupo.
3. Sometimiento del grupo a condiciones de existencia que hayan de acarrear su destrucción física de manera
total o parcial.
4: Medidas destinadas a im pedirlosnacim ientos en el sen o del grupo;
5. Transferencia forzada de niños a otro grupo.
1.2. Concepto del delito de genocidio
La Convención para la Prevención y la Sanción del Delito de Genocidio no otorga definiciones
generales, pero introduce un concepto casuístico de enumeración taxativa estableciendo en
su artículo II, descriptivamente, los actos que son considerados como delito de genocidio, a
saben i. Matanza de miembros del grupo; 2. Lesión grave a la integridad física o mental de los
miembros del grupo; 3. Sometimiento intencional del grupo o condiciones de existencia, que
hayan de acarrear su destrucción física, total o parcial; 4 - Medidas destinadas a impedir los
nacimientos en el seno del grupo; 5 - Traslado por fuerza de niños del grupo a otro grupo; en
consecuencia, fuera de ello, no cabe hablar de delito de genocidio.
1.3. Bien jurídico protegido
La protección jurídico penal en el delito de genocidio está orientada a garantizar la supervi
vencia y desarrollo del grupo humano, protegiendo la vida y la integridad psicofísica de los
individuos que lo conforman; respecto a la figura de “traslado de niños”, como genocidio cul
tural que representa conforme a la Convención para la Prevención y la Sanción del Delito de
Genocidio, la protección legal se orienta a preservar la identidad y caracteres específicos del
grupo humano, evitando que los menores sean llevados a otros grupos, con la intención de
forjarles una nueva cultura, haciéndoles perder su contacto cultural con el grupo humano del
cual son originarios.
1.4. Sujeto activo
El artículo IV de la Convención para la Prevención y la Sanción del Delito de Genocidio sobre
genocidio, determina a los responsables de esta modalidad delictiva; en primer lugar estable
ce un sujeto activo genérico, que puede serlo cualquier persona: gobernantes, funcionarios o
simples particulares; sin embargo, las normas punitivas de la Convención sobre genocidio, es
tán dirigidas exclusivamente sobre las personas físicas, no estableciéndose ninguna m odali
dad represiva contra las personas jurídicas, sean estas corporaciones, asociaciones o el mismo
Estado, conforme al carácter personalísimo del Derecho penal.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN I
Y NOMBRAMIENTO DE JUECES Y FISCALES

