UBILEX
1 . 5 . S u j e t o p a s iv o
En tiempos actuales, como resultado del desarrollo de las relaciones internacionales y del es
píritu de solidaridad humana que las inspira, se ha ido formando una tendencia que consi
dera al individuo, sin considerar como perteneciente a un determinado país, como sujeto de
Derecho internacional, para los efectos de la protección de sus Derechos Humanos, por lo que
se han aprobado normas punitivas orientadas a la protección del hombre, situándolo como
sujeto pasivo de tales conductas y brindándoles su protección.
Respecto a lo que el artículo II de la Convención para la Prevención y la Sanción del Delito de
Genocidio, considera como “grupo humano” que sufre la acción genocida, debe entenderse
como agrupación humana de índole estructural, que presenta aspectos o características muy
variadas íntimamente concretadas, todas las cuales y no una sola, dan personalidady especi
ficidad al grupo de que se trate, tomando en cuenta todas sus características y no solamente
algunas de estas, una a una, y edificar con ellas grupos que, en verdad, no pueden ser caracte
rizados en esta forma. Finalmente, se entender como grupo a una agrupación nacional, étnica,
racial o religiosa, apreciable en cantidad.
Atendiendo a que el genocidio debe estar dirigido hacia la destrucción total o parcial de un
grupo humano como tal y considerando que los grupos se componen de individuos, llegamos
a concluir que, en últim o análisis, la acción destructiva debe estar dirigida contra los indivi
duos, quienes se constituyen en los destinatarios de la protección penal; en consecuencia, el
sujeto pasivo en el delito de genocidio lo será toda persona que sea miembro de un grupo
nacional, étnico, racial o religioso. El individuo es protegido aquí, no en relación así mismo,
sino en relación a su pertenencia a determinado grupo.
1.6. Modalidades de genocidio
a. H o m icid io de m ie m b ro s del grup o
La descripción de la conducta típica de esta modalidad delictiva la encontramos en el
inciso i del artículo 319o del Código Penal, concordante con el artículo II, inciso a) de la
Convención, que exponed siguiente texto: "m atanza de miembros del grupo”.
Se protege en esta modalidad la vida humana desde su inicio hasta su fin; se tutela el bien
jurídico vida humana, pero en relación a la pertenencia del individuo a un determinado
grupo humano.
Esta forma delictiva establece un sujeto activo genérico, puede serlo cualquier persona:
gobernantes, funcionarios o particulares; el sujeto pasivo sí es específico, ya que se prote
ge al individuo, pero en relación a su pertenencia a un grupo humano específico sobre el
cual el agente orienta su acción homicida.
Se trata de una modalidad delictiva eminentemente dolosa, impregnada de un caracte
rístico sello subjetivo, que es la intención del agente, de dar muerte a uno o más integran
tes de un grupo humano por su pertenencia a tal.
El tipo admite solo el dolo directo, se descarta por tanto el dolo eventual y las formas ne
gligentes.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 917 of 1506 --

Tema 6: Temas de la Especialidad Penal
b. Lesiones graves a miembros del grupo
El inciso 2 del artículo 319 del Código Penal y el artículo II, inciso b) de la Convención, estable
cen como genocidio la “lesión grave a la integridad física o mental de los miembros del grupo”.
El bien jurídico q ue se protege es tanto la integridad corporal como el equilibrio de la salud
de las personas, entendiendo como tal, la salud física y la salud mental.
El sujeto activo en este tipo genocida puede serlo cualquier persona, sea gobernante, fun
cionario o particular; sujeto pasivo solo pueden serlo las personas pertenecientes a un
determinado grupo humano, sobre el cual actúa el agente con la intención de destruirlo
total o parcialmente.
La intención del agente, en esta figura delictiva, es la de producir en los individuos perte
necientes al grupo humano, lesiones de naturaleza grave, que viabilicen la consecución
de su finalidad; es decir, la destrucción del grupo como tal.
Este tipo delictivo se consuma en el momento en que el agente, imbuido de la intención
de destruirtotal o parcialmente al grupo humano, ocasiona a sus integrantes un daño en
su integridad corporal o en su salud psicofísica, en el sentido del artículo 121 de nuestro
Código Penal.
El agente quiere la destrucción del grupo humano, para lo cual ocasiona lesiones graves
a sus integrantes, como un medio intim idatorio conducente a conseguir su finalidad. El
agente actúa solo en animus vulnerandi nunca quiere la muerte, y si ésta se produce, tal
resultado deviene preterintencional. Como vemos, la actitud del actor es netamente in
tencional, actúa con evidente dolo directo.
c. S o m e tim ie n to del grup o a co n d icio n e s d e v id a te n d ie n te s a su d estru cció n .
El inciso 3 del artículo 319o del Código Penal, así como el artículo II, inciso c) de la Conven
ción establecen como conducta genocida el “sometimiento intencional, del grupo a condicio
nes de existencia que hayan de acarrear su destrucción física, total o parcial”.
La protección penal está orientada a la preservación tanto de la vida como la integridad
corporal y la salud psico-física de los miembros del grupo; el sujeto activo puede ser cual
quier persona, sea gobernante, funcionario o particular; sujeto pasivo solo pueden serlo
los integrantes del grupo humano sobre el cual ejerce su acción el agente.
En este caso se requiere de una m ultiplicidad de víctimas, ya que el tipo legal se refiere al
grupo como objeto material de la acción. La esencia del tipo legal en estudio, es el peligro
al cual se expone a un determinado grupo humano, sometiéndolo a condiciones nocivas
de vida, con la intención de destruirlo total o parcialmente; o sea que para la consuma
ción de este delito solo se requiere la existencia efectiva del incremento injustificado del
riesgo, loque lo determina como un tipo de consumación instantánea.
El tipo es netamente doloso, la intención del agente está dirigida a la desaparición física
(total o parcial) del grupo humano, sometiéndolo a determinadas y nocivas condiciones
de vida que podrían producirtal fin. Solo admite el dolo directo.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 918 of 1506 --

UBILEX
d. Impedimento de nacimientos
El inciso 4 del artículo 319o del Código Penal y el artículo II, inciso d) de la Convención,
establecen como conducta punible las “medidas destinadas a im pedirlos nacimientos en el
seno del grupo".
La intención del agente es la de impedir la renovación natural del grupo humano, evitan
do tanto la procreación, como el nacimientos de nuevas generaciones; en consecuencia,
se aprecia una diversidad de bienes jurídicos protegidos: en el primer caso donde la ac
ción del autorse dirige a evitar la procreación, podemos encontrar la lesión al bien jurídi
co libertad individual (caso en el cual se prohíben los matrimonios, se establece la separa
ción de los sexos, etc.); en segundo lugar, encontramos la lesión al bien jurídico integridad
piso-física (caso de las lesiones graves producto de castraciones o esterilizaciones etc.);
e incluso encontramos también la lesión al bien jurídico vida del feto (caso en el cual se
procede a provocar abortos). Ello torna el tipo en una modalidad pluriofensiva.
Siendo que el sujeto activo es genérico, puede serlo cualquier persona. Por otro lado, te
niendo en consideración la naturaleza de los bienes jurídicos lesionados, podemos apre
ciar que, si se vulnera el bien jurídico libertad individual o la integridad psico-física, nos
encontramos ante el caso de un sujeto pasivo genérico, pudiendo serlo cualquier inte
grante del grupo, mientras que si el bien jurídico lesionado es la vida del feto, evidente
mente tendríamos un sujeto pasivo específico, quesería justamente dicho feto.
Se trata de una figura netamente dolosa, el agente obra con la intención de impedir la
renovación del grupo humano, imposibilitando a sus víctimas la función natural de la
procreación o aniquilando a los seres en gestación. Como hemos dicho, la intención del
agente ha de ser la de destruir al grupo humano total o parcialmente, por lo que la ex
presión utilizada por el texto legal: “impedir”, denota tanto una acción dirigida contra la
totalidad del grupo como sobre un sector de tal.
e. Seg reg ació n fo rza d a de niño s de un g rupo a otro
El inciso 5 del artículo 319o, juntamente con el artículo II, inciso e) de la Convención repri
me el “traslado por fuerza de niños del grupo a otro grupo".
Siendo que esta modalidad pertenece a un tipo de genocidio cultural, protege el derecho
de todo niño a crecer en el seno de su propia fa m iliay grupo social, desarrollándose bajo
los mismos principios y patrones culturales que rigieron la vida de sus progenitores y de
sus ancestros.
En este caso el sujeto activo es genérico, puede ser cualquier persona; gobernante, funcio
nario o particular. Por su lado el sujeto pasivo es específico, por cuanto la acción material
en este delito está orientada sobre los “niños” del grupo humano. Evidentemente se re
quiere la existencia de una m ultiplicidad de víctimas.
La intención del agente no se dirige directamente a dañar o perjudicar a los niños, sino
que busca la destrucción del grupo al cual pertenecen. Puede incluso suceder que la
transferencia de esos niños les depare un mejor estatus de vida (por ejemplo entrar al
servicio de familias adineradas), a diferencia del que llevarían en su grupo humano de
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 919 of 1506 --

Tema 6: Temas de la Especialidad Penal
origen (pobreza, hambre, analfabetismo, etc.). El destino de los niños es intrascendente,
lo que requiere esta figura es su “reprogramación cultural”, propiciar el olvido de sus pa
trones culturales de origen y forjarles una nueva cultura. Este delito se consuma, no con
el empleo de la violencia, sino con el efectivo traslado de los niños de su grupo humano
originario, a otro. La violencia es el medio al cual recurre el agente, pero no constituye el
elemento consumativo del tipo, pues se trata de una figura de genocidio cultural, en la
cual prima la especial voluntad de parte del agente de fomentar la desnacionalización de
los menores. La aplicación de la violencia se halla en el plano de la tentativa de este delito;
no constituye todavía su constitución.
2. DESAPARICION FORZADA
2.1. Descripción normativa:
Alt. 320 CP El funcionario o servidor público, o cualquier persona con el consentimiento o aquiescencia
de aquel, que de cualquier forma priva a otro de su libertad y se haya negado a reconocer dicha pri
vación de libertad o a dar información cierta sobre el destino o el paradero de la víctima, es reprimido
con pena privativa de libertad no menor de quince ni mayor de treinta años e inhabilitación conforme
al artículo 36 incisos V) y 2),
La pena privativa de libertad es no menor de treinta ni mayor de treinta y cinco años, e inhabilitación conforme
al artículo 36 incisos 1) y 2), cuando la víctima:
a) Tiene menos de dieciocho años o es mayor de sesenta años de edad.
b) Padece de cualquier tipo de discapacidad.
c) Se encuentra en estado de gestación.
2.2. Definición del delito de desaparición forzada
Según la Convención Americana sobre la Desaparición Forzada de Personas, ésta consiste en
la "privación de la libertad a una o más personas, cualquiera que fuere su forma, cometida por
agentes del Estado o personas o grupos de personas que actúen con la autorización, el apoyo
o la aquiescencia del Estado, seguida de la falta de información o de la negativa a reconocer
dicha privación de libertado de informar sobre el paradero de la persona, con lo cual se impide
el ejercicio de los recursos legales y de las garantías procesales pertinentes" (Art.2).
La desaparición forzada es un delito de derecho internacional por el cual los Estados están
obligados a hacer rendir cuentas a los responsables mediante la investigación crim inal y el
procesamiento. Esto se aplica aunque el delito se haya cometido en el extranjero y aunque
ni el sospechoso ni la víctima sean nacionales de ese Estado. Además, constituye un crimen
de lesa hum anidad cuando se comete como parte de un ataque generalizado o sistemático
contra una población civil. Asimismo, aunque los tratados de derecho internacional hum a
nitario no hacen referencia directa al térm ino “desaparición forzada", el acto de desaparición
forzada viola la norma 98 de las Normas Consuetudinarias del Derecho Internacional Hu-
manitario, del Comité Internacional de la Cruz Roja (“Quedan prohibidas las desapariciones
forzadas").
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 920 of 1506 --

UBILEX
2 . 3 . B ie n j u r í d i c o p r o t e g id o
La doctrina como la jurisprudencia internacional no han dudado en calificar la Desaparición
Forzada como “una de las más graves y crueles violaciones de los Derechos Humanos”, por
causa de la amenaza a una serie de bienes jurídicos en perjuicio de una misma persona.
Nos encontramos, entonces, ante un delito de marcada fuerza pluriofensiva, caracterizado por
la violación acumulativa de derechos humanos. Ello se debe a que puede infligir una amplia
diversidad de violaciones de derechos humanos, incluida la violación de: • el derecho a la
vida: porque la persona puede ser asesinada o su suerte desconocerse; • el derecho a la segu
ridad y ía dignidad de la persona; • el derecho a no sufrir detención arbitraria; • el derecho
a no ser sometido a torturas ni a otros tratos o penas crueles, inhumanos o degradantes; • el
derecho a unas condiciones humanas de reclusión; • el derecho a la personalidad jurídica; •
el derecho a un juicio justo; • el derecho a la vida familiar.
2.4. Sujeto Activo
Para la Convención sobre Desaparición Forzada de personas el sujeto activo del delito puede
ser un agente del Estado o una persona o grupo de personas que actúe con autorización, apo
yo o aquiescencia de aquél. Para el Estatuto de Roma, en cambio, el delito puede ser cometido
por el Estado o una organización política, con lo cual se deja abierta la posibilidad de que
integrantes de grupos terroristas (vgr. Sendero Luminosoy MRTA) puedan ser incluidos como
autores del hecho punible91.
En nuestra legislación penal, señala el Acuerdo Plenario N°9-2009/CJ-i i 6 (FJ.io) que el “delito
de desaparición forzada de personas es un delito especial propio. Sólo puede ser perpetra
do por un agente estatal competente para informar sobre el paradero o situación jurídica del
afectado-aquí reside, como ha quedado expuesto, el principal defecto de la legislación nacio
nal, censurada por laCIDH, puesto que el Derecho Internacional Penal también comprende a
una organización política, sin que necesariamente pertenezca a la estructura estatal-".
El sujeto activo es cualificado y, por ello, es un delito especial propio y de infracción de deber,
así como de omisión pura de garante (inobservancia de un mandato de actuar). Como tal, so
bre el presupuesto de la privación de la libertad de una persona (situación típica), la conducta
específica del agente está dada por la omisión de información, que por lo demás está en la
posibilidad de hacerlo (relación entre ausencia de una acción determinada y capacidad para
realizar esa acción). R .N . N °2 1 8 4 -2 0 1 7 /N a c io n a l. Fj. 2.
2.5. Sujeto Pasivo
Cualquier persona, de cualquier edad o sexo.
91 MODOLELI GONZALEZ Juan Luis. “La Desaparición Forzada de Personasen el Sistema Interamericano de De
rechos Humanos”. En Ambos, Kai (coord.). Desaparición Forzada de Personas. Análisis Comparado e Internacional.
Bogotá: Temis, 2009. p. 140.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 921 of 1506 --

Tema 6: Temas de la Especialidad Penal
2.6. Tipicidad subjetiva
El artículo 32.0o del Código Penal requiere que la conducta que se tipifica como desaparición
forzaday que ocasiona el resultado lesivo se realice dolosamente, no siendo admisible la mo
dalidad culposa.
2.7. Conducta típica
“El tipo legal de desaparición forzada, en cuanto a su conducta típica, es un delito complejo
que puede ser cometido de diversas maneras. Son dos las conductas sucesivas que han de
tener lugar para la tipificación de este ilícito: a) la privación de libertad de una persona, a quien
se la oculta, y cuyo origen puede ser ab initio legal o ilegal (SSCIDH Trujillo Oroza, del 26 de
enero de 2000,y Heliodoro Portugal, del 12 de agosto de 2008); y b) la no información sobre la
suerte o el paradero de la persona a quien se le ha privado de su libertad.
La no información es, por consiguiente, el elemento esencial del tipo legal, cuyo fm y efecto au
tomático es sustraer a la persona privada de libertad de la protección de la ley, esto es, impedir
o dificultar la protección jurídica del afectado, a quien se le sustrae.
El deber de informar es fundamental para la tipificación de la conducta delictiva: es un delito
de incum plim iento del deber. El funcionario o servidor público infringe este deber, que fluye de
la normativa penal, si no cumple con proporcionar la información necesaria-que está en el
ámbito de su conocimiento o potestad de acceso a las fuentes de conocimiento sobre el suce
so- para hacer cesar la sustracción del individuo afectado del sistema legal de protección, sin
que sea necesario un requerimiento expreso. El deber de información se impone en virtud del
principio de injerencia, sea que la privación de libertad sea legal o ilegal. Mientras perdura el
estado de desaparición de la persona, a todos los agentes que estén en la potestad y en las
condiciones de conocer lo acontecido le es exigióle este deber. No es necesario que los autores
o partícipes intervengan desde el comienzo de la ejecución para que respondan penalmente
[IVÁN MEINI MENDEZ: Perú: El delito de desaparición forzada. En: Desaparición Forzada de
Personas-Análisis comparado e internacional, (Coordinador: KAI AMBOS), obra citada, pági
na i 22]. En atención a las características de este delito, el sujeto activo mantiene su obligación
de cumplir con informar sobre el destino o situación jurídica de la persona privada de libertad
así haya dejado de ser funcionario, por cuanto en su oportunidad y en determinadas circuns
tancias generó o conoció de la privación de libertad, situación que-según se ha destacado- lo
convierte en garante y esta seguirá hasta que se deje considerar desaparecido a una persona
(aparezca vivo o muerto).” Acuerdo Plenario No9-2009/C]-i i 6. F3.11.
2.8. Consumación
El delito de desaparición forzada, por la forma de afectación del objeto de protección, es un
delito permanente. Ahora bien, este delito se consuma cuando el individuo privado de su li
bertad desaparece.
Siendo así, en el delito de desaparición forzada de personas la fase consumativa se extiende,
la ofensa al bien jurídico se prolonga en el tiempo, en virtud al mantenimiento del compor
tamiento peligroso del agente-dependiente en su totalidad de su ejecución de la voluntad
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 922 of 1506 --

del agente-; esto es, en el caso concreto, hasta que no se da la información correspondiente
sobre el paradero del afectado, mientras el deber de informar no sea satisfecho. El momento
en que tal permanencia cesa se presenta cuando se establezca el destino o paradero de la
víctim a-ésta "aparece”-, o cuando sean debidamente localizados e identificados sus restos
(SCIDH Heliodoro Portugal, párrafo 34); se supere, de este modo, la falta de información que
bloquee los recursos materiales y legales para el ejercicio de derechos y el esclarecimiento
de los hechos, y mientras de este modo perdure el dolor e ¡ncertidumbre en los allegados
de la persona desaparecida y en la sociedad en general [KAI AMBOS/MARÍA LAURA BÓHM:
La desaparición forzada de personas como tipo penal autónomo. En: Desaparición Forzada
de Personas-Análisis comparado e internacional, (Coordinador: KAI AMBOS), Obra citada,
página 250] A cu erd o P le n a rio N °9 -2 0 0 9 /C J -i i 6. Fj.14.
3. TORTURA
3 . 1. Descripción normativa:
Art, 321 C.P.: El funcionario o servidor público, o cualquier persona con el consentimiento o aquiescen
cia de aquel, que inflige dolores o sufrimientos graves, sean físicos o mentales, a otra persona o la
somete a cualquier método tendente a menoscabar su personalidad o disminuir su capacidad mental
o física, es reprimido con pena privativa de libertad no menor de ocho ni mayor de catorce años.
La pena privativa de libertad es no menor de quince ni mayor de veinte años, cuando la víctima:
a. Resulte con lesión grave.
b. Tiene menos de dieciocho años o es m ayor de sesenta años de edad.
c. Padece de cualquier tipo de dlscapacldad.
d. Se encuentra en estado de gestación.
e. Se encuentra detenida o recluida, y el agente abusa de su condición de autoridad para cometer el delito.
Si se produce la muerte de la víctima y el agente pudo prever ese resultado, la pena privativa de libertad es no
menor de veinte ni mayor de veinticinco años.
C o operación de p ro fesio nal. El médico o cualquier profesional sanitario que cooperara en la
perpetración del delito señalado en el artículo anterior, será reprimido con la misma pena de
los autores.
3.2. Definición del delito de tortura
La Convención contra la tortura y otros tratos o penas crueles, inhumanos o degradantes,
de 10 de diciembre de 1984, en su artículo 1, establece que la tortura es el acto por el cual
se inflige intencionadamente a una persona dolores o sufrim ientos graves, ya sean físicos
o mentales, con el fin de obtener de ella o de un tercero información o una confesión, de
castigarla por un acto que haya cometido, o se sospeche que ha cometido, o de intim ida r o
coaccionar a esa persona o a otras, o por cualquier razón basada en cualquier tipo de discri
minación, cuando dichos dolores o sufrim ientos sean infligidos por un funcionario público
u otra persona en el ejercicio de funciones públicas, a instigación suya, o con su consenti
miento o aquiescencia.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 923 of 1506 --

Tema 6: Temas de la Especialidad Penal
3.3. Bien jurídico protegido
El bien jurídico que protege el delito de tortura tiene varias aristas, pues se han configura di
versas posiciones al respecto; así, se considera como tal a la dignidad de la persona humana, la
administración pública (porque supone un abuso de poder de los funcionarios contra particula
res), la vida e integridad psicofísica, la integridad personal, la libertad personal o individual; etc.
Si embargo, debe considerarse al delito de tortura como un delito pluriofensivo puesto que
su acción conlleva al daño que abarca un sinnúmero de derechos, y sin duda su protección
abarca a ese conglomerado de derechos como el derecho a la vida, a la salud, a la libertad,
que constituyen derechos fundamentales de la persona humana, absolutos, irrenunciables,
imprescriptibles e inviolables.
Sujetos: El sujeto activo el funcionario o servidor público, también cualquier persona que actúe
con el consentimiento o aquiescencia de aquel. No cabe duda que nos encontramos ante un
delito especial propio, debido a que la actuación del sujeto como funcionario público se dará,
normalmente, en aquellos casos en los que por su rol de funcionario o servidor público tenga la
posibilidad de obtenerde una persona una confesión o información, o de castigarla, intimidarla
o coaccionarla, pero no siempre el escenario de una tortura será una detención. El sujeto pasivo,
puede ser cualquier persona, de cualquier edad o sexo; generalmente se presenta que el sujeto
pasivo es una persona que está privada de libertad, legítima o ilegítimamente.
3.4. Conducta típica
El artículo 321 del Código Penal el delito de tortura presenta dos modalidades: a. Infligir do
lores o sufrimientos graves físicos o mentales b. Someter a otro a condiciones o métodos que
anulen su personalidad o disminuyan su capacidad física o mental, aunque no causen dolor
físico o aflicción psíquica.
3.5. Tipicidad subjetiva
El numeral 321o del Código Penal requiere que la conducta que se tipifica como tortura y que
ocasiona el resultado lesivo se realice dolosamente, no siendo admisible la modalidad culposa.
3.6. Concurso
Aunque la tortura constituye un solo acto, se aplicarán las reglas del concurso real, esto es que
se castigarán los hechos separadamente, conforme lo establecido en el numeral 50 del Código
Penal. Esto significa que, si los torturados por un solo agente han sido varios, aquél incurriría
en tantos delitos como víctimas haya, porque la tortura aplicada a cada uno de ellos, constitu
ye un hecho independiente.
3.7. Consumación
El delito de tortura se consuma con la lesión de bien jurídico, cuando se inflija a otros dolores o
sufrimientos graves, sean físicos o mentales, o lo someta a condiciones o métodos que anulen
su personalidad o disminuya su capacidad física o mental.
