Bien jurídico protegido: La trata implica privar a las víctimas de su libertad, someterlas a
condiciones de violencia, amenazas y engaños, y reducirlas a una situación de completa
indefensión y vulnerabilidad, en la que son despojadas de su autonomía y capacidad de
decidir sobre sus propias vidas. Esta total anulación de la voluntad y el trato degradante al
que son sometidas las víctimas constituye una violación flagrante de su dignidad como seres
humanos92.
