T ip icid ad ob jetiva: Según el Acuerdo Plenario N °0 4 -2 0 2 3 /C IJ -ii2 (Fj. 8) “el delito de trata de
personas se configura cuando el agente realiza una o algunas de las conductas previstas en el
artículo 129-A del Código Penal -en adelante, CP—: capta, transporta, traslada, acoge, recibe o
retiene a otro con fines de explotación, sin que sea necesario que el fin llegue a concretizarse.
Lógicamente, debe realizarse a través de los medios previstos en la norma.
Los fines de explotación de la trata de personas comprende, entre otros, la venta de niños,
niñas o adolescentes, la prostitución y cualquier forma de explotación sexual, la esclavitud o
prácticas análogas a la esclavitud, cualquier forma de explotación laboral, la mendicidad, los
