Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 925 of 1506 --

Tema 6: Temas de la Especialidad Penal
trabajos o servicios forzados, la servidumbre, la extracción o tráfico de órganos o tejidos so
máticos o sus componentes humanos, así como cualquier otra forma análoga de explotación.
La trata de personas comprende una serie de conductas, como la captación, el transporte, el
traslado, la acogida, la recepción o la retención de personas. Los tratantes de personas utilizan
diversos medios para lograr el reclutamiento, como la violencia, la amenaza u otras formas
de coacción, la privación de la libertad, fraude, engaño, abuso de poder o de una situación de
vulnerabilidad, la concesión o recepción de pagos o de cualquier beneficio. En ese orden de
ideas, este delito es independiente de que con posterioridad se produzca una situación con
creta de explotación (laboral, sexual u otras formas). Igualmente, el consentimiento de la víc
tim a mayor de edad a los requerimientos del tratante no es relevante. Cas. N°1351-2019 Puno.
Señala Vega Llapapasca que93 "la tipicidad de la trata de personas abarca un amplio espec
tro de conductas que van desde la captación inicial de las víctimas hasta su explotación final,
pasando por etapas intermedias de transporte, traslado y retención. Además, se sanciona a
quienes coadyuvan o facilitan estas actividades, lo que demuestra una visión integral y com
prehensiva por parte del legislador para enfrentar este grave delito. "El tipo penal hace alusión
a una serie de verbos rectores:
Promover, importa incentivar una actividad determinada, en este caso la trata de perso
nas.
Favorecer, supone crear el ambiente propicio, para que se puedan captar, transportar u
retener, una persona, en el territorio, para su entraday/o salida.
Financiar, significa proveer de fondos suficientes, para que otras personas puedan captar
personas, sacándolas del país, para la realización de fines de explotación.
Facilitar, implica allanar los obstáculos, para que la persona, pueda ser retenida en contra
de su voluntad y, así someterla a tratos inhumanos.”
Luego, se dice, según el tenor literal, que la promoción, favorecí miento, financiamiento, facili
tación se dirige a la captación (obtención), transporte (desplazamiento), traslado (de un lugar
a otro), acogida (recibimiento), recepción (acogimiento) o retención (impedir su traslado),
en el territorio de la República, se refiere a la circunscripción territorial, que se describe en el
artículo 549 de la Ley Fundamental o para su salida (a otro país) o, entrada dentro del Perú,
procedente de otra Nación" (Peña Cabrera Freyre, 2019, p. 471).
Las finalidades que persigue este delito son diversas, pero todas ellas giran en torno a la explo
tación de la persona, convirtiéndola en una mercancíay privándola de su dignidady libertad.
Diferencia de los verbos rectores “Transportar” y “Trasladar”
