tie n e so b re la víctima de u n a p e rs o n a a o tra . No consiste entonces, en movilizar físicamente
a lavíctima (transporte) sin o en q u e la p e rs o n a q u e tie n e d o m in io so b re la v íc tim a tra sp as e
d ic h o d o m in io a o tra p ers o n a , d is p o n ié n d o s e fá c tic a o ju r íd ic a m e n te d e e lla . Así, el tra s la
d o no su p o n e el m o v im ie n to d e la p ers o n a , sino d e s p la z a r el p o d e r q u e ex is te so b re e lla . A
modo de ejemplo: cuando un padre o madre entrega a alguno de sus hijos o hija a una tercera
persona a fin de que sea explotado o explotada. [Resaltado agregado].
S u je to activo: El sujeto activo en el delito de trata de personas puede ser cualquier persona,
sin importar su género, edad, condición social, profesión o relación con la víctima. Lo que lo
define como tratante es su participación en alguna de las acciones que conforman el proceso
de trata, como captar, transportar, trasladar, acoger o recibir a la víctima, con el fin de explo
tarla.94
S u je to pasivo: En el delito de trata de personas, las víctimas provienen de diversos contextos
y no existe una caracterización específica en cuanto a género, edad o condición social. Sin em
bargo, es innegable que la pobreza y la falta de oportunidades son factores que generan una
mayor vulnerabilidad frente a este flagelo.95
T ip ic id a d s u b je tiv a : Podemos identificar los siguientes elementos de la tipicidad subjetiva en
el delito de trata de personas:
• D olo: Existe un amplio consenso doctrinario, en referencia a cómo puede ser definido el
dolo en el derecho penal,y es entendido como “conocimiento y voluntad de realizar cada
uno de los elementos objetivos de la descripción penal” (Mir Puig, 1998, p. 240). En ese
sentido, el delito de trata de personas requiere dolo, lo que significa que el autor debe
actuar con intención. En otras palabras, el perpetrador debe tener la intención de explo
tar a las víctimas de manera directa o indirecta. Esto incluye la intención de someter a las
personas a condiciones de explotación, que puede ser sexual, laboral, o de otra índole.
• C o n o c im ie n to d el c a rá c te r ilíc ito d e la co n d u cta : El autor debe ser consciente de que su
conducta está dirigida a realizar un acto ilícito. Esto implica que sabe que su comporta
miento tiene como fin la explotación de personas y actúa con plena consciencia de ello.
• F in a lid a d e x p lo ta tiv a : El objetivo del delito de trata de personas es la explotación de las
víctimas. Por lo tanto, el autor debe actuar con el propósito de explotara las personas me
diante el uso de violencia, coacción, engaño, o abuso de poder. La finalidad explotadora
es un componente clave en la tipicidad subjetiva, ya que es necesario que el autor tenga
la intención de obtener un beneficio económico o de otro tipo a través de la explotación
de las personas tratadas.
• C o n o c im ie n to d e la v u ln e r a b ilid a d d e las víc tim as: Aunque no siempre es necesario, en
algunos casos puede ser relevante que el autortenga conocimiento de la vulnerabilidad o
