ta ra personas en situaciones de debilidad o desventaja.
En resumen, la tipicidad subjetiva del delito de trata de personas en Perú se basa en la inten
ción del autor de explotar a las víctimas, actuando con dolo y con el conocimiento de la ilicitud
de su conducta. La ley exige que el autor actúe con la finalidad específica de someter a las
personas a condiciones de explotación para que el delito sea considerado como ta l96.
Agravantes:
Ate 129-3 CP„- La pena será no menor de doce ni mayor de veinte años de pena privativa de libertaés
e inhabilitación conforme ai artículo 36 incisos 1,2, 3,4 y 5 del Código Penal, cuando:
1. El agente comete el hecho abusando del ejercicio de la función pública;
2. El agente es promotor, integrante o representante de una organización social, tutelar o empresa
rial, que aprovecha de esta condición y actividades para perpetrar este delito;
3. Exista pluralidad de víctimas;
4. La víctima tiene entre catorce y menos de dieciocho años de edad o es incapaz;
5. El agente es cónyuge, conviviente, adoptante, tutor, curador, pariente hasta el cuarto grado de consanguini
dad o segundo de afinidad, o tiene a la víctima a su cuidado por cualquier motivo o habitan en el mismo hogar.
6. El hecho es cometido por dos o más personas.
7. La víctima se encuentra en estado de gestación.
La pena será privativa de libertad no menor de 25 años, cuando;
1. Se produzca la muerte, lesión grave o se ponga en inminente peligro la vida y la seguridad de la víctima.
2. La víctima es menor de catorce años de edad o padece, temporal o permanentemente, de alguna discapa
cidad física o mental.
3. El agente es parte de una organización criminal.
Las agravantes del delito de trata de personas se sustentan no solo en la gravedad de la afec
tación al bien jurídico de la dignidad humana, sino también en la lesión de otros bienes ju rí
dicos como la vida, lasaludy la integridad física de las víctimas. Además, se agravan las penas
cuando el agente incurre en una infracción al deber especial que le es exigible en virtud de
una posición de garante o situación de dominio sobre la víctima, así como cuando concurren
circunstancias que denotan una mayor peligrosidad, planificación o presencia de estructuras
delictivas organizadas97.
Tentativa: En el contexto de la trata de personas, la tentativa se refiere a situaciones en las
que una persona empieza a realizar actos preparatorios para cometer el delito, como plani
ficar, reclutar, o intentar trasladar a una víctima con la intención de explotarla, pero no logra
consumar el delito por circunstancias externas o imprevistas. Por ejemplo, si un individuo está
organizando el traslado de una víctima para explotarla laboralmente, pero es detenido por las
autoridades antes de que se complete el traslado, este acto puede considerarse una tentativa
de trata de personas98.
