Consumación: Se considera que el delito de trata está consumado cuando":
La acción delictiva se completa: Esto puede incluirel reclutamiento, transporte, traslado,
acogida o recepción de la víctima.
Se establece la explotación: La víctima es efectivamente explotada, ya sea laboralmente,
sexualmente o de cualquier otra forma prohibida por la ley. En la trata de personas, la
consumación se da cuando se completa el ciclo de explotación que el delito busca preve
nir.
Por ejemplo, si una persona es trasladada de un lugar a otro con la intención de serexplotaday
realmente es explotada (laboralmente, sexualmente, etc.), el delito se considera consumado.
5. EXPLOTACION
5.1. Delito de explotación sexual
Descripción normativa:
“Art. 129-C CP. El que, mediante violencia, amenaza u otro medio, obliga a una persona a ejercer actos
de connotación sexual con la finalidad de obtener un aprovechamiento económico o de otra índole,
será reprimido con pena privativa de libertad no menor de diez ni mayor de quince años.
Si el agente comete el delito mediante engaño, manipulación u otro condicionamiento, se aplicará la
misma pena del primer párrafo.
La pena privativa de libertad será no menor de quince ni mayor de veinte años, cuando:
1. El agente tiene a la víctima bajo su cuidado o vigilancia por cualquier motivo, o mantiene con ella un vínculo de
superioridad, autoridad, poder o cualquier otra circunstancia que la impulse a depositar su confianza en él.
2. El agente comete el delito en el ámbito del turismo, en el marco de la actividad de una persona jurídica o
en el contexto de cualquier actividad económica.
La pena privativa de libertad será no menor de veinte ni mayor de veinticinco años, cuando:
7. El agente es ascendiente o descendiente por consanguinidad, adopción o por afinidad: pariente colateral
hasta el cuarto grado de consanguinidad o adopción, o segundo grado de afinidad; cónyuge, excónyuge,
conviviente, exconviviente o tenga hijos en común con la víctima; o habite en el mismo domicilio de la
víctima, siempre que no medien relaciones contractuales o laborales.
2. La explotación sexual es un medio de subsistencia del agente.
3. Existe pluralidad de víctimas.
4. La víctima tiene discapacidad, es adulta mayor, padece de una enfermedad grave, pertenece a un pueblo
indígena u originario, o presenta cualquier situación de vulnerabilidad.
5. Se produzca una lesión grave o se ponga en peligro inminente la vida o la salud de la víctima.
6. Se derive de una situación de trata de personas.
7. El agente actúe como integrante de una banda o una organización criminal.
8. La víctima está en situación de abandono o de extrema necesidad económica.
Si se produce la muerte de la víctima, la pena privativa de libertad será no menor de veinticinco ni mayor de
En todos los casos se impondrá, además, la pena de inhabilitación conforme al artículo 36 incisos 1,2,3, 4, 5,
