"Art. 129-1 CP. Promoción y favorecimiento de ¡a explotación sexual de niñas, niños y adolescentes
El que promueve, favorece o facilita la explotación sexual de niña, niño o adolescente será reprimido
con pena privativa de libertad no menor de quince ni mayor de veinte años.
El consentimiento brindado por el adolescente carece de efectos jurídicos.
