Bien jurídico protegido
Siendo coherentes con lo sostenido en el análisis de los anteriores delitos, el bien jurídico pro
tegido por el artículo 129-1 del Código Penal es nuevamente la dignidad humana. Efectiva
mente, quien promociona o publicita folletos donde se ofrece relaciones sexuales con adoles
centes con fines comerciales, pone en peligro de explotación a las personas que brindan estos
servicios y coloca los derechos humanos de las víctimas en una situación de vulnerabilidad.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 932 of 1506 --

UBILEX
Tipicídad objetiva
El presente delito desvalora los actos de favorecer, publicitar, etc. folletos y otro tipo de pu
blicaciones que atraen a sus eventuales clientes: es decir, su conducta no va dirigida hacia las
personas que ejercerán la actividad sexual, sino a aquellos que contratarán ese servicio (dado
que promueve la demanda del servicio sexual).
En este sentido, se diferencia del delito de trata de personas, puesto que este últim o supone
una conducta del agente que se dirige hacia la víctima de la trata, favoreciendo su captación,
traslado, recepción, etc. (promueven la oferta del servicio sexual).
Por tanto, el delito de explotación sexual comercial adolescente no se superpone en modo
alguno al delito de trata de personas. Así, no existe un bis in ídem en la aplicación de estas dos
figuras, pues si bien ambos tipos penales regulan formas de ataque a la dignidad humana,
estos ataques (desvalorde acción) son totalmente distintos. Sin embargo es posible, en deter
minados casos, apreciar perfectamente un concurso real entre estas dos figuras.
Tipicidad subjetiva
El tipo penal exige la concurrencia dolo en la conducta del agente.
5.3. Delito de usuario-cliente
Descripción normativa:
"Art. 1 29 -J CP”. Cliente del adolescente
El que, mediante una prestación económica o ventaja de cualquier naturaleza tiene acceso carnal-pora
vía vaginal, anal o bucal o realiza otros actos análogos introduciendo objetos o partes del cuerpo por
alguna de las dos primeras vías con una persona de catorce y menor de dieciocho años, será reprimido
con pena privativa de libertad no menor de quince ni mayor de veinte años.
El consentimiento brindado por el adolescente carece de efectos jurídicos."
Bien jurídico protegido
El bien jurídico protegido por este delito es la libertad sexual, porque se pretende que el sujeto
pasivo asuma una determinada forma de ejercer la sexualidad. Se busca evitar que se distor
sione el proceso de deliberación del adolescente respecto a la forma de ejercer su sexualidad.
Tipicidad objetiva
El ofrecimiento de algún tipo de ventaja constituye un elemento de asimetría de poder que
evita que el adolescente pueda tomar una decisión sobre el desarrollo de su sexualidad en
plena libertad. Se trata del abuso de poder del sujeto activo que vicia el supuesto consenti
miento de la víctima.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 933 of 1506 --

Tema 6: Temas de la Especialidad Penal
Mientras que el profesor Muñoz Conde sostiene que, (...) el cliente que paga promueve o favorece
la prostitución o la continuación en la misma (...)W4, lo cual pone en peligro la libertad sexual del
menor.
En nuestro concepto, el cliente que paga por los servicios sexuales de una menor de edad, a la
vez que favorece la prostitución (y por lo tanto pone en riesgo la dignidad sexual de la menor),
está afectando la libertad sexual de la menor en virtud del abuso deesa posición asimétrica.
Por tanto, el delito contemplado en el artículo 179-A° del Código Penal supone un atentado a la
libertad sexual de la víctima, pero también pone en peligro la dignidad del o la menor, dado el
riesgo de ser susceptible de explotación sexual y versus derechos vulnerados.
Tipicidad subjetiva
El delito exige la concurrencia de dolo en la conducta del usuario sexual.
5.4. Pornografía infantil
Descripción normativa:
r P A f t í E l que posee, promueve, fabrica, distribuye, exhibe, ofrece, comercializa, publicita, públi
cos, importa o exporta por cualquier medio objetos, libros, escritos, imágenes, videos o audios, orealiza
espectáculos en vivo de carácter sexual, en ios cuales participen menores de dieciocho años de edad,
será sancionado con pena privativa de libertad no menor de seis ni mayor de diez años y con ciento
veintena trescientos: sesenta y cinco días multa.
La pena privativa de libertad será no menor de diez ni mayor de quince años y de cincuenta a trescientos
sesenta y cinco días multa cuando:
1. La víctima tenga menos de catorce años de edad.
2. El material se difunda a través de cualquier tecnología de la información o de la comunicación o cualquier
otro medio que genere difusión masiva.
3. El agente actúe como miembro o integrante de una banda u organización criminal.
Entodosílosmasos:se impone, además, la pena de inhabilitación conforme al artículo 36, incisos 1, 2, 3, 4, 5,
6,8, 9,10y 77.".
Tipicidad objetiva
Se explota a la víctima en la elaboración de material pornográfico tales como películas, re
vistas, fotos, etc. de carácter obsceno. El consumidor de este tipo de imágenes ya no tiene
que acudir a ambientes marginales para conseguir, algunas fotos de menores determinados,
con riesgo cierto de ser descubierto. El acceso a la red le permite, desde su casa, su lugar de
trabajo o incluso desde ordenadores instalados en establecimientos públicos asomarse, con
muy escaso esfuerzo, a la producción mundial de este tipo de material. Incluso, si es constante
y no ceja en su busca, podrá localizar espacios (webs, chats, foros), donde otros sujetos, con
su mismo objetivo, estarán dispuestos a intercambiar con él toda la producción que hayan
encontrado, sin contraprestación económica alguna.104
104 T A M A R IT S U M A L L A , Josep M a ría . Protección penal del menor frente al abusoy la explotación sexual. A ra n z a d i: N a
varra, 2002. p. 84.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 934 of 1506 --

En definitiva, los conceptos “traficante” y “consumidor” se difum inan y entremezclan, de tal
manera que los consumidores pasan a ser los principales difusores de pornografía en la red.
Internet plantea, en este ámbito, problemas de muy diverso orden. En primer lugar, se consta
ta que los centros de producción de pornografía infantil se van desplazando deform a inexora
ble hacia lugares donde expresamente no aparecen tipificadas estas conductas (en ocasiones
se encuadran en tipos más amplios con penas simbólicas), donde se protege únicamente a
personas de edad muy inferior a los 18 años o donde resulta ineficaz la persecución de estos
delitos.
La falta de una uniformidad legal,y de colaboración internacional determina una especial di
ficultad en la persecución de aquellos que producen este material, y, por ello, convierten en
ilusoria la defensa adecuada de los menores que son objeto de estas prácticas. La actuación
de los tribunales en nuestro entorno se limita, con contadas excepciones, a las conductas de
difusión de material ya elaborado o de tenencia de pornografía. Este hecho condiciona, sin
duda, la actividad del legislador y de los tribunales. La problemática se ve agravada en los
supuestos en que el material pornográfico tiene como sujeto pasivo a incapaces. La falta de
persecución de las redes de producción, impide conocer, en muchos casos, si en la elaboración
se han utilizado imágenes de estas personas. Además, son muy numerosas las legislaciones
que contemplan como delito la pornografía infantil, pero se olvidan de los incapaces, lo que,
sin duda, supone que estas personas, especialmente desprotegidas, queden a merced de or
ganizaciones que se dediquen a tan reprochable actividad.
Tipicidad subjetiva
El tipo exige la presencia del dolo en el autor.
