5 .5 .1 . E scla vitud
T ip ic id a d o b je tiv a 105: El artículo 129-Ñ del CR poruña parte, sanciona al que obliga a otra per
sona a trabajar en condiciones de esclavitud o la reduce o mantiene en dichas condiciones.
El delito tiene tres verbos rectores: “obligara trabajar", “reducirá trabajar"o “m antenertrabajando”
en condiciones de esclavitud. Cada uno de ellos hace referencia a la situación en la que se en
cuentra la víctima frente a la esclavitud. El primero comprende la situación fáctica consistente
en que la víctima es insertada en contra de su voluntad a trabajar en dichas condiciones de
esclavitud; el segundo verbo de reducir a trabajar en tales condiciones implica que previa
mente se ofrecieron o se dieron condiciones laborales meridianamente legales, pero luego se
incumplió lo ofrecido por el empleador, aniquilando el contrato laboral verbal o escrito que
hubieren tenido; y, el tercero, de mantener trabajando en tales condiciones significa que la
víctimayase encontraba en una situación de esclavitudy el sujeto activo realiza acciones que
permiten que dicha situación permanezca del mismo modo.
En cualquier caso, para la tipificación de la esclavitud, no interesa si las labores que realizan las
víctimas son lícitas o no, o si hubo pago de por medio o no, ya que-com o se ha indicado-, en
ningún caso pueden consentir una situación de esa naturaleza.
La esclavitud del artículo 129-Ñ del CP debe entenderse que solo se trata del ámbito laboral,
pues el citado dispositivo legal expresamente excluye los supuestos del delito de explotación
sexual -p o r ende, también de esclavitud sexual- que contienen una respuesta criminal preci
samente en los tipos penales específicos para las conductas concernidas.
5 .5 .2 . S ervidum bre
T ip ic id a d o b je tiv a : El artículo 129-Ñ del CP sancionaal que obliga a otra persona a trabajar en
condiciones de servidumbre o la reduce o mantiene en dichas condiciones. La Corte IDH, en
el caso Trabajadores de la Hacienda Brasil Verde vs. Brasil106 (sentenciaya citada en el presen
te Acuerdo Plenario), explicó que la servidumbre es una forma análoga de esclavitudy debe
recibir la misma protección. Además, entre las formas en que este delito se expresa, la citada
Corte definió la servidumbre por deudas, la cual se configura cuando los trabajadores reciben
adelanto de pago, y luego pago de salarios irrisorios y descuentos excesivos por comida, me
dicamentos y otros productos, todo lo cual genera una deuda impagable para la víctima quien
105 A cu erd o P le n a rio N ° 04- 2023/C IJ-112 . Fj. 4 0 .
106 Párr. 210 .
