debe continuar sometida a la situación de servidumbre. Es decir, el agente activo le genera
una deuda a la víctima quien trabaja para solventarla, pero esta se vuelve impagable, ya que
el propio agente impide que la pueda term inar de pagar recurriendo a los medios abusivos
indicados anteriormente107.
En cualquier caso, en la servidumbre el agente activo se aprovecha de la situación de vulnera
bilidad de la víctima al ser incapaz de satisfacer sus necesidades más básicas, dificultades eco
nómicas persistentes o en deterioro. Por tanto, la víctima conoce qué labores realizará, pero su
consentimiento no es válido en este tipo de delitos.
En cuanto a los verbos rectores para la configuración de la servidumbre, estos son los mismos
que los señalados para el delito de esclavitud.
5.6. Trabajo forzoso
Descripción normativa:
^ — y “Art. 1 2 0 -0 CP. El que somete u obliga a otra persona, a través de cualquier medio o contra su voluntad,
J L m a realizar un trabajo o prestar un servicio, sea retribuido o no, será reprimido con pena privativa de
/ I J libertad no menor de seis ni mayor de doce años y multa de cíen a doscientos días-multa.
La pena será privativa de libertad no menor de doce años ni mayor de quince años y multa de dos
cientos a trescientos días-multa si concurre alguna de las siguientes circunstancias:
1 . El agente tiene a la víctima bajo su cuidado o vigilancia por cualquier motivo, o mantiene con ella un vínculo
de superioridad, autoridad, poder u otro que la impulse a depositar su confianza en él.
2. La víctima tiene entre catorce y menos de dieciocho años de edad, y la actividad que desarrolla está prohi
bida por la ley en razón a su edad,
3; El agente comete el delito en el marco de la actividad de una persona jurídica o en el contexto de cualquier
actividad económica.
La pena será privativa de libertad no. menor de quince ni mayor de veinte años y multa de trescientos a tres
cientos sesenta y cinco días-multa, en los siguientes casos:
1. El agente es familiar de la víctima hasta el cuarto grado de consanguinidad o segundo de afinidad.
2 . Existe pluralidad de víctimas.
3 . La víctima tiene menos de catorce años de edad, es adulta mayor, tiene discapacidad, padece de enfermedad
grave, pertenece a un pueblo indígena, es trabajador migrante o presenta cualquíersituación de vulnerabilidad.
4 . Se produzca lesión grave o se ponga en peligro inminente la vida o la salud de la víctima.
Si se produce !a muerte de la víctima, la pena privativa de libertad es no menor de veinte ni mayor de veinticinco
años. Se aplica la misma multa si se dan los agravantes precedentes. En todos los casos se impondrá además
Tipicidad objetiva: El concepto contemporáneo de trabajo forzoso hace referencia: “a obligar,
a través de cualquier medio, incluido el abuso de la situación de vulnerabilidad, a una persona a realizar
o continuar realizando un trabajo o servicio". En esta medida, se debe de precisar que el tipo y el
volumen del trabajo realizado no son elementos del trabajo forzoso, sino que son indicadores
que evidencian la ausencia de consentimiento.
