j j ^ nuevos estándares, en cuanto a la investigación, juzgamiento y sanción de los integrantes de
la organización criminal, de tal suerte que excluyó de su ámbito de aplicación aquéllas orga
nizaciones criminales que no cumplan con dichos parámetros, y por ende, las sustrajo de la
competencia de la Corte Superior Nacional de justicia Penal Especializada.
La dación de la Ley 32108 trajo consigo la descriminalización parcial del delito de organización
criminal, previsto en el artículo 317 del Código Penal, recayendo ésta en tres ámbitos109:
1. Supresión del verbo promover: La dación de la Ley 32108 describe tres verbos rectores,
entre el los, organizar, constituiré integrar una organización criminal, a diferencia de la ley
anterior que estableció cuatro verbos rectores, a saber, promover, organizar, constituir e
integrar una organización criminal, lo que significó que se suprimiera de su configuración
típica el verbo rector promover. El acto de promover una organización criminal alude a la
realización posterior de actos de difusión, consolidación y expansión de una organización
criminal ya creada y organizada, presentándose incluso en plena ejecución del proyecto
delictivo, no limitándose a crear solo condiciones operativas para su desempeño local o
internacional, sino de dotarle programáticamente el desarrollo funcional de la estructura
y de sus operadores centrales o ejecutivos, según Prado Saldarriaga110.
En ese orden de ideas, se habría descriminalizado uno de los verbos rectores esenciales
del delito de organización criminal, a saber, el acto de promover una organización cri
minal, el cual presentaría diversos componentes, entre ellos, la difusión, consolidación
y expansión de una organización criminal ya creada, cuestión fundamental en la cons
trucción del delito de organización criminal, debido a que el comportamiento criminal
de promover una organización criminal tiene incidencia en que ésta adquiera un mayor
grado de desarrollo en su estructura, sea diversificando sus actividades ilícitas o teniendo
mayor presencia en otras áreas geográficas, de cara a lograr un mayor grado de compleji
dad, consustancial al concepto de organización criminal.
2. Delitos graves superiores a los seis años de PPL: En igual sentido, la ley 32108 modificó
el delito de organización criminal estableciendo que solo podría cometer delitos graves
superiores a los seis años de pena privativa de la libertad, en la medida que el marco de
pena conminada de dicho delito, tanto en su extremo mínimo y máximo legal lo supere,
a diferencia de la ley anterior que solo exigía que la organización criminal esté destinada
a cometer delitos, sin especificar penalidad alguna. En buena cuenta, con la dación de la
nueva ley se habría establecido que el delito de organización criminal no sería aplicable
a delitos sancionados con penas de 6 años de pena privativa de la libertad o menores
a la misma, excluyendo tácitamente de su radio de acción, una cantidad importante de
delitos previstos en el artículo 3 de la Ley 30077 Ley contra el crimen organizado, entre
ellos, delitos contra la administración pública, el delito de conspiración y ofrecimiento
parael sicariato, el delito de violación del secreto de las comunicaciones, el delito de hurto
agravado, el delito de receptación agravada, el delito de estafa agravada, el delito de de-
