delitos monetarios, delitos contra la salud pública, delitos de tráfico ilícito de migrantes,
delitos ambientes, delito de mareaje o reglajey el delito de falsificación de documentos111.
3 . Beneficio económico: La ley 32108 exige que la organización criminal tenga por finalidad,
obtener de manera directa o indirecta, el control de la cadena de valor de una econo
mía o mercado ilegal, para obtener un beneficio económico, criterio bajo el cual se ha
bría rediseñado el delito de organización criminal, al introducir conceptos generales que
provienen de la economía, entre ellos, “control de la cadena de valor de una economía” o
“mercado ilegal”, a la par que habría reducido el ámbito de prohibición de dicho delito,
circunscribiéndola únicamente a las organizaciones criminales que buscan obtener be
neficio económico.
Dicha ley adolecería de una adecuada técnica legislativa, ya que habría empleado con
ceptos jurídicos indeterminados que provienen de la economía al establecer que la orga
nización criminal debe tener porfinalidad “obtenerdirecta o indirectamente, el control de
la cadena de valor de una economía o mercado ilegal, para obtener beneficio económico”
por existir indeterminación sobre su contenido112, inobservando uno de los criterios rec
tores del principio de legalidad, a saber, la noción de certeza, según el cual la ley penal
debe estar redactada de la manera más exacta posible, para que los destinatarios sepan
cuáles son los actos incriminadosy la sanción que le corresponde, incurriendo en uno de
los defectos de técnica legislativa, a saber, el empleo de fórmulas generales.113
En el ámbito procesal, la entrada en vigor de la Ley 32108 trajo consigo que se modifiquen las
reglas procesales de la Ley 30077 Ley contra el Crimen Organizado, al dejar fuera de su ámbito
de aplicación a las organizaciones criminales que cometan delitos sancionados con 6 años de
pena privativa de la libertado menos, así como a aquéllas organizaciones criminales que bus
quen obtener un beneficio distinto al económico, con lo cual se habría derogado tácitamente
el artículo3de la Ley 30077 antes anotado, excluyéndose desuám bitodeaplicación un núme
ro importante de delitos que no cumplirían con dichos estándares, entre ellos, una cantidad
importante de delitos contra la administración pública.
