años para el delito de o rg a n iz a c ió n c r im in a l, mientras que la norma actual señalaque la pena
será « ig u a l o m a y o r» a cinco años.
Asimismo, la presente ley sostiene explícitamente que se considera como organización crim i
nal a los grupos que ejerzan determinados delitos con una finalidad patrimonial «Se considera
organización crim inal a todo grupo (...) compuesto portres o más personas (...) para la comisión de delitos
de extorsión, secuestro, sicariatoy otros delitos (...) con el fm de obtener, directa o indirectamente, un
beneficio económico u otro de orden material.»
6.3. Integrantes
Según el tipo penal, para que se cometa el delito de organización criminal se requiere, como
mínimo, que esté conformada por tres miembros, entre los cuales se repartan tareas o funcio
nes; pero no bastará probar la pluralidad de miembros para encontrarnos frente a una organi
zación crim inal,ya que este elemento es uno de otros más que establece la ley.
Por otro lado, es importante diferenciar a quienes tengan la calidad de líder, jefe, financista
o dirigente de la organización criminal, pues estos tendrán una pena mayor respecto de los
demás integrantes.
El líder actúa como guía y posee amplias facultades de orientación, conducción y coordina
ción de las actividades delictivas del grupo; por lo general conducen organizaciones que se
dedican a cometer del ¡tos de alta especial ización. El jefe, por su parte, es un órgano intermedio
que se encuentra subordinado al poder central del dirigente, pero posee autonomía a nivel
operativo dentro de la organización; tiene control sobre la ejecución de las acciones delictivas
que deben cum plir quienes están bajo su mando. El financista, es un gestor especial izado y de
confianza encargado de proyectar, procurar, suministrar o administrar los recursos financieros
y logísticos que requiera la organización para poder operar. El dirigente es un órgano central
que tiene poder al interior de la organización y ejerce posición de mando; define y ordena las
actividades de los integrantes de modo directo y vertical.
6.4. Estructura y tareas entre los m iem bros
El artículo 317o del Código Penal no define cómo tiene que ser la estructura de una organización
criminal, por lo que hay organizaciones con estructuras altamente jerarquizadas, así como tam
bién estructuras flexibles que buscan adaptarse a esquemas corporativos horizontales.
Según el Acuerdo Plenario N° o i-z o i7-SPN, para la configuración del delito autónomo de or
ganización criminal, si bien el tipo penal vigente artículo 317o del Código Penal— modificado
por el Decreto Legislativo N°i244— no asume la existencia de una estructura criminal, esta si
es asumida en la agravante del artículo segundo de la Ley N° 30077, a la luz del tratado inter
nacional de la Convención de Palermo y en concordancia con el Acuerdo Plenario de la Corte
Suprema número 004-2007/CJ116, la configuración de una organización criminal necesita de
una estructura, la cual proviene de los elementos normativos de reparto de tareas o roles así
como de la propia exigencia de organización el actuar de manera organizada. Esto es, el con
cepto “organización” denota una estructura funcional.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 941 of 1506 --

Tema 6: Temas de la Especialidad Penal
Los elementos de la estructura de la organización criminal son: i. Elemento personal: Esto es,
que la organización esté integrada por tres o más personas. 2. Elemento temporal: El carácter
estableo permanente de la organización crim inal.3. Elemento teleológico-, Correspondeal desa
rrollo futuro de un programa criminal. 4. Elemento funcional: La designación o reparto de roles
de los integrantes de la organización criminal. 5. Elemento estructural: Como elemento norma
tivo que engarzay articula todos los componentes.
La estructura se analiza en función de las actividades de la organización, se infiere a través de
las labores conjuntas de los integrantes, pues a partir de ello es posible inferir la existencia de
la estructura. La estructura implica nivel de coordinación entre unoy otro. No se configura una
organización criminal solo porque exista actuación conjunta para la comisión de un delito, es
claro que el elemento estructural es imprescindible.
En conclusión, una organización criminal puede presentar una estructura vertical, horizontal
y funcionalmente adoptar otras formas flexibles, como cuando se usan las estructuras de las
sociedades anónimas. En ese orden, la organización criminal necesita una estructura adecua
da al fin delictivo.
6.5. Temporalidad
Según lo señalado en el artículo 317o del Código Penal, se considera organización criminal a
todo grupo con compleja estructura desarrol laday mayor capacidad operativa compuesto por
tres o más personas con carácter permanente o por tiempo indefinido.
6.6. Finalidad
Conforme lo menciona el tipo penal, el propósito de la organización criminal es la de cometer
delitos, por lo que no será necesario que la organización cometa crímenes para poder sancio
narlos. Se trata de un delito de peligro abstracto destinado a reprimir comportamientos cri
minológicos, para así evitar poner en peligro bienes jurídicos tutelados por el Derecho Penal;
es una figura de adelantamiento de la intervención penal, porque castiga un ámbito previo a
la comisión de delitos.
6.7. Conductas sancionadas por el tip o penal
Las conductas punibles en el delito de organización criminal son: constituir, organizar o inte
grar una organización criminal.
“C onstituir” supone dar nacimiento formal a la estructura criminal de la organización; es parti
cipar en el acto fundacional que define la composición funcional, los objetivos, las estrategias
de desarrollo, la forma de operar,y las acciones inmediatas y futuras de la organización.
“O rganizar"conlleva a dirigir, diseñary proporcionar una estructura funcional y operativa a la
organización ya constituida.
“Integrar”, finalmente, comprende cualquier acto de adhesión personal y material a una es
tructura preexistente; la persona que integra una organización criminal se somete a los pro
pósitos de la organización, comprometiéndose, de manera expresa o implícita, a realizar las
tareas que le sean asignadas.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 941

-- 942 of 1506 --

UBILEX
6 . 8 . D if e r e n c ia s con e l delito d e b a n d a c r i m i n a l
Los tipos delictivos de organización criminal y banda criminal tienen el mismo bien jurídico
vulnerado. Están contemplados en el C ap ítu loide l Título XIV del Libro Segundo del Código
Penal: “Delitos contra la paz pública”. En pureza, en ambos delitos se parte de la noción de
seguridad, entendida como una situación de ausencia de riesgo, de intrínseca peligrosidad
en el desarrollo de las relaciones entre personas e instituciones, cuya tutela corresponde al
Estado. La organización crim inaly la banda criminal se convierten en un instrumento criminal
cualificado, de ahí la utilización más intensa del Derecho penal.
Las diferencias entre ambos tipos delictivos, que tienen el mismo bien o interés jurídico tute
lado, se sustentan en el menor nivel y complejidad de la estructura organizacional y en la na
turaleza de los delitos instrumentales que comprende el plan criminal, lo que es más claro con
la nueva Ley 32108, de 9 de agosto de 2024, en cuya virtud la órbita de la organización criminal
incide, mediante los delitos que comete, en la obtención, directa o indirecta, del control de
la cadena de valor de una economía o mercado ilegal para obtener un beneficio económico,
mientras que el delito de banda criminal se circunscribe a delitos de despojo. Así, entonces, el
delito de banda criminal es menos complejo y, por ello, está sancionado con una pena menor
(de cuatro a ocho años de privación de libertad). Recurso Casación N° 566-2024/La Libertad.
Fj-4 -
7. DELITOS CONTRA EL PATRIMONIO
7.1. Delito de hurto simple
Descripción normativa:
"Art. 185.-El que, para obtener provecho, se apodera ilegítimamente de un bien mueble, total o parcial
mente ajeno, sustrayéndolo del lugar donde se encuentra, será reprimido con pena privativa de libertad
no menor de uno ni mayor de tres años. S e equiparán a bien mueble la energía eléctrica, el gas, los
hidrocarburos o sus, productos derivados, el agua y cualquier otra energía o elemento que tenga valor
económico, así como el espectro electromagnético y también los recursos pesqueros objeto de un
mecanismo de asignación de Límites Máximos de Captura por Embarcación." :
B ien ju ríd ic o protegido: Patrimonio. Se tutela indirectamente la propiedad sobre el patrim o
nio mueble e indirectamente de la posesión de bien mueble, el fundamento de este hecho
se desprende de la literalidad de la norma, que exige ajenidad de la cosa objeto del apodera-
miento delictivo.
T ip ic id a d o b je tiva:
El hurto es el apoderamiento o sustracción por lo que debe tratarse de un objeto que pueda
ser desplazado de un lugar a otro, es decir un bien mueble, para que se produzca este delito es
necesario que no exista violencia.
El apoderamiento es el elemento central para determinarsi estamos ante un delito consuma
do o una tentativa de hurto. El apoderamiento importa:
a) El desplazamiento físico de la cosa del ámbito del poder patrimonial del tenedor-de su
esfera de posesión- a la del sujeto activo; y,
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 943 of 1506 --

Tema 6: Temas de la Especialidad Penal
b) La realización material de actos posesorios, de disposición sobre la misma.
El hurto es un delito de resultado (se requiere el apoderamiento).
Sujeto activo: puede ser cualquier persona que no sea el dueño de la cosa mueble hurtada.
S u je to pasivo: es cualquier persona, incluyendo la jurídica propietaria o poseedora de la cosa.
T ip ic id a d su b je tiv a : El tipo además de dolo genérico de entender que se toma cosa total o
parcialmente ajena y querer que ello ocurra exige un elemento subjetivo del tipo, a saber, el
ánimo de lucro venido con la locución para obtener provecho que comprende la idea o propó
sito de conservar la cosa. El ánimo de lucro ha sido definido como la intención de obtener una
ventaja patrimonial directa como correlato del apoderamiento de las cosas ajenas.
C o n su m a ció n : Cuando el titu la r del bien deja de tenerlo en el ámbito de su protección y, por
consiguiente, cuando el agente pone a la cosa bajo su poder de hecho, esto se manifiesta en la
posibilidad de realizar actos de disposición sobre el bien, aun cuando sea por breve termino,
es decir cuando tenga el “potencial” ejercicio de facultades de dominio.
En consecuencia:
Si hubo posibilidad de disposición, y pese a ello se detuvo al autory recuperó en su inte
gridad el botín, la consumación ya se produjo;
Si el agente es sorprendido infraganti o in situ y perseguido inmediatamente y sin inte
rrupción es capturado con el íntegro del botín, así como si en el curso de la persecución
abandona el botín y éste es recuperado, el delito quedó en grado de tentativa; y,
Si perseguidos los participantes en el hecho, es detenido uno o más de ellos pero otro u
otros logran escapar con el producto del hurto, el delito se consumó para todos.
7.2. Delito de hurto agravado
Descripción normativa:
"Art. 186, Hurto agravado: El agente será reprimido con pena privativa de libertad no menor de tres ni
mayor de seis años si el hurto es cometido:
1. Durante la noche.
2. Mediante destreza, escalamiento, destrucción o rotura de obstáculos.
3. Con ocasión de incendio, inundación, naufragio, calamidad pública o desgracia particular del agraviado.
4. Sobre los bienes muebles que forman el equipaje del viajero.
5. Mediante el concurso de dos o más personas. ,
L a pena será no menor de cuatro ni mayor de ocho años si el hurto es cometido:
1. En inmueble habitado.
2. Por un agente que actúa en calidad de integrante de una organización destinada a perpetrar estos delitos,
3. Sobre bienes de valor científico o que integren el patrimonio cultural de la Nación,
4. Mediante la utilización de sistemas de transferencia electrónica de fondos, de la telemática en general o la
violación del empleo de claves secretas (Numeral derogado) . .
5. Colocando a la víctima o a su familia en grave situación económica.
6. Con empleo dé materiales o artefactos explosivos para la destrucción o rotura de obstáculos.
7. Utilizando el espectro radioeléctrico para la transmisión de señales de telecomunicación ilegales.
