7.3. Delito de robo
Descripción normativa:
“Artículo 188 C.P.- El que se apodera ilegítimamente de un bien mueble total o parcialmente ajeno,
para aprovecharse de él, sustrayéndolo del lugar en que se encuentra, empleando violencia contra la
persona o amenazándola con un peligro inminente para su vida o integridad física será reprimido con
pena privativa de libertad no menor de tres ni mayor de ocho años."
B ien ju ríd ic o protegido: En el robo se tutela básicamente el patrimonio en su tenencia o pro
piedad sin embargo se trata de un tipo pluriofensivo, en la medida en que la violencia o in ti
midación exigida puede afectara la salud del sujeto pasivo.
T ip ic id a d o b je tiv a :
La conducta típica exige el empleo por el agente de violencia o amenaza contra la persona-no
necesariamente sobre el titu lar del bien mueble-, como medio para facilitar el apoderamien-
to del bien mueble total o parcialmente ajeno, o estar encaminada a vencer la resistencia de
quien se opone al apoderamiento. En consecuencia, la violencia es causa determinante del
desapoderamiento y está siempre orientada a neutralizar o impedir toda capacidad de actua
ción anterior o de reacción concomitante de la víctima que pueda obstaculizar la consuma
ción del robo114. Por otro lado, loque determina la consumación del delito es la disponibilidad
del autorsobre lo sustraído siquiera sea por un breve lapso.
S u je to activo, será cualquier persona incluyendo el copropietario.
S u je to pasivo, será cualquier persona incluyendo al copropietario, pero no la persona jurídica
quien por su índole no puede ser objeto de la violencia física o intimidación que reclama al
tipo.
T ip ic id a d su b je tiv a : La figura delictiva del robo solo resulta repri mi ble a título de dolo, con-
ciencia y voluntad de realización típica, el autor dirige su conducta a desapoderar a la victima
de sus bienes muebles mediando violencia físicay/o amenaza de peligro inminente para su
vida o integridad física.
114 S A L I N A S S IC C H A , R a m ir o , op. cit, p p. 9 0 7 - 9 1 0 .
944 BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 945 of 1506 --

Tema 6: Temas de la Especialidad Penal
Al igual que el hurto el autor debe ser consciente de la ajenidad del bien por lo que podría
darse un error de tipo que si es invencible no implica la impunidad de la conducta, pues el des
pliegue de los medios violentos seria desplazados a los tipos penales de coacción o lesiones.
7.4. Delito de robo agravado
Descripción normativa:
"MJ89 C.P..- La pena será no menor de doce ni mayor de veinte años si el robo se comete: i
7. En inmueble habitado.
•Durante la noche o en lugar desolado:.
A mano armada.
4. Con el concurso de dos o más personas.
5. En cualquier medio de locomoción de transporte público o privado de pasajeros o de carga, terminales
terrestres, ferroviarios, lacustres y fluviales, puertos, aeropuertos, restaurantes y afínes, establecimientos de
hospedaje y lugares de alojamiento, áreas naturales protegidas, fuentes de agua minero-medicinales con fines
turísticos, bienes inmuebles integrantes del patrimonio cultural de la Nación y museos.
6. Fingiendo ser autoridad o servidor público o trabajador del sector privado o mostrando mandamiento falso ■
de autoridad.
7. En agravio de menores de edad, personas con discapacidad, mujeres en estado de gravidez o adulto mayor.
8. Sobre vehículo automotor, sus autopartes o accesorios.
9. Sobre equipo terminal móvil, teléfono celular, equipo o aparato de telecomunicaciones, red o sistemas de
telecomunicaciones u otro bien de naturaleza similar, '' '' ‘ ■
La pena será no menor de veinte ni mayor de treinta a ñ o s s i el robo es cometido:
7, Cuando se cause lesiones a la integridad física o mental de la víctima,
2. Con abuso de la incapacidad física o mental de la víctima o mediante el empleo de drogas, insumos quími
cos o fármacos contra la víctima:
3. Colocando a la víctima o a su familia en grave situación económica,
4. Sobre bienes de valor científico o que integren el patrimonio cultural de la Nación,
5. Si la agravante descrita en el numeral 9 del primer párrafo se realiza mediante el empleo de material o
artefacto explosivo.
6. Si la agravante descrita en el numeral 9 del primer párrafo se realiza mediante el uso de vehículos motorizados.
La pena será de cadena perpetua cuando el agente actúe en calidad de integrante de una organización crimi
nal, o si, como consecuencia del hecho, se produce la muerte de la víctima o se le causa lesiones graves a su
integridad física o mental.
7.5. Delito de estafa
Descripción normativa:
"Art. 796 C.P.- El que procura para sío para otro un provecho ilícito en perjuicio de tercero, induciendo
o manteniendo en error al agraviado mediante engaño, astucia, ardid u otra forma fraudulenta, será
reprimido con pena privativa de libertad no menor de uno ni mayor de seis años."
B ien ju ríd ic o protegido: El bien jurídico protegido por esta figura penal se encuentra consti
tuido por los distintos elementos o componentes del patrimonio, ya sean componentes ma
teriales o inmateriales, muebles o inmuebles; y no como todos los elementos de éste conce
bidos como un todo115.
115 Vives Antón. T.S.; Boix Reig, ].; Orts Berenguer, E.; Carbonell Mateu, J.C.; y Conzales Cusac, J.L. Derecho Penal:
