BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 946 of 1506 --

UBILEX
T ip ic id a d objetiva: El delito de estafa, presupone en su vertiente objetiva, la concurrencia
de cuatro hechos vinculados a título de causa-efecto: (i) el sujeto activo ha de desplegar un
engaño (mise in scene); que (ii) cree en el agraviado una situación de error; a consecuencia del
cual éste ha de efectuar (iii) una disposición patrimonial; lo que (iv) le representa un perjuicio
económico, a la vez que un beneficio para el autor del delito.
En ese mismo sentido, se ha pronunciado la Sala Penal de la Corte Suprema de justicia en la
ejecutoria recaída en el R.N. N° 8023-1997-Uma, a saber: «Que, los delitos de estafa, en su aspecto
objetivo, requieren necesariamente la existencia de cuatro elementos que constituyen su estructura típi
ca, estos són-, “el engaño, el error, la disposición patrim onial y el perjuicio económico, entre los cuales ha
de existir una relación de antecedente a consecuente”» "6.
En cuanto al “engaño típico”, este elemento objetivo ha sido ampliamente analizado por la doc
trina nacional,)/ ha sido identificado como una «desfiguración de lo verdadero»"7, «artimaña», «arbitrio
falso»,«encubrimiento de la verdad», «simulación» o «maquinación»"8. En otras palabras, el engaño cons
tituye cualquier tipo de ardid, maniobra, mendacidad, fabulación o artificio del agente empleado
para aprovecharse de la disposición patrimonial de un tercero, ocasionándole un perjuicio.
Luego de verificarse que el agente ha desplegado una conducta fraudulenta mediante el uso
del engaño, corresponde verificar si dicho ardid han inducido a “erro r” a la víctima (falsa re
presentación de la realidad).
En cuanto a la “d isposición p a trim o n ia l”, este comportamiento es definido como toda acción u
omisión que implique un desplazamiento patrimonial, que podrá tener la forma de una entre
ga, cesión o prestación de un bien, derecho o servicio116117118119. Cabe resaltar que la disposición patri
monial efectuada de forma voluntaria por la víctima no niega la conducta delictiva del agente,
sino que, por el contrario, confirma la ocurrencia de la misma como consecuencia del engañoy el
estado de erraren el que se induce a la víctima, tal como lo señala nuestra jurisprudencia: «Res
pecto al delito de estafa se debe tener en consideración que lo que se reprocha al agente es conseguir que
el propio agraviado le traslade a su esfera de dominio su propio patrimonio, es decir, el aspecto objetivo
de este delito requiere que el agente obtenga un provecho ilícito, para lo cual debe mantener en error al
agraviado por medio del engaño, astucia o ardid.»120
El “ perjuicio” consistirá en un perjuicio estimable económicamente en base a una concepción
del patrimonio como todo aquel bien con relevancia económica121. El “b e n e ficio ilícito ” del
sujeto activo tiene como contrapartida el perjuicio patrimonial del sujeto pasivo del delito, en
