bien tenga122.
Tip icid ad sub jetiva: En cuanto al elemento subjetivo, el delito de estafa requiere que el sujeto
activo actúe con “dolo” (conocimiento y voluntad) de querer realizar los elementos objetivos
anteriormente mencionados, es decir, el elemento subjetivo del tipo está conformado por el
dolo empleado por el autor, el cual se manifiesta en el conocimiento que éstos poseen sobre
el carácter fraudulento de su comportamiento123.
Además el delito exige un elemento subjetivo adicional dado el carácter patrimonial del
mismo, que es conocido como el “ánimo de lucro”, que en esta clase de delitos es definido en
términos muy amplios, como la intención de obtener en beneficio del sujeto activo o de un
tercero un enriquecimiento.
Modalidades agravadas:
“Art. 196-A. Estafa agravada
La pena será privativa de libertad no menor de cuatro ni mayor de ocho años y con noventa a dos-;
cientos días-multa, cuando la estafa:
7. Se cometa en agravio de menores de edad, personas con discapacidad, mujeres en estado de ;
gravidez o adulto mayor.
2. Se realice, con la participación de dos o más personas.
3. Se cometa en agravio de pluralidad de victimas.
4. Se realíce con ocasión de compra-venta de vehículos motorizados o bienes inmuebles.
5. Se realice para sustraer o acceder a los datos de tarjetas de ahorro o de crédito, emitidos por el sistema
financiero o bancario.
6. Se realice con aprovechamiento dé la situación de vulnerabilidad de lavíctim a.''í
7.6. Delito de extorsión
Descripción normativa:
“Art. 200 C.P.- El que mediante violencia o amenaza obliga a una persona o a una institución pública o
privada a otorgar al agente o a un tercero una ventaja económica indebida u otra ventaja de cualquier ¡
otra índole, será reprimido con pena privativa de libertad no menor de diez ni mayor de quince años. .
La misma pena se aplicará al que, con la finalidad de contribuirá la comisión del delito dé extorsión,
suministra información que haya conocido por razón o con ocasión de sus funciones, cargo u oficio o propor
ciona deliberadamente los medios para la perpetración del delito.
El que mediante violencia o amenaza, toma locales, obstaculiza vías de comunicación o impide el libre trán-
sito de la ciudadanía o perturba el normal funcionamiento de los servicios públicos o la ejecución de obras
legalmente autorizadas, con el objeto de obtener de las autoridades cualquier beneficio o ventaja económica
indebida u otra ventaja de cualquier otra índole, será sancionado con pena privativa de libertad no menor d e ;
cinco ni mayor de diez años.
El funcionario público con poder de decisión o el que desempeña cargo de confianza o de dirección que, contra
viniendo lo establecido en el artículo 42 de la Constitución Política del Perú, participe en una huelga con el objeto
de obtener para sí o para terceros cualquier beneficio o ventaja económica indebida u otra ventaja dé cualquier
otra índole, será sancionado con inhabilitación conforme a los incisos 7 y 2 del artículo 36 del Código Penal.
122 SALINAS SICCHA, Ramiro. Op. Cit. p.1061.
123 QUINTERO OLIVARES, Gonzalo (Director). Op. cit. p. 517.
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 948 of 1506 --

UBILEX
La pena será no menor de quince ni mayor de veinticinco años e inhabilitación conforme a los numerales 4 y 6
del artículo 36, si la violencia o amenaza es cometida:
a) A mano armada, o utilizando artefactos explosivos o incendiarios.
b) Participando dos o más personas; o,
c) Contra el propietario, responsable o contratista de la ejecución de una obra de construcción civil pública
o privada, o de cualquier modo, impidiendo, perturbando, atentando o afectando la ejecución de la misma.
d) Aprovechando su condición de integrante de un sindicato de construcción civil.
e) Simulando ser trabajador de construcción civil.
f) Mediante el empleo de imágenes del entorno familiar, empresarial, laboral o social, u objetos perturbadores
de peligrosidad, entregados, exhibidos, difundidos directa o indirectamente por cualquier medio a la víctima.
Si el agente con la finalidad de obtener una ventaja económica indebida o de cualquier otra índole, mantiene en
rehén a una persona, la pena será no menor de veinte ni mayor de treinta años.
La pena será privativa de libertad no menor de treinta años, cuando en el supuesto previsto en el párrafo
anterior:
a) Dura más de veinticuatro horas.
b) Se emplea crueldad contra el rehén.
c) El agraviado ejerce función pública o privada o es representante diplomático.
d) El rehén adolece de enfermedad grave.
e) Es cometido por dos o más personas.
f) Se causa lesiones leves a la víctima.
La pena prevista en el párrafo anterior se impone al agente que, para conseguir sus cometidos extorsivos, usa
armas de fuego o artefactos explosivos.
La pena será de cadena perpetua cuando:
a) El rehén es menor de edad o mayor de setenta años.
b) El rehén es persona con discapacidad y el agente se aprovecha de esta circunstancia.
c) Si la víctima resulta con lesiones graves o muere durante o como consecuencia de dicho acto.
d) El agente se vale de menores de edad."
Bien jurídico protegido: Tratándose de un delito pluriofensivo; son dos los bienes que se tu
telan: La libertad ambulatoria de la persona (delito-medio), y el Patrimonio (delito-fin). En
efecto, la extorsión se protege el patrimonio de modo adjetivado, no la mera tenencia o po
sesión de la cosa, sino el ejercicio en general de determinados actos. El ataque a la libertad es
inmediato y directo, se produce con el empleo de la intimidación o como efecto lógico de las
violencias practicadas o cuyo ejercicio se anuncia.
Tipicidad objetiva: Sujeto activo: Cualquier persona que obliga a la víctima a entregar una
cosa o suma de dinero por medio de violencia, intimidación o secuestro con la finalidad de
obtener un provecho ilícito para sí o para tercero.
Sujeto pasivo: Cualquier persona que es víctima de los abusos antes mencionadosy en la cual
el sujeto activo provoca tal presión que este se ve obligado a la entrega del bien.
El delito de extorsión consiste en obligara una persona a otorgar al agente o a un tercero, una
ventaja económica indebida, mediante violencia o amenaza o manteniendo como rehén al
sujeto pasivo u otra persona y se consuma cuando el sujeto pasivo cumple con entregar be
neficio económico indebidamente ilícito. Para la materialización de este delito de extorsión
confluirán los siguientes elementos objetivos:
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 949 of 1506 --

lema 6: Temas de la Especialidad Penal
a) Violencia o am en aza sobre la víctim a: Es decir, la “vis absoluta” o la “vis compulsiva”. En
ambos casos, la víctima es secuestrada para recibir dinero posteriormente La violencia, es
la fuerza física irresistible que se ejerce en la persona del sujeto pasivo. Sobre la amenaza,
que puede recaer en la víctima o en un tercero con la finalidad de que se perpetre el delito.
Bajo la idoneidad de la amenaza se obliga a la víctima a ser conducido a otro lugar para
ser mantenido como rehén.
b) Mantener en rehén a una persona violentada o am enazada y privada de su libertad ambu
latoria: contra la voluntad de la víctima, se le mantiene en rehén, se le priva de su liber
tad ambulatoria, es decir, la libertad de poder ir voluntariamente de un lugar a otro sin
ningún obstáculo. Una persona es mantenida como rehén cuando, por cualquier medio
y por cualquier forma se encuentra en poder de un tercero, ilegítimamente privada de su
libertad personal, como medio intim idatorio para sacar rescate.
c) Ventaja económ ica ilícita a favor del agente: esta es la nota distintiva con el delito de
secuestro, el actor no tiene otro objetivo que el de conseguirá toda costa un provecho pa
trim onial indebido. No interesa que sea necesariamente dinero, puede tratarse de bienes
(como electrodomésticos, o un automóvil, etc).
El concepto de ventaja pecuniaria tiene su representación más general y objetiva en el dinero
que se obliga a entregaren provecho del malhechor. Comprende también cualquier mueble o
inmueble, que tenga su equivalente en dinero.
Tip icid ad sub jetiva: La comisión del delito de extorsión es a título de dolo, es decir, conciencia
y voluntad para exigir la disposición patrimonial, a pesar de conocer su ilicitud.
Consum ación: Se da la consumación de este delito cuando la víctima pone a disposición del
agente las cosas. Este delito se consuma cuando el extorsionado otorga una ventaja indebida,
es decir basta con el desprendimiento, sin necesidad de que se produzca el efectivo apodera-
miento ni en consecuencia, el beneficio único.
No hay inconveniente en adm itir la tentativa, la cual se daría en tanto se produzca el despren
dimiento económico.
Agravantes:
Se han señalado hasta seis hipótesis agravatorias para la imposición de pena privativa de li
bertad no menor de doce ni mayor de veinte años.
a) El rehén es m enor de edad: Es decir el rehén tiene menos de 18 años de edad, de acuerdo
al Código Civil. Se justifica su agravación porque no tiene la madurez necesaria, pues, lo
que tiene que pasar por esto, implica un resquebrajamiento en su integridad psico-física.
b) El secuestro dura m ás de cinco días: El legislador ha puesto como límite de cinco días,
pasado ello, se agrava el delito básico, debido a que mientras más dure, más va a ser el
daño que se ocasione al rehén y desventura o preocupación para sus seres queridos.
c) Se em plea crueldad contra el rehén: No es necesario ejercer violencia o amenaza al re
hén, puesto que ya es suficiente con que se encuentre privado de su libertad, pese a ello el
agente maltrata psicológicay físicamente al rehén, siendo innecesario esto.
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 950 of 1506 --

d) El secuestrado ejerce función pública: Significa que la víctima es un funcionario público,
que tiene alguna representatividad de una persona jurídica estatal, de ahí, su agravación
atendiendo a la calidad del sujeto pasivo.
e) El rehén es inválido o adolece de enferm edad: Lo común es que el sujeto pasivo sea
una persona física integra que no adolezca enfermedad alguna. Pero cuando el delito de
extorsión recae sobre personas especiales, por su invalidez o enfermedad, entonces, se
agrava. Se justifica su agravación, porque el agente se aprovecha de estas personas, que
no opondrán ninguna resistencia, para perpetrar su actuar delictuoso. Eso no es todo, el
actor» ni siquiera ha tenido en consideración la condición enfermiza de la víctima, pese a
ello lo realiza, causando preocupante alarma en la sociedad.
f) Es cometido por dos o m ás personas: Es frecuente que la comisión de este delito sea
realizada y ejecutada por más de dos personas, pues de esta forma, se asegura la con
sumación del tipo penal. No interesa si actúan organizados o no, en banda o no, basta la
participación de más de dos personas para que se agrave la figura básica.
7.7. Delito de apropiación ilícita
Descripción normativa:
"Art. 190 C.P.- El que, en su provecho o de un tercero, se apropia indebidamente de un bien mueble, una
suma de dinero o un valor que ha recibido en depósito, comisión, administración u otro título seme
jante que produzca obligación de entregar, devolver, o hacer un uso determinado, será reprimido con
pena privativa de libertad no menor de dos ni mayor de cuatro años.
Si el agente obra en calidad de curador, tutor, albacea, síndico, depositario judicial o en el ejercicio de una
profesión o industria para la cual tenga título o autorización oficial, la pena será privativa de libertad no menor
de tres ni mayor de seis años.
Cuando el agente se apropia de bienes destinados al auxilio de poblaciones que sufren las consecuencias de
desastres naturales u otros similares la pena será privativa de libertad no menor de cuatro ni mayor de diez años.
Cuando el agente se apropia, desvía o dispone indebidamente en todo o en parte, confines propios o de ter
ceros, los aportes destinados a la constitución, formación, consolidación o desarrollo de un fondo pensionario
o del seguro social de salud, la pena será privativa de libertad no menor de dos ni mayor de cuatro años; si el
agente tiene la calidad de servidor público, la pena será no menor de tres ni mayor de seis años y la Inhabilita
ción a que se refieren los incisos I 2 y 8 del artículo 36.
Bien jurídico protegido: El patrimonio.
Tip icid ad ob jetiva: De la lectura del tipo penal se concluye que la conducta delictiva de apro
piación ilícita o indebida se configura cuando el agente con la finalidad de obtener un prove
cho patrimonial para sí mismo o para un tercero, se apropia, adueña, adjudica o apodera de
un bien mueble, dinero o un valor que ha recibido del sujeto pasivo en calidad de depósito,
comisión, administración u otro título semejante que produzca obligación de entregar, devol
ver o hacer un uso determinado del bien.
a) Bien m ueble: El objeto material del delito siempre será un bien mueble, dinero o un valor
que lo represente. Se entiende por bien mueble a toda cosa con existencia real y con valor
patrimonial para las personas, susceptibles de ser transportadas de un lugar a otro ya sea
porsi mismas (animales) o por voluntad del hombre utilizandosu propia m anoo instru-
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 951 of 1506 --

Tema 6: Temas de la Especialidad Penal
mentos mecánicos o electrónicos. Por ejemplo, no se configura la apropiación ilícita si el
agente se apodera de una casa (bien inmueble).
b) Apropiación indebida: La conducta esencial que debe desarrollar el agente lo constituye
la “apropiación”, es decir, la conducta por la cual el agente se apodera, adueña o adjudica
a su favor un bien mueble que no le pertenece legalmente. Esto es, el agente en forma
ilegal, ilícita o indebida coloca dentro de su patrimonio un bien mueble que sabe perfec
tamente le pertenece a otro, quien por título lícito le confió por un tiempo determinado.
Se evidencia el apoderamiento cuando el agente comienza a realizar actos de disposición
del bien como si fuera realmente su dueño o propietarioy se resiste a devolverlo o entre
garlo ante el requerimiento del sujeto pasivo.
En ese sentido, para estar ante una acción típica de apropiación ilícita debe evidenciarse
que el agente quiere la cosa para sí, quiere adueñarse del bien. En doctrina es común
identificar a esta circunstancia como el animus rem sibi habendi que debe guiar al autor de
la conducta, por ejemplo, si el agente quiere solo usar el bien, así sea de modo ilícito, no
se configurará el delito de apropiación ilícita.
En efecto, si en una conducta por la cual el agente se niega a entregar o devolver los bienes
muebles recibidos, no aparece el animus rem sibi habendi, el delito de apropiación ilícita
no se configura. Al respecto se ha pronunciado la jurisprudencia al señalar que: «si bien
en autos se ha acreditado la retención de bienes, sin embargo, los hechos no configuran el delito de
apropiación ilícita, toda vez que no ha quedado probado que el sujeto activo en su condición legal de
representante de la empresa transportista se haya aprovechado, dando uso o dispuesto de la mer
cadería-, de lo que se infiere es que su conducta careció del especial animus rem sibi habendi, que
caracteriza este ilícito patrim onial, es decir, el ánimo de hacer las veces de propietario, sin reunir
semejante condición, siendo evidente que tomó tal actitud con el único propósito de asegurarse el
pago de los fletes devengados.»
Teniendo claro este últim o aspecto, el juez no podrá calificar como apropiación ilícita
cuando una persona designada como depositario retiene el bien hasta que el depositan
te le pague lo que le debe en razón del contrato según lo dispuesto por el Código Civil. O,
cuando una persona hace efectivo lo previsto en el art. 56o del Ley de Garantía Mobiliaria,
el mismo que reconoce al acreedor que recibió en garantía un bien inmueble en garantía
de una obligación, el derecho de retener el bien recibido en garantía en tanto no han sido
íntegramente pagados el capital e intereses y reembolsados los gastos relativos a la deu-
day a la conservación del bien.
c) Que el bien haya sido recibido m ediante título que produzca la obligación de entregar,
devolver o hacer un uso determ inado:
El agente recibe el bien mueble lícitamente o por título legítimo de parte del sujeto pasivo
o víctima, verificándose el delito cuando después aquel se resiste a devolverlo, entregarlo
o hacer un uso determinado del bien.
Los títulos legítimos o lícitos por los cuales el agente recibe el bien mueble han sido indi
cados por el legislador en el mismo tipo penal, tales como el depósito, comisión, adminis-
BALOTARIO DESARROLLADO PARA LOS EXAMENES ESCRITOS DE SELECCION
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 952 of 1506 --

UBILEX
tración y otros títulos semejantes que produzcan en el agente la obligación de entregar,
devolver o hacer un uso determinado del bien.
Los títulos lícitos otorgan al agente posesión o custodia temporal del bien mueble, luego
del cual deben ser devueltos a quien los entregó o entregara la persona que corresponda.
Si la devolución o entrega no se produce ante el requerimiento, el delito aparece. Por el
contrario, si el título por el cual se recibió el bien mueble, dinero o valores no indica clara
mente la obligación de devolver o entregar, el delito de apropiación ¡lícita no se configura
ante la negativa del agente a devolver o entregar.
Depósito: mediante este título la víctima entrega el bien lícitamente al agente para
que lo custodie con la obligación de devolverlo cuando lo solicite el depositante o
entregarlo a un tercero. En ese sentido, el delito se configura cuando el agente ante la
solicitud de devolución de parte del depositante, se niega a hacerlo, o ante el reque
rimiento del depositante para que se entregue el bien a la persona a cuyo nombre se
hizo o destinó el depósito, se resiste.
Adm inistración: la situación jurídica se produce cuando una persona recibe bienes
muebles para administrarlo en beneficio del propietario del bien o de un tercero.
En ese mismo sentido, se ha pronunciado laSala Penal de la Corte Suprema de justicia en
la ejecutoria recaída en el R.N. N ° io í7-201 z-Callao, a saber:
[En] el delito de apropiación ilícita, hay que distinguir dos momentos: uno constituye en la trans-
misión legítima de la posesión de la cosa con título que produzca la obligación de entregarla
-jJB É flL r- o devolverla, y otro de apropiación antijurídica por parte del poseedor legítimo, acaeciendo la
H jflR H j infracción penal en este segundo momento; en el caso de autos, se advierte que se trata de
. bienes que no fueron entregados por título que produzca obligación de entregar o devolver, sino
más bien de retención de bienes con el único propósito de resolver el posible incumplimiento
de pago en el proceso de indemnización que se le seguía al encausado en la vía civil, respecto
a lo cuál las partes han arribado a un acuerdo sobre cancelación de la pretensión indemnizatoria de lo que se
infiere que el encausado [en su calidad de depositario judicial] no hizo la cosa suya, es decir, no se comprobó
como sí fuera dueño, disponiendo de ella en calidad de propietario, sino que retuvo los bienes de propiedad
de su empresa con la finalidad de evitar perjuicio a su representada, ya que la tenía prendada a una entidad .
-bancada, por ello, nos encontrábamos ante falta de tipicidad objetiva, ya que no se verifica una conducta de
-apropiación en sentido estricto, infringiéndose que no concurren los elementos objetivos y subjetivos del tipo
penal previsto en el artículo 190''del Código Penal,"
d) Provecho propio o de un tercero:
Otro elemento objetivo de tipicidad del delito de apropiación ilícita lo constituye el prove
cho indebido propio o de un tercero que busca obtener el agente con su conducta ilícita.
Provecho es una ventaja de índole económica que busca el agente al desarrollar su con
ducta de apropiación ilícita de un bien mueble Aquí no se requiere que efectivamente el
agente obtenga el provecho económico, basta con verificar que el agente tuvo el propósi
to de conseguirlo, es decir, ventaja potencial.
Nueva m odalidad: El 08 de julio de 2023 se publicó la Ley N°3i823, norma que agregó un
párrafo al a r tic u ló lo del Código Penal, incorporando una nueva modalidad del delito de
Apropiación Ilícita. Este párrafo señala:
I5 2
BALOTARIO DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 953 of 1506 --

Tema 6: Temas de la Especialidad Penal
Cuando el agente se apropia, desvía o dispone indebidamente en todo o en parte, con fines propios
o de terceros, los aportes destinados a la constitución, formación, consolidación o desarrollo de un
fondo pensionario o del seguro social de salud, la pena será privativa de libertad no menor de dos ni
mayor de cuatro años; si el agente tiene la calidad de servidor público, la pena será no menor de tre s :
ni mayor de seis años y la inhabilitación a que se refieren los incisos 1, 2 y 8 del artículo 36",
La modificación implica que los empleadores que no cumplan con el pago correspon
diente a la AFR ONP o Essalud, al utilizar indebidamente los aportes retenidos de las re
muneraciones de sus trabajadores, enfrentarán sanciones de privación de libertad. De
esta manera, aquellos empleadores que no cumplan con la obligación de realizar los
aportes no solo serán sujetos a una falta administrativa, sino que también cometerán un
delito al destinar dichos aportes a otros fines.
Es importante destacar que el delito requiere el uso de los fondos retenidos en conceptos distin
tos. Por lo tanto, es necesario garantizar la transparencia en el manejo de estos fondos para evitar
interpretaciones que puedan perjudicar a los representantes legales de los empleadores.
Anteriormente, la no entrega de lo recaudado de la remuneración del trabajador destina
do a los fondos pensionarios o seguro social, era considerado una infracción en materia
laboral, por lo que SUNAFIL era el ente encargado de sancionara las empresas que incu
rran en estafada, sumado a los posibles casos que lleguen al Poder judicial. No obstante,
ahora será un delito de apropiación ilícita con pena privativa de la libertad, lo que de
muestra el mayor interés del Estado por proteger al trabajador en el ámbito pensionario.
Tip icid ad sub jetiva: El delito de apropiación ilícita es un delito doloso, es decir, el agente
debe actuar con conocimiento que el bien mueble pertenece a otra personay tiene obli
gación de devolver, entregar o hacer un uso determinadoy sin embargo, voluntariamente
decide apoderarse o apropiarse, negándose a devolver, entregar o darle el uso determ i na
do ante el requerimiento de quien tiene derecho hacerlo.
En la actitud del agente debe prevalecer el cwimus rensibi habendi, es decir, el agente debe
querer adueñarse del bien mueble, dinero o valor sabiendo perfectamente que pertenece
a otra persona. Al respecto, la jurisprudencia ha señalado que: "La conducta esencial que
debe desarrollar el agente está constituida por la apropiación, es decir, por el apodera-
miento o adjudicación a su favor de un bien mueble que no le pertenece legalmente. Eso
implica que el agente en forma ilegal, ilícita o indebida coloca dentro de la esfera de su
patrim onio— bajo su dom inio— un bien mueble que sabe perfectamente que es ajeno,
dado que le pertenece a otro, en su forma clásica, ese otro es quien por título lícito, le
confió el bien por un tiempo y con un fin determinado". Cas. N° 301-2011, Lambayeque.
Fj.5 .5 .
Consum ación: El delito se consuma en el momento que el agente se resiste, se niega o
es renuente a cum plir la obligación de entregar o devolver el bien ante el requerimiento
expreso e indubitable de la persona que tiene derecho a efectuarlo. Solo con la negativa o
resistencia al requerimiento expreso podemos tener convicción que realmente el agente
se ha apropiado del bien. Si no hay petición o requerimiento expreso es imposible sa
ber si el agente tiene el animus rem sibi habendi. Al respecto, la jurisprudencia ha señalado
que: "3.5. En virtud de lo reseñado en el apartado 33 - de este auto de calificación, deberá
entenderse que el momento de consumación del delito se produjo al requerirle la em
