presa agraviada al recurrente la devolución del bien. Adoptar la postura de que el delito
se consuma en el momento de la apropiación no permite distinguirla del delito de hurto
— a menos que el bien haya sido entregado de manera legítima— y tampoco permitiría
probar el dolo del agente." Cas. N° 428-2019, Arequipa.
7 . 8 . Delito de receptación
Descripción normativa:
"Arf. 194 C.R- El que adquiere, recibe en donación, en prenda, guarda, esconde, expone para la venta,
ayuda a negociar, comercializa, desensambla o utiliza, un bien o sus partes de cuya procedencia delic
tuosa tenía conocimiento o debía presumir que provenía de un delito, será reprimido con pena privativa
de libertad no menor de dos ni m ayor de cuatro años y con treinta a noventa días-multa e inhabilitación,
conforme al numeral 4 del artículo 36 del Código Penal,
La misma pena se aplica al que provea documentos para ocultar, encubrir o disimular el origen ilícito de un bien
o sus partes, contribuyendo con las conductas descritas en el párrafo precedente".
Bien jurídico protegido: Se acepta que el bien jurídico que la punición del delito de recepta
ción pretende proteger es el patrimonio, pues el receptador atenta contra el patrimonio ajeno
en la medida en que hace suyos los bienes que pertenecen a otra persona. Ello tiene sentido
con la ubicación sistemática del delito de receptación, que se encuentra incardinado en el
título correspondiente a los delitos contra el patrimonio.
Con todo, el delito de receptación tiende a perjudicartambién, aunque en grado de peligro, la
administración de justicia, en la medida en que la transmisión de mano en mano de un bien
de procedencia delictuosa dificulta que la Justicia pueda identificarlo y restituirlo o decomi
sarlo. Sin embargo, su sim ilitud con el delito de encubrimiento no debe llevar a ser considera
do un delito contra la administración de justicia. En la receptación, sea esta “sustituí iva” o “en
cadena", el sujeto activo vulnera la norma que protege el patrimonio.
T ip icid ad ob jetiva: Las fases para la configuración del delito de receptación son las siguientes:
a) El sujeto activo realiza un aprovechamiento ulterior de los bienes o sus partes que proce
den de un delito en el que no ha participado;
b) Incorpora al circuito económico legal (expone para la venta, ayuda a negociar, comerciali
za, desensambla o utiliza) los bienes o sus partes de procedencia delictuosa;
c) Continúa o perpetúa el perjuicio sufrido por el propietario o titu lar del bien objeto del
primer delito; y,
d) Dificulta o impide lograr la restitución del bien.
Primero, que no solo en los casos de “receptación en cadena”, sino también en los de “recep
tación sustitutiva”, el autor del delito se aprovecha de manera ulterior de los bienes o de sus
partes que proceden de un delito en el que no han participado. Pongamos un ejemplo: Cuan
do el testaferro T compra al funcionario público F las acciones de una sociedad anónima que
este adquirió con dinero que recibió en un cohecho, se puede afirm ar sin problema alguno
que T se aprovecha de los bienes provenientes del delito de corrupción de funcionarios en el
