Tema 6: Temas de la Especialidad Penal
cual no ha participado. Que T no haya adquirido el mismo bien que recibió F no significa que
no cumpla con el primer requisito anotado por el fiscal adjunto supremo, toda vez que el mis
mo fiscal señala que los bienes de los cuales se ha de aprovechar el receptador tienen que ser
provenientes de un delito. Para decirlo en otras palabras, los bienes que proceden de un delito
son sus efectos (incluidas las ganancias), y no se puede dudar de que las acciones que T recibe
provienen de una actividad delictiva, pues han sido compradas con dinero de un soborno.
Segundo, afirmada la procedencia delictuosa de los bienes o sus partes en la receptación
sustitutiva, el receptador los incorpora al circuito económico legal (expone para la venta,
ayuda a negociar, comercializa, desensambla o utiliza). En la medida en que el artículo 194
del CP exige que el bien o sus partes receptadas procedan de otro delito, su incorporación
al tráfico mercantil podría tornarse indefinida, y alteraría el normal desarrollo de las tran
sacciones comerciales, fundadas en un esencial principio de confianza. Se cumple así con el
segundo requisito.
Tercero, resulta innegable que en los casos de "receptación sustitutiva” el autor del delito
mantiene el perjuicio sufrido por el propietario o titu lar del bien o sus partes objetos del pri
mer delito, pues realiza actos que dificultarán su identificación y posterior restitución. En efec
to, tanto en la receptación "en cadena" cuanto en la "sustitutiva” el perjudicado con el primer
delito sigue sin poder recuperar su bien o sus partes.
Y cuarto: por lo dicho, dificulta o impide la restitución del bien o sus partes en cuestión.
El Decreto Legislativo 1578 publicado el 18 de octubre de 2023 modificó el art. 194 del Código
Penal, para incorporarcomo conducta típica la “comercializaciórí’y además el solo desensam
blaje o uso de un bien o sus partes cuyo origen ilícito se conocía o se podía presumir. En el texto
anterior a la modificación no se mencionaba expresamente la comercialización ni el desen-
samblaje o uso, ahora sí.
Además, antes la pena era de 1 a 4 años, ahora con la reforma es de 2 a 4 añosy se añade inha
bilitación. También se agrega un segundo párrafo castigando al que provee documentos para
ocultar el origen ilícito, con una pena de 2 a 4 años.
