de apoyo social.
5. Si se realiza en el comercio de bienes muebles al público.
6. Si se trata de gas, de hidrocarburos o de sus productos derivados.
7. Si la conducta recae sobre bienes que forman parte de la infraestructura o instalaciones públicas o privadas
para la exploración, explotación, procesamiento, refinación, almacenamiento, transporte, distribución, comer
