La pena será privativa de libertad no menor de seis ni mayor de doce años si se trata de bienes provenientes
de la comisión de los delitos de robo agravado, secuestro, extorsión, trata de personas y trabajo forzoso".
Tipicidadsubjetiva: La tipicidad subjetiva del delito de receptación del artículo 194 del CP, por
el contrario, se agota con el simple conocimiento de la realización de los elementos objetivos
del tipo, esto es, con el dolo. En tal medida, en lo que concierne a la tipicidad subjetiva se exige
únicay exclusivamente que el autor de la receptación haya conocido o haya debido presumir
la procedencia delictuosa del bien o partes del bien que adquiere, recibe en donación o en
prenda o guarda, esconde o expone a la venta o ayuda a negociar, comercializa o desensambla
o utiliza sin necesidad de que haya deseado, anhelado, pretendido, intentado, perseguido,
esperado o ansiado evitar la identificación del origen del bien o sus partes, su incautación o
decomiso.
7.9 Delito de administración fraudulenta de personas jurídicas
El mencionado ilícito es un delito contra el patrimonio en su modalidad de defraudación. Es
por ello que debe existir un engaño por parte del sujeto activo (administrador o representan
te) frente a miembros de la empresa (accionistas, contadores, otros representantes, etc.) o ter
ceros en perjuicio del patrimonio de la empresa.
Descripción normativa:
"Art. 198 C.P.- Será reprimido con pena privativa de libertad no menor de dos ni mayor de cinco años y
con ciento ochenta a trescientos sesenta y cinco días-multa, el que, ejerciendo funciones de adminis
tración o representación de una persona jurídica, realiza, en perjuicio de ella o de terceros, cualquiera de
los actos siguientes:
1. Ocultar a los accionistas, socios, asociados, auditor interno, auditor externo, según sea el caso o a terceros
interesados, la verdadera situación de la persona jurídica, falseando los balances, reflejando u omitiendo en los
mismos beneficios o pérdidas o usando cualquier artificio que suponga aumento o disminución de las partidas
contables.
2. Proporcionar datos falsos relativos a la situación de una persona jurídica.
3. Promover, por cualquier medio fraudulento, falsas cotizaciones de acciones, títulos o participaciones.
4. Aceptar, estando prohibido hacerlo, acciones o títulos de la misma persona jurídica como garantía de crédito.
5. Fraguar balances para reflejar y distribuir utilidades inexistentes.
6. Omitir comunicar al directorio, consejo de administración, consejo directivo u otro órgano similar o al auditor
interno o externo, acerca de la existencia de intereses propios que son incompatibles con los de la persona jurídica.
7. Asumir indebidamente préstamos para la persona jurídica.
8. Usar en provecho propio, o de otro, el patrimonio de la persona jurídica.
9. Utilizar cualquier documento contable que sustente operaciones inexistentes o simuladas para encubrir pagos
a favor de terceras personas naturales o jurídicas, nacionales o extranjeras.
Bien jurídico protegido: La doctrinase divide en dos posturas respecto al bien jurídico prote
gido por el delito de Administración Fraudulenta de las personas jurídicas.
56 BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DE SELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES

-- 957 of 1506 --

Tema 6: Temas de la Especialidad Penal
La primera postura sostiene que el bien jurídico es el patrimonio de la empresa. Esesenti-
do, el delito previstoen el a rt.i9 8 °del CPseráun delito de resultado porcuanto es necesa-
rloqueel patrim oniode laempresa se ve disminuido (Principiode Lesividadde los Bienes
Jurídicos).
La segunda postura sostiene que el Derecho Penal no puede proteger el patrimonio en sí,
pues cuando el delito tiene lugar el patrimonio ya se encuentra afectado. En ese sentido,
mediante el art. 198o del CP no se protege el patrimonio de la persona jurídica sino la ex
pectativa de que los directivos o administradores de una persona jurídica no abusarán o
incumplirán sus facultades de administración, perjudicando patrimonlalmente a ésta o
terceros.
Tipicidad objetiva: El delito de administración fraudulenta puede ser cometido por sus adm i
nistradores durante cualquier etapa de la empresayasea nacimiento, existencia o extinción.
El tipo penal que regula el delito de administración fraudulenta de la persona jurídica exige, de
manera general, que las acciones fraudulentas se realicen en perjuicio de la persona jurídica o
de terceros. Por ejemplo, el perjuicio en la persona jurídica se materializa en la adulteración de
los balances financieros a fin de repartir utilidades inexistentes y en el tercero frente al acreedor
que se le proporciona información falsa sobre el patrimonio de la empresa a fin de no pagar a
tiempo sus obligaciones.
El perjuicio puede tener lugar tanto cuando hay una disminución patrimonial como cuando se
ha impedido un aumento patrimonial. Por ejemplo, la disminución patrimonial se da cuando se
fragua el balance financiero de la empresa a fin de repartir utilidades Inexistentes loque produce
que el patrimonio de la empresa se reduzca debido a que se reparte lo que no se tiene. En cam
bio, se impide el aumento del patrimonio cuando se presenta Información falsa ante terceros lo
que impide el Interés de éstos en invertir en la empresa produciendo con ello que el patrimonio
de la misma no aumente. El perjuicio debe entenderse en el sentido más amplio como peligro
concreto de lesión patrimonial mas no como sólo la lesión patrimonial efectiva.
Modalidades de la administración fraudulenta:
a) La omisión de comunicar intereses incompatibles (inciso 6):
El Injusto del tipo penal se estructura sobre un deber específico derivado de la confianza
especial que recae sobre el directivo, gerente u otro funcionario que ejerce cargo de repre
sentación de la persona jurídica.
En ese sentido, esta modalidad de administración fraudulenta estará configurada como
un delito de infracción de un deber. Otro elemento objetivo del delito de este supuesto
del delito de administración fraudulenta es que los intereses del directivo tengan incom
patibilidad con los de la empresa. La incompatibilidad debe entenderse como la imposi
bilidad de poder favorecer, al mismo, tiempo los interese propios y los sociales.
b) Falsas informaciones sociales (inciso 2):
Esta modalidad consiste en proporcionar daos falsos relativos a la situación de la per
sona jurídica. La razón por la cual se criminaliza las falsas informaciones sociales radica
en el aspecto económico-patrimonial de la conducta, en la medida que la falsedad de la
BALOTAR 10 DESARROLLADO PARA LOS EXÁMENES ESCRITOS DESELECCIÓN
Y NOMBRAMIENTO DE JUECES Y FISCALES 957

-- 958 of 1506 --

información sobre la situación de la persona jurídica afecta de forma grave la toma de
decisiones de carácter económico.
Para delim itar el ámbito de aplicación del delito hay que precisar primeramente que no
se castiga el suministro de datos falsos sobre cualquier aspecto de la situación de la per
sona jurídica, sino solamente sobre la situación económica-financiera. Por ejemplo, no
se sancionará información falsa respecto a la cantidad de accionistas de la empresa o la
identidad de las mismas debido a su irrelevancia punitiva respecto a la economía de la
empresa sino solo la relacionada con la situación financiera de la empresa como la adul
teración de los estados financieros.
Debe quedar claro que no se trata de cualquier comunicación social que suministra datos
falsos, sino que el tipo penal debe limitarse a las comunicaciones sociales dirigidas a los
órganos de la propia persona jurídica o a personas vinculadas patrimonialmente ésta.
Por ejemplo, se sancionará las informaciones falsas remitidas a los directorios o junta de
accionistas (dentro de la empresa) y a los acreedores de la empresa (fuera de la empresa).
En cambio, no se sancionarán las informaciones falsas dirigidas a organismos superviso
res o de control estatal como CONASEV (empresa que regula las empresas que cotizan en
bolsa) por ser una entidad externa sin vínculo patrimonial con la empresa.
Cuando las informaciones falsas hayan sido dirigidas a la propia persona jurídica (junta de
accionistas, directorio, consejo de vigilancia, auditores, etc.) el delito se configura a partir de
la infracción de deber (veracidad). Ello, debido al cargo que ocupan estas personas dentro
de la empresay el deber que tiene frente a la misma de proporcionar información veraz so
bre su situación económica-financiera. Por ejemplo, el contador de la empresa que elabora
un estado financiero falso de la empresa (auditoria) con la finalidad de repartir utilidades
inexistes configurará un delito de infracción de deber por cuanto tenía el deber de elaborar
el referido documento en base a la real situación económica de la empresa.
Por otro lado, si el destinatario de la información es un externo a la empresa (acreedores
o terceros interesados) ya no se trata de un delito de infracción de deber, sino, más bien
de un delito de dominio. El gerente que ostenta dom inio sobre la organización de la em
presa (puede ser representante o no) al momento de proporcionar información falsa a sus
acreedores sobre la solvencia de la empresa incurre en el presente. Esto podría implicar
